CREATE OR REPLACE FUNCTION "public"."_assert_shift_places"("p_request_id" "uuid", "p_department_id" "uuid", "p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_pair text; v_id uuid; v_text text; v_has_return boolean;
begin
  foreach v_pair in array array['origin', 'destination'] loop
    if p_payload ? (v_pair || '_id') or p_payload ? (v_pair || '_text') then
      v_id := nullif(p_payload ->> (v_pair || '_id'), '')::uuid;
      v_text := nullif(btrim(coalesce(p_payload ->> (v_pair || '_text'), '')), '');
      if (v_id is null) = (v_text is null) then raise exception 'invalid_place' using errcode = 'P0001'; end if;
      if v_id is not null and not exists (select 1 from public.destinations d
        where d.id = v_id and d.department_id = p_department_id and d.is_approved) then
        raise exception 'invalid_place' using errcode = 'P0001';
      end if;
    end if;
  end loop;
  if p_payload ? 'stops' then
    select coalesce(nullif(p_payload ->> 'return_at', '')::timestamptz, q.return_at) is not null into v_has_return
    from public.requests q where q.id = p_request_id;
    begin
      perform public.replace_request_stops(p_request_id, p_department_id, coalesce(v_has_return, false), p_payload -> 'stops');
      raise exception 'stops_valid' using errcode = 'MDR99';
    exception when others then
      if sqlstate <> 'MDR99' then raise; end if;
    end;
  end if;
end;
$$;


ALTER FUNCTION "public"."_assert_shift_places"("p_request_id" "uuid", "p_department_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_authorize"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_today date := (now() at time zone 'Asia/Jerusalem')::date;
  v_dept_a uuid; v_dept_b uuid;
  v_can_manage boolean; v_member boolean; v_published boolean;
  v_blockers jsonb := '[]'::jsonb;
begin
  if p_day < p_week_start or p_day > p_week_start + 6 then
    return v_blockers || jsonb_build_array(jsonb_build_object('code', 'not_allowed', 'detail', 'day_outside_week'));
  end if;
  if p_day < v_today then
    return v_blockers || jsonb_build_array(jsonb_build_object('code', 'past', 'detail', 'day_in_the_past'));
  end if;
  if p_car_a = p_car_b then
    return v_blockers || jsonb_build_array(jsonb_build_object('code', 'not_allowed', 'detail', 'same_car'));
  end if;

  select department_id into v_dept_a from public.cars where id = p_car_a;
  select department_id into v_dept_b from public.cars where id = p_car_b;
  if v_dept_a is distinct from p_department_id or v_dept_b is distinct from p_department_id then
    return v_blockers || jsonb_build_array(jsonb_build_object('code', 'not_allowed', 'detail', 'car_wrong_department'));
  end if;

  v_can_manage := public.can_manage_week(p_department_id, p_week_start);
  v_member := public.member_of(p_department_id);
  v_published := public.is_day_public(p_department_id, p_week_start, p_day);

  if v_published then
    if not v_member then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'not_allowed', 'detail', 'not_department_member'));
    end if;
  else
    if not v_can_manage then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'not_allowed', 'detail', 'unpublished_day_sadran_only'));
    end if;
  end if;

  return v_blockers;
end $$;


ALTER FUNCTION "public"."_day_car_swap_authorize"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_day_ride_ids"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(id order by id), '{}')
  from public.rides
  where department_id = p_department_id and week_start = p_week_start
    and car_id in (p_car_a, p_car_b) and status <> 'cancelled'
    and (starts_at at time zone 'Asia/Jerusalem')::date = p_day;
$$;


ALTER FUNCTION "public"."_day_car_swap_day_ride_ids"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_expand_whole"("p_ride_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct id), '{}')
  from (
    select id from public.rides where id = any(p_ride_ids)
    union
    select id from public.rides
    where status <> 'cancelled'
      and series_id = any(public._day_car_swap_series_ids(p_ride_ids))
  ) x;
$$;


ALTER FUNCTION "public"."_day_car_swap_expand_whole"("p_ride_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_fingerprint"("p_ride_ids" "uuid"[]) RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select md5(coalesce(string_agg(id::text || ':' || version::text, ',' order by id), ''))
  from public.rides where id = any(p_ride_ids);
$$;


ALTER FUNCTION "public"."_day_car_swap_fingerprint"("p_ride_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_notices"("p_day_ride_ids" "uuid"[], "p_car_a" "uuid", "p_car_b" "uuid", "p_day" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_home uuid;
  v_dept uuid;
  v_notices jsonb := '[]'::jsonb;
  r record;
begin
  select department_id into v_dept from public.rides where id = p_day_ride_ids[1];
  if v_dept is null then
    select department_id into v_dept from public.cars where id = p_car_a;
  end if;
  select home_destination_id into v_home from public.departments where id = v_dept;

  -- last ride of the day per original car (distinct on picks the first row per car_id,
  -- i.e. the latest starts_at thanks to the order by below).
  for r in
    select distinct on (rd.car_id) rd.car_id as old_car_id, rd.destination_id, d.name as location_name,
      (case when rd.car_id = p_car_a then p_car_b else p_car_a end) as new_car_id
    from public.rides rd
    join public.destinations d on d.id = rd.destination_id
    where rd.id = any(p_day_ride_ids) and rd.status <> 'cancelled'
      and not public.ride_is_reservation(rd.id)
      and rd.car_id in (p_car_a, p_car_b)
      and (rd.starts_at at time zone 'Asia/Jerusalem')::date = p_day
    order by rd.car_id, rd.starts_at desc
  loop
    if r.destination_id is distinct from v_home then
      v_notices := v_notices || jsonb_build_array(jsonb_build_object('code', 'ends_away',
        'car_id', r.new_car_id, 'location_id', r.destination_id, 'location_name', r.location_name));
    end if;
  end loop;

  return v_notices;
end $$;


ALTER FUNCTION "public"."_day_car_swap_notices"("p_day_ride_ids" "uuid"[], "p_car_a" "uuid", "p_car_b" "uuid", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_physical_blockers"("p_ride_ids" "uuid"[], "p_car_a" "uuid", "p_car_b" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_blockers jsonb := '[]'::jsonb;
  r record;
begin
  for r in
    select leg_side,
           sum(q.adults) a, sum(q.child_seats) c, sum(q.boosters) b,
           rd.id as ride_id, rd.car_id as old_car_id,
           (case when rd.car_id = p_car_a then p_car_b else p_car_a end) as new_car_id
    from public.ride_requests rr
    join public.requests q on q.id = rr.request_id
    join public.rides rd on rd.id = rr.ride_id
    cross join lateral (values ('out'), ('return')) as legs(leg_side)
    where rd.id = any(p_ride_ids) and rd.status <> 'cancelled'
      and ((legs.leg_side = 'out' and rr.covers_out) or (legs.leg_side = 'return' and rr.covers_return))
    group by leg_side, rd.id, rd.car_id
  loop
    if not exists (select 1 from public.ride_requests x where x.ride_id = r.ride_id and x.role = 'driver') then
      r.a := r.a + 1;   -- chauffeur ride: the volunteer has no request of their own (DATA_MODEL §5.2)
    end if;
    if not public.car_fits(r.new_car_id, r.a::int, r.c::int, r.b::int) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'seats', 'ride_id', r.ride_id,
        'car_id', r.new_car_id, 'detail', format('ride %s leg %s needs (%s,%s,%s) on car %s', r.ride_id, r.leg_side, r.a, r.c, r.b, r.new_car_id)));
    end if;
  end loop;

  for r in
    select rd.id as ride_id, rd.car_id as old_car_id, rd.starts_at, rd.blocked_until,
           (case when rd.car_id = p_car_a then p_car_b else p_car_a end) as new_car_id
    from public.rides rd
    where rd.id = any(p_ride_ids) and rd.status <> 'cancelled'
  loop
    if exists (
      select 1 from public.car_maintenance_blocks mb
      where mb.car_id = r.new_car_id
        and tstzrange(mb.starts_at, mb.ends_at, '[)') && tstzrange(r.starts_at, r.blocked_until, '[)')
    ) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'maintenance', 'ride_id', r.ride_id,
        'car_id', r.new_car_id, 'detail', format('car %s has a maintenance block during ride %s', r.new_car_id, r.ride_id)));
    end if;
  end loop;

  return v_blockers;
end $$;


ALTER FUNCTION "public"."_day_car_swap_physical_blockers"("p_ride_ids" "uuid"[], "p_car_a" "uuid", "p_car_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_private_car_blockers"("p_car_a" "uuid", "p_car_b" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('code', 'private_car', 'car_id', c.id,
      'detail', format('car %s is a private car; only its owner may swap it', c.id))), '[]'::jsonb)
  from public.cars c
  where c.id in (p_car_a, p_car_b) and c.type = 'temporary' and c.owner_id is distinct from p_actor;
$$;


ALTER FUNCTION "public"."_day_car_swap_private_car_blockers"("p_car_a" "uuid", "p_car_b" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_rides_json"("p_ride_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'ride_id', rd.id, 'car_id', rd.car_id, 'starts_at', rd.starts_at, 'ends_at', rd.ends_at,
      'driver_name', p.full_name, 'label', dst.name,
      'series_id', q.series_id, 'series_index', q.series_index, 'series_count', q.series_count
    ) order by rd.starts_at), '[]'::jsonb)
  from public.rides rd
  left join public.profiles p on p.id = rd.driver_id
  left join public.destinations dst on dst.id = rd.destination_id
  left join lateral (
    select q1.series_id, q1.series_index, q1.series_count
    from public.ride_requests rr1 join public.requests q1 on q1.id = rr1.request_id
    where rr1.ride_id = rd.id and q1.series_id is not null limit 1
  ) q on true
  where rd.id = any(p_ride_ids);
$$;


ALTER FUNCTION "public"."_day_car_swap_rides_json"("p_ride_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_series_ids"("p_ride_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct q.series_id), '{}')
  from public.ride_requests rr
  join public.requests q on q.id = rr.request_id
  where rr.ride_id = any(p_ride_ids) and q.series_id is not null;
$$;


ALTER FUNCTION "public"."_day_car_swap_series_ids"("p_ride_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_series_json"("p_series_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'series_id', s.series_id, 'car_id', s.car_id, 'days', s.days,
      'first_day', s.days[1], 'last_day', s.days[array_length(s.days, 1)]
    )), '[]'::jsonb)
  from (
    select rd.series_id,
           (array_agg(rd.car_id order by rd.starts_at))[1] as car_id,
           array_agg(distinct (rd.starts_at at time zone 'Asia/Jerusalem')::date order by (rd.starts_at at time zone 'Asia/Jerusalem')::date) as days
    from public.rides rd
    where rd.series_id = any(p_series_ids) and rd.status <> 'cancelled'
    group by rd.series_id
  ) s;
$$;


ALTER FUNCTION "public"."_day_car_swap_series_json"("p_series_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_day_car_swap_split_series"("p_series_id" "uuid", "p_day" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_before_req uuid[]; v_before_ride uuid[];
  v_after_req uuid[]; v_after_ride uuid[];
  v_at_req uuid[]; v_at_ride uuid[];
  v_new_before uuid := gen_random_uuid();
  v_new_after uuid := gen_random_uuid();
  v_before_count int; v_after_count int;
begin
  select coalesce(array_agg(x.request_id order by x.day), '{}'), coalesce(array_agg(x.ride_id order by x.day), '{}')
    into v_before_req, v_before_ride
  from (
    select q.id as request_id, rr.ride_id, (rd.starts_at at time zone 'Asia/Jerusalem')::date as day
    from public.requests q
    join public.ride_requests rr on rr.request_id = q.id
    join public.rides rd on rd.id = rr.ride_id and rd.status <> 'cancelled'
    where q.series_id = p_series_id and q.status not in ('withdrawn', 'cancelled')
      and (rd.starts_at at time zone 'Asia/Jerusalem')::date < p_day
  ) x;

  select coalesce(array_agg(x.request_id order by x.day), '{}'), coalesce(array_agg(x.ride_id order by x.day), '{}')
    into v_after_req, v_after_ride
  from (
    select q.id as request_id, rr.ride_id, (rd.starts_at at time zone 'Asia/Jerusalem')::date as day
    from public.requests q
    join public.ride_requests rr on rr.request_id = q.id
    join public.rides rd on rd.id = rr.ride_id and rd.status <> 'cancelled'
    where q.series_id = p_series_id and q.status not in ('withdrawn', 'cancelled')
      and (rd.starts_at at time zone 'Asia/Jerusalem')::date > p_day
  ) x;

  select coalesce(array_agg(x.request_id), '{}'), coalesce(array_agg(x.ride_id), '{}')
    into v_at_req, v_at_ride
  from (
    select q.id as request_id, rr.ride_id
    from public.requests q
    join public.ride_requests rr on rr.request_id = q.id
    join public.rides rd on rd.id = rr.ride_id and rd.status <> 'cancelled'
    where q.series_id = p_series_id and q.status not in ('withdrawn', 'cancelled')
      and (rd.starts_at at time zone 'Asia/Jerusalem')::date = p_day
  ) x;

  v_before_count := coalesce(array_length(v_before_req, 1), 0);
  v_after_count := coalesce(array_length(v_after_req, 1), 0);

  -- the swapped day's own leg is never part of a series afterwards
  if coalesce(array_length(v_at_req, 1), 0) > 0 then
    update public.requests set series_id = null, series_index = null, series_count = null where id = any(v_at_req);
    update public.rides set series_id = null where id = any(v_at_ride);
  end if;

  if v_before_count = 1 then
    update public.requests set series_id = null, series_index = null, series_count = null where id = any(v_before_req);
    update public.rides set series_id = null where id = any(v_before_ride);
  elsif v_before_count >= 2 then
    update public.requests r set series_id = v_new_before, series_index = u.ord, series_count = v_before_count
      from unnest(v_before_req) with ordinality as u(id, ord) where r.id = u.id;
    update public.rides set series_id = v_new_before where id = any(v_before_ride);
  end if;

  if v_after_count = 1 then
    update public.requests set series_id = null, series_index = null, series_count = null where id = any(v_after_req);
    update public.rides set series_id = null where id = any(v_after_ride);
  elsif v_after_count >= 2 then
    update public.requests r set series_id = v_new_after, series_index = u.ord, series_count = v_after_count
      from unnest(v_after_req) with ordinality as u(id, ord) where r.id = u.id;
    update public.rides set series_id = v_new_after where id = any(v_after_ride);
  end if;
end $$;


ALTER FUNCTION "public"."_day_car_swap_split_series"("p_series_id" "uuid", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_merge_check"("p_ride_id" "uuid", "p_request_id" "uuid", "p_leg" "public"."ride_leg" DEFAULT 'both'::"public"."ride_leg") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_lim_min int; v_lim_km numeric;
  v_leg text; v_before numeric; v_after numeric; v_refused text; v_km_before numeric; v_km_after numeric;
  v_add_min int[] := array[0, 0]; v_add_km numeric[] := array[0, 0]; v_ix int;
  v_err text; v_start timestamptz; v_end timestamptz; v_day date; v_unknown boolean;
begin
  select * into v_ride from public.rides where id = p_ride_id;
  if v_ride.id is null then return jsonb_build_object('ok', false, 'error', 'ride_not_found'); end if;
  select coalesce(s.detour_limit_minutes, 20), coalesce(s.detour_limit_km, 15) into v_lim_min, v_lim_km
  from public.department_settings s where s.department_id = v_ride.department_id;
  v_lim_min := coalesce(v_lim_min, 20); v_lim_km := coalesce(v_lim_km, 15);

  foreach v_leg in array array['out', 'return'] loop
    continue when p_leg <> 'both' and p_leg::text <> v_leg;
    v_ix := case when v_leg = 'out' then 1 else 2 end;

    select round(extract(epoch from (max(r.eta) - min(r.eta))) / 60) into v_before
    from public._ride_route_with(p_ride_id, null, 'both') r where r.leg = v_leg::public.ride_leg;
    select round(extract(epoch from (max(r.eta) - min(r.eta))) / 60), max(r.refused) into v_after, v_refused
    from public._ride_route_with(p_ride_id, p_request_id, p_leg) r where r.leg = v_leg::public.ride_leg;
    if v_refused is not null then v_err := coalesce(v_err, v_refused); end if;

    select coalesce(sum(coalesce((select pt.distance_km from public.place_travel(x.place_id, x.next_id) pt), 0)), 0) into v_km_before
    from (select r.place_id, lead(r.place_id) over (order by r."position") as next_id
          from public._ride_route_with(p_ride_id, null, 'both') r where r.leg = v_leg::public.ride_leg) x
    where x.place_id is not null and x.next_id is not null;
    select coalesce(sum(coalesce((select pt.distance_km from public.place_travel(x.place_id, x.next_id) pt), 0)), 0) into v_km_after
    from (select r.place_id, lead(r.place_id) over (order by r."position") as next_id
          from public._ride_route_with(p_ride_id, p_request_id, p_leg) r where r.leg = v_leg::public.ride_leg) x
    where x.place_id is not null and x.next_id is not null;

    -- REQ §13.95: a free-text place on the merged route has no known travel time, so the added
    -- driving is unknown — the Sadran's judgement decides (no detour-limit refusal, no automatic
    -- window change; a payload window still applies on apply). Boarding-before-the-end still holds.
    select exists(select 1 from public._ride_route_with(p_ride_id, p_request_id, p_leg) r
                  where r.leg = v_leg::public.ride_leg and r.place_id is null) into v_unknown;
    if v_unknown then
      v_add_min[v_ix] := 0; v_add_km[v_ix] := 0;
    else
      v_add_min[v_ix] := greatest(coalesce(v_after, 0) - coalesce(v_before, 0), 0)::int;
      v_add_km[v_ix] := greatest(coalesce(v_km_after, 0) - coalesce(v_km_before, 0), 0);
      if v_err is null and (v_add_min[v_ix] > v_lim_min or v_add_km[v_ix] > v_lim_km) then v_err := 'merge_detour_too_long'; end if;
    end if;
  end loop;

  -- Window: leave earlier by the added driving out, end later by the added driving back (quarter-hour grid).
  v_day := (v_ride.starts_at at time zone 'Asia/Jerusalem')::date;
  v_start := v_ride.starts_at - make_interval(mins => (ceil(v_add_min[1] / 15.0) * 15)::int);
  v_end := v_ride.ends_at;
  if (v_end at time zone 'Asia/Jerusalem')::time = time '23:59' and v_add_min[2] > 0 then v_end := v_end + interval '1 minute'; end if;
  v_end := v_end + make_interval(mins => (ceil(v_add_min[2] / 15.0) * 15)::int);
  if v_err is null and (((v_start at time zone 'Asia/Jerusalem')::date <> v_day)
      or (((v_end - interval '1 minute') at time zone 'Asia/Jerusalem')::date <> v_day)) then
    v_err := 'ride_request_day_mismatch';
  end if;
  if (v_end at time zone 'Asia/Jerusalem')::time = time '00:00' then
    v_end := (((v_day) + time '23:59') at time zone 'Asia/Jerusalem');
  end if;

  return jsonb_build_object('ok', v_err is null, 'error', v_err,
    'added_out_minutes', v_add_min[1], 'added_return_minutes', v_add_min[2],
    'added_out_km', round(v_add_km[1], 1), 'added_return_km', round(v_add_km[2], 1),
    'starts_at', v_ride.starts_at, 'new_starts_at', v_start,
    'ends_at', v_ride.ends_at, 'new_ends_at', v_end);
end;
$$;


ALTER FUNCTION "public"."_merge_check"("p_ride_id" "uuid", "p_request_id" "uuid", "p_leg" "public"."ride_leg") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ride_route"("p_ride_id" "uuid") RETURNS TABLE("leg" "public"."ride_leg", "position" integer, "place_id" "uuid", "place_text" "text", "request_id" "uuid", "kind" "text", "eta" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select r.leg, r."position", r.place_id, r.place_text, r.request_id, r.kind, r.eta
  from public._ride_route_with(p_ride_id, null, 'both') r;
$$;


ALTER FUNCTION "public"."_ride_route"("p_ride_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ride_route_visible"("p_ride_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_ride public.rides%rowtype;
begin
  select * into v_ride from public.rides r where r.id = p_ride_id;
  if v_ride.id is null then return false; end if;
  -- service / cron callers carry no user id; same predicate as policy `rides_select` otherwise
  if (select auth.uid()) is null then return true; end if;
  return public.can_manage_week(v_ride.department_id, v_ride.week_start)
    or (public.is_approved() and v_ride.status <> 'draft'
        and public.is_day_public(v_ride.department_id, v_ride.week_start, (v_ride.starts_at at time zone 'Asia/Jerusalem')::date));
end;
$$;


ALTER FUNCTION "public"."_ride_route_visible"("p_ride_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_ride_route_with"("p_ride_id" "uuid", "p_extra_request" "uuid" DEFAULT NULL::"uuid", "p_extra_leg" "public"."ride_leg" DEFAULT 'both'::"public"."ride_leg") RETURNS TABLE("leg" "public"."ride_leg", "position" integer, "place_id" "uuid", "place_text" "text", "request_id" "uuid", "kind" "text", "eta" timestamp with time zone, "refused" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
  v_ride public.rides%rowtype;
  v_base uuid; v_out boolean; v_ret boolean;
  v_stop_min int;
  v_leg text;
  v_route jsonb; g record;
  v_board int; v_tmp record; v_refused text;
  v_n int; i int; v_t timestamptz; v_e jsonb; v_prev_id uuid; v_cur_id uuid;
  v_b_id uuid; v_b_text text; v_a_id uuid; v_a_text text; v_covers boolean;
begin
  select * into v_ride from public.rides r where r.id = p_ride_id;
  if v_ride.id is null then return; end if;
  select coalesce(ds.stop_minutes, 5) into v_stop_min from public.department_settings ds where ds.department_id = v_ride.department_id;
  v_stop_min := coalesce(v_stop_min, 5);

  select rr.request_id into v_base from public.ride_requests rr where rr.ride_id = p_ride_id
  order by (rr.role = 'driver') desc, rr.created_at, rr.request_id limit 1;

  if v_base is null then
    leg := 'out'; "position" := 0; place_id := v_ride.origin_id; place_text := null; request_id := null; kind := 'origin'; eta := v_ride.starts_at; refused := null;
    return next;
    "position" := 1; place_id := v_ride.destination_id; kind := 'destination'; eta := v_ride.ends_at;
    return next;
    return;
  end if;

  select coalesce(bool_or(rr.covers_out), false), coalesce(bool_or(rr.covers_return), false) into v_out, v_ret
  from public.ride_requests rr where rr.ride_id = p_ride_id and rr.request_id = v_base;

  foreach v_leg in array array['out', 'return'] loop
    if (v_leg = 'out' and not v_out) or (v_leg = 'return' and not v_ret) then continue; end if;

    select coalesce(jsonb_agg(jsonb_build_object('place_id', p.place_id, 'place_text', p.place_text,
        'request_id', v_base,
        'kind', case when p."position" = 0 then 'origin'
                     when p."position" = (select max(p2."position") from public.request_leg_route_points(v_base, v_leg::public.ride_leg) p2) then 'destination'
                     else 'stop' end) order by p."position"), '[]'::jsonb)
      into v_route
    from public.request_leg_route_points(v_base, v_leg::public.ride_leg) p;
    if jsonb_array_length(v_route) < 2 then continue; end if;

    v_refused := null;
    for g in
      select q.id, q.origin_id, q.origin_text, q.destination_id, q.destination_text,
             bool_or(rr.covers_out) as c_out, bool_or(rr.covers_return) as c_ret, min(rr.created_at) as first_at
      from public.ride_requests rr join public.requests q on q.id = rr.request_id
      where rr.ride_id = p_ride_id and rr.request_id <> v_base
      group by q.id, q.origin_id, q.origin_text, q.destination_id, q.destination_text
      union all
      select q.id, q.origin_id, q.origin_text, q.destination_id, q.destination_text,
             (p_extra_leg in ('out', 'both')), (p_extra_leg in ('return', 'both')), 'infinity'::timestamptz
      from public.requests q
      where q.id = p_extra_request and q.id <> v_base
        and not exists (select 1 from public.ride_requests rx where rx.ride_id = p_ride_id and rx.request_id = q.id)
      order by first_at, id
    loop
      v_covers := case when v_leg = 'out' then g.c_out else g.c_ret end;
      if not v_covers then continue; end if;
      if v_leg = 'out' then
        v_b_id := g.origin_id; v_b_text := g.origin_text; v_a_id := g.destination_id; v_a_text := g.destination_text;
      else
        v_b_id := g.destination_id; v_b_text := g.destination_text; v_a_id := g.origin_id; v_a_text := g.origin_text;
      end if;
      select * into v_tmp from public._route_add_place(v_route, v_b_id, v_b_text, g.id, 'board', 0);
      if v_tmp.o_idx < 0 then
        v_refused := coalesce(v_refused, 'merge_boards_at_end');
        continue; -- this guest is left off the route; the refusal is reported on the leg
      end if;
      v_route := v_tmp.o_route; v_board := v_tmp.o_idx;
      select * into v_tmp from public._route_add_place(v_route, v_a_id, v_a_text, g.id, 'alight', v_board);
      if v_tmp.o_idx >= 0 then v_route := v_tmp.o_route; end if;
    end loop;

    v_n := jsonb_array_length(v_route);
    if v_leg = 'out' then
      v_t := v_ride.starts_at;
      for i in 1 .. v_n loop
        v_e := v_route -> (i - 1);
        v_cur_id := nullif(v_e ->> 'place_id', '')::uuid;
        if i > 1 then
          v_t := v_t + make_interval(mins => (case when i > 2 then v_stop_min else 0 end)
            + public._route_hop_minutes(v_prev_id, v_cur_id));
        end if;
        leg := 'out'; "position" := i - 1; place_id := v_cur_id; place_text := nullif(v_e ->> 'place_text', '');
        request_id := nullif(v_e ->> 'request_id', '')::uuid; kind := v_e ->> 'kind'; eta := v_t; refused := v_refused;
        return next;
        v_prev_id := v_cur_id;
      end loop;
    else
      v_t := v_ride.ends_at;
      for i in reverse v_n .. 1 loop
        v_e := v_route -> (i - 1);
        v_cur_id := nullif(v_e ->> 'place_id', '')::uuid;
        if i < v_n then
          v_t := v_t - make_interval(mins => (case when i + 1 < v_n then v_stop_min else 0 end)
            + public._route_hop_minutes(v_cur_id, v_prev_id));
        end if;
        leg := 'return'; "position" := i - 1; place_id := v_cur_id; place_text := nullif(v_e ->> 'place_text', '');
        request_id := nullif(v_e ->> 'request_id', '')::uuid; kind := v_e ->> 'kind'; eta := v_t; refused := v_refused;
        return next;
        v_prev_id := v_cur_id;
      end loop;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_ride_route_with"("p_ride_id" "uuid", "p_extra_request" "uuid", "p_extra_leg" "public"."ride_leg") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_round_up_ride_end"("p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_end timestamptz := to_timestamp(ceil(extract(epoch from p_end) / 900) * 900);
begin
  if (v_end at time zone 'Asia/Jerusalem')::date <> (p_start at time zone 'Asia/Jerusalem')::date then
    return (((p_start at time zone 'Asia/Jerusalem')::date + time '23:59') at time zone 'Asia/Jerusalem');
  end if;
  return v_end;
end;
$$;


ALTER FUNCTION "public"."_round_up_ride_end"("p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_route_add_place"("p_route" "jsonb", "p_place_id" "uuid", "p_place_text" "text", "p_request" "uuid", "p_kind" "text", "p_after" integer, OUT "o_idx" integer, OUT "o_route" "jsonb") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  n int := jsonb_array_length(p_route);
  i int; k int; best_k int; best_cost int; cost int;
  prev_id uuid; next_id uuid;
  elem jsonb := jsonb_build_object('place_id', p_place_id, 'place_text', p_place_text,
    'request_id', p_request, 'kind', p_kind);
begin
  if p_place_id is not null then
    for i in greatest(p_after, 0) + 1 .. (case when p_kind = 'board' then n - 1 else n end) loop
      if nullif(p_route -> (i - 1) ->> 'place_id', '')::uuid = p_place_id then
        o_idx := i; o_route := p_route; return;
      end if;
    end loop;
    -- REQ §13.95: boarding where the base ride ends is no ride at all.
    if p_kind = 'board' and greatest(p_after, 0) < n
       and nullif(p_route -> (n - 1) ->> 'place_id', '')::uuid = p_place_id then
      o_idx := -1; o_route := p_route; return;
    end if;
  end if;
  for k in greatest(p_after + 1, 2) .. n loop
    prev_id := nullif(p_route -> (k - 2) ->> 'place_id', '')::uuid;
    next_id := nullif(p_route -> (k - 1) ->> 'place_id', '')::uuid;
    cost := public._route_hop_minutes(prev_id, p_place_id) + public._route_hop_minutes(p_place_id, next_id)
          - public._route_hop_minutes(prev_id, next_id);
    if best_cost is null or cost < best_cost then best_cost := cost; best_k := k; end if;
  end loop;
  if best_k is null then o_idx := -1; o_route := p_route; return; end if;
  o_route := jsonb_insert(p_route, array[(best_k - 1)::text], elem);
  o_idx := best_k;
end;
$$;


ALTER FUNCTION "public"."_route_add_place"("p_route" "jsonb", "p_place_id" "uuid", "p_place_text" "text", "p_request" "uuid", "p_kind" "text", "p_after" integer, OUT "o_idx" integer, OUT "o_route" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_route_hop_minutes"("p_from" "uuid", "p_to" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when p_from is null or p_to is null then 30
    else greatest(coalesce((select travel_minutes from public.place_travel(p_from, p_to)), 30), 0) end;
$$;


ALTER FUNCTION "public"."_route_hop_minutes"("p_from" "uuid", "p_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_shift_place_on_car"("p_proposal_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare p public.proposals%rowtype;
begin
  select * into p from public.proposals where id = p_proposal_id;
  return public.place_request_on_car(p.request_id, (p.payload ->> 'car_id')::uuid, p.created_via = 'sadran', p.created_by,
    nullif(p.payload ->> 'driver_id', '')::uuid, nullif(p.payload ->> 'depart_at', '')::timestamptz,
    nullif(p.payload ->> 'return_at', '')::timestamptz, 'PROPOSAL_APPLIED');
end;
$$;


ALTER FUNCTION "public"."_shift_place_on_car"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_ride_passengers"("p_ride_id" "uuid", "p_expected_version" integer, "p_passengers" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_actor uuid := (select auth.uid());
  v_actor_name text;
  v_destination_name text;
  v_route text;
  v_item jsonb;
  v_person_id uuid;
  v_child_id uuid;
  v_display_name text;
  v_seat_kind text;
  v_existing_person_ids uuid[];
  v_existing_child_ids uuid[];
  v_served_person_ids uuid[];
  v_served_child_ids uuid[];
  v_seen_person_ids uuid[] := '{}';
  v_seen_child_ids uuid[] := '{}';
  v_accepted jsonb[] := '{}';
  v_added_names text[] := '{}';
  v_added_person_ids uuid[] := '{}';
  v_names_joined text;
  v_existing_a int; v_existing_c int; v_existing_b int;
  v_passengers_a int; v_passengers_c int; v_passengers_b int;
  v_new_a int := 0; v_new_c int := 0; v_new_b int := 0;
  v_chauffeur_bonus int;
  v_new_version int;
begin
  select * into v_ride from public.rides where id = p_ride_id for update;
  if not found or v_ride.status = 'cancelled' then raise exception 'ride_not_found' using errcode = 'P0001'; end if;

  if not public.member_of(v_ride.department_id) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if not (public.is_week_public(v_ride.department_id, v_ride.week_start) or public.can_manage_week(v_ride.department_id, v_ride.week_start)) then
    raise exception 'ride_week_not_public' using errcode = 'P0001';
  end if;

  if p_expected_version is null or v_ride.version <> p_expected_version then
    perform public.raise_stale_version();
  end if;

  if exists (select 1 from public.weeks where department_id = v_ride.department_id and week_start = v_ride.week_start and phase = 'archived') then
    raise exception 'week_archived' using errcode = 'P0001';
  end if;

  select array_agg(person_id) filter (where person_id is not null), array_agg(child_id) filter (where child_id is not null)
    into v_existing_person_ids, v_existing_child_ids
  from public.ride_passengers where ride_id = p_ride_id;

  select array_agg(distinct x) into v_served_person_ids
  from (
    select q.requester_id as x
    from public.ride_requests rr join public.requests q on q.id = rr.request_id
    where rr.ride_id = p_ride_id and q.requester_id is not null
    union
    select rc.profile_id as x
    from public.request_companions rc join public.ride_requests rr on rr.request_id = rc.request_id
    where rr.ride_id = p_ride_id
  ) served;

  select array_agg(distinct rc.child_id) into v_served_child_ids
  from public.request_children rc join public.ride_requests rr on rr.request_id = rc.request_id
  where rr.ride_id = p_ride_id;

  select coalesce(sum(case when seat_kind = 'adult' then 1 else 0 end), 0),
         coalesce(sum(case when seat_kind = 'child_seat' then 1 else 0 end), 0),
         coalesce(sum(case when seat_kind = 'booster' then 1 else 0 end), 0)
    into v_passengers_a, v_passengers_c, v_passengers_b
  from public.ride_passengers where ride_id = p_ride_id;

  select coalesce(sum(q.adults), 0), coalesce(sum(q.child_seats), 0), coalesce(sum(q.boosters), 0)
    into v_existing_a, v_existing_c, v_existing_b
  from public.ride_requests rr join public.requests q on q.id = rr.request_id
  where rr.ride_id = p_ride_id;

  v_chauffeur_bonus := case when v_ride.driver_id is not null
    and not exists (select 1 from public.ride_requests rr where rr.ride_id = p_ride_id and rr.role = 'driver')
    then 1 else 0 end;

  -- Validate every row and decide what to actually insert before writing anything —
  -- an invalid row anywhere in the payload rejects the whole call, but a merely-duplicate
  -- one is quietly dropped from the accepted set instead.
  for v_item in select * from jsonb_array_elements(coalesce(p_passengers, '[]'::jsonb))
  loop
    v_person_id := nullif(v_item ->> 'person_id', '')::uuid;
    v_child_id := nullif(v_item ->> 'child_id', '')::uuid;
    v_display_name := nullif(trim(coalesce(v_item ->> 'display_name', '')), '');
    v_seat_kind := v_item ->> 'seat_kind';

    if v_person_id is not null and v_child_id is not null then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_display_name is null then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_seat_kind not in ('adult', 'child_seat', 'booster') then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;

    if v_person_id is not null then
      if not exists (
        select 1 from public.profiles p join public.department_members dm on dm.profile_id = p.id
        where p.id = v_person_id and p.approval_status = 'approved'
          and dm.department_id = v_ride.department_id and dm.removed_at is null
      ) then
        raise exception 'invalid_ride_passenger' using errcode = 'P0001';
      end if;
      if v_person_id = any(coalesce(v_existing_person_ids, '{}'::uuid[]))
        or v_person_id = any(v_seen_person_ids)
        or v_person_id = any(coalesce(v_served_person_ids, '{}'::uuid[]))
      then
        continue;
      end if;
      v_seen_person_ids := v_seen_person_ids || v_person_id;
    elsif v_child_id is not null then
      if not exists (select 1 from public.children c where c.id = v_child_id and c.department_id = v_ride.department_id) then
        raise exception 'invalid_ride_passenger' using errcode = 'P0001';
      end if;
      if v_child_id = any(coalesce(v_existing_child_ids, '{}'::uuid[]))
        or v_child_id = any(v_seen_child_ids)
        or v_child_id = any(coalesce(v_served_child_ids, '{}'::uuid[]))
      then
        continue;
      end if;
      v_seen_child_ids := v_seen_child_ids || v_child_id;
    end if;

    case v_seat_kind
      when 'adult' then v_new_a := v_new_a + 1;
      when 'child_seat' then v_new_c := v_new_c + 1;
      when 'booster' then v_new_b := v_new_b + 1;
    end case;

    v_accepted := v_accepted || jsonb_build_object(
      'person_id', v_person_id, 'child_id', v_child_id, 'display_name', v_display_name, 'seat_kind', v_seat_kind);
  end loop;

  if not public.car_fits(v_ride.car_id,
       v_existing_a + v_chauffeur_bonus + v_passengers_a + v_new_a,
       v_existing_c + v_passengers_c + v_new_c,
       v_existing_b + v_passengers_b + v_new_b)
  then
    raise exception 'ride_seats_exceeded' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'add_ride_passengers', true);

  for v_item in select * from unnest(v_accepted)
  loop
    insert into public.ride_passengers (ride_id, department_id, week_start, person_id, child_id, display_name, seat_kind, added_by)
    values (p_ride_id, v_ride.department_id, v_ride.week_start,
      nullif(v_item ->> 'person_id', '')::uuid, nullif(v_item ->> 'child_id', '')::uuid,
      v_item ->> 'display_name', v_item ->> 'seat_kind', v_actor);
    v_added_names := v_added_names || (v_item ->> 'display_name');
    if nullif(v_item ->> 'person_id', '') is not null then
      v_added_person_ids := v_added_person_ids || (v_item ->> 'person_id')::uuid;
    end if;
  end loop;

  update public.rides set updated_at = now() where id = p_ride_id
  returning version into v_new_version;

  if array_length(v_added_names, 1) > 0 and v_ride.driver_id is distinct from v_actor then
    select full_name into v_actor_name from public.profiles where id = v_actor;
    select name into v_destination_name from public.destinations where id = v_ride.destination_id;
    v_route := public.route_label(v_ride.department_id, v_ride.origin_id, null, v_ride.destination_id, null);
    v_names_joined := array_to_string(v_added_names, ', ');
    perform public.enqueue_notification(v_ride.driver_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
      jsonb_build_object('byName', coalesce(v_actor_name, ''), 'names', v_names_joined, 'destination', coalesce(v_destination_name, ''), 'route', coalesce(v_route, '')),
      jsonb_build_object('variant', 'passengers_added', 'ride_id', p_ride_id),
      format('passengers_added:%s:%s:%s', p_ride_id, v_new_version, v_ride.driver_id));
  end if;

  -- Owner decision 2026-09-14, rule 3: each added *member* (person_id) is told individually
  -- too, not only the driver — a free-text guest or a named child has no account to notify.
  if array_length(v_added_person_ids, 1) > 0 then
    if v_actor_name is null then
      select full_name into v_actor_name from public.profiles where id = v_actor;
    end if;
    select name into v_destination_name from public.destinations where id = v_ride.destination_id;
    v_route := public.route_label(v_ride.department_id, v_ride.origin_id, null, v_ride.destination_id, null);
    for v_person_id in select unnest(v_added_person_ids) loop
      if v_person_id is distinct from v_actor then
        perform public.enqueue_notification(v_person_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
          jsonb_build_object('byName', coalesce(v_actor_name, ''), 'destination', coalesce(v_destination_name, ''), 'route', coalesce(v_route, '')),
          jsonb_build_object('variant', 'passenger_added_you', 'ride_id', p_ride_id),
          format('passenger_added_you:%s:%s:%s', p_ride_id, v_new_version, v_person_id));
      end if;
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "public"."add_ride_passengers"("p_ride_id" "uuid", "p_expected_version" integer, "p_passengers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_member"("p_profile_id" "uuid", "p_department_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;
  perform set_config('app.audit_reason', 'admin_approve_member', true);
  update public.profiles set approval_status='approved', approved_at=coalesce(approved_at,now()),
    default_department_id=coalesce(default_department_id,p_department_id) where id=p_profile_id;
  if not found then raise exception 'member_not_found'; end if;
  insert into public.department_members(department_id,profile_id,added_by)
    values(p_department_id,p_profile_id,auth.uid())
    on conflict(department_id,profile_id) do update set removed_at=null;
end;
$$;


ALTER FUNCTION "public"."admin_approve_member"("p_profile_id" "uuid", "p_department_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_sadran_assignments"("p_department_id" "uuid", "p_profile_ids" "uuid"[], "p_week_start" "date" DEFAULT NULL::"date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;
  -- One department lock serializes overlapping replacements, including initially empty rosters.
  perform 1 from public.departments where id=p_department_id for update;
  if not found then raise exception 'not_authorized'; end if;
  if p_profile_ids is null or (p_week_start is not null and extract(dow from p_week_start)<>0) then
    raise exception 'invalid_roster';
  end if;
  perform 1 from public.department_members dm join public.profiles p on p.id=dm.profile_id
    where dm.department_id=p_department_id and dm.profile_id=any(p_profile_ids) for update of dm, p;
  if exists(select 1 from unnest(p_profile_ids) selected(id) where not exists(
    select 1 from public.department_members dm join public.profiles p on p.id=dm.profile_id
    where dm.department_id=p_department_id and dm.profile_id=selected.id
      and dm.removed_at is null and p.approval_status='approved'
  )) then raise exception 'not_authorized'; end if;
  perform set_config('app.audit_reason', 'admin_set_sadran_assignments', true);
  if p_week_start is null then
    -- The permanent pool editor changes roles; assigning a particular week never does.
    update public.department_members set role='member'
      where department_id=p_department_id and role='sadran' and not(profile_id=any(p_profile_ids));
    update public.department_members set role='sadran'
      where department_id=p_department_id and profile_id=any(p_profile_ids) and role<>'sadran';
  end if;
  delete from public.sadran_assignments where department_id=p_department_id
    and week_start is not distinct from p_week_start and not(profile_id=any(p_profile_ids));
  insert into public.sadran_assignments(department_id,profile_id,week_start,assigned_by)
    select p_department_id,id,p_week_start,auth.uid() from (select distinct unnest(p_profile_ids) id) selected
    where not exists(select 1 from public.sadran_assignments sa where sa.department_id=p_department_id
      and sa.week_start is not distinct from p_week_start and sa.profile_id=selected.id);
end;
$$;


ALTER FUNCTION "public"."admin_set_sadran_assignments"("p_department_id" "uuid", "p_profile_ids" "uuid"[], "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_member"("p_profile_id" "uuid", "p_details" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare dept uuid:=nullif(p_details->>'department_id','')::uuid;
  removed uuid[]:=array(select value::uuid from jsonb_array_elements_text(coalesce(p_details->'removed_department_ids','[]'::jsonb)));
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;
  perform 1 from public.profiles where id=p_profile_id for update;
  if not found then raise exception 'member_not_found'; end if;
  if not (p_details ? 'display_name') and nullif(trim(p_details->>'full_name'),'') is null then
    raise exception 'invalid_member_name';
  end if;
  if dept is not null then
    perform 1 from public.departments where id=dept and is_active for share;
    if not found or dept=any(removed) then raise exception 'not_authorized'; end if;
  end if;
  perform set_config('app.audit_reason','admin_update_member',true);
  if p_details ? 'display_name' then
    update public.profiles set display_name=nullif(trim(p_details->>'display_name'),''),
      phone=nullif(trim(p_details->>'phone'),'') where id=p_profile_id;
  else
    update public.profiles set full_name=trim(p_details->>'full_name'),phone=nullif(trim(p_details->>'phone'),'') where id=p_profile_id;
  end if;
  if p_details ? 'does_not_drive' then
    update public.profiles set does_not_drive=(p_details->>'does_not_drive')::boolean where id=p_profile_id;
  end if;
  update public.department_members set removed_at=now(),role='member'
    where profile_id=p_profile_id and department_id=any(removed) and removed_at is null;
  if dept is not null then
    insert into public.department_members(department_id,profile_id,added_by)
      values(dept,p_profile_id,auth.uid()) on conflict(department_id,profile_id) do update
      set removed_at=null,role=case when department_members.removed_at is not null then 'member'::public.role else department_members.role end;
  end if;
  update public.profiles p set default_department_id=(
    select dm.department_id from public.department_members dm join public.departments d on d.id=dm.department_id
    where dm.profile_id=p.id and dm.removed_at is null and d.is_active
    order by (dm.department_id=dept) desc,dm.created_at,dm.department_id limit 1)
  where p.id=p_profile_id and not exists(select 1 from public.department_members dm join public.departments d on d.id=dm.department_id
    where dm.profile_id=p.id and dm.department_id=p.default_department_id and dm.removed_at is null and d.is_active);
end $$;


ALTER FUNCTION "public"."admin_update_member"("p_profile_id" "uuid", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_week_phases"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count int := 0;
  v_n int;
  v_dept record;
  v_week record;
  v_archived record;
begin
  for v_dept in select id from public.departments where is_active loop
    v_count := v_count + public.materialize_department_weeks(v_dept.id, p_now);
  end loop;

  update public.weeks set phase = 'open' where phase = 'upcoming' and open_at <= p_now;
  get diagnostics v_n = row_count;
  v_count := v_count + v_n;

  for v_week in select * from public.weeks where phase = 'open' and close_at <= p_now loop
    update public.weeks set phase = 'solving' where department_id = v_week.department_id and week_start = v_week.week_start;
    perform public.enqueue_notification(s.profile_id, 'window_closed_solve_now', v_week.department_id, v_week.week_start,
      '{}'::jsonb, '{}'::jsonb, format('window_closed_solve_now:%s:%s', v_week.department_id, v_week.week_start))
    from public.sadranim_of(v_week.department_id, v_week.week_start) as s(profile_id);
    v_count := v_count + 1;
  end loop;

  for v_archived in
    update public.weeks set phase = 'archived'
    where phase in ('published', 'live') and (week_start + 7) <= (p_now at time zone 'Asia/Jerusalem')::date
    returning department_id, week_start
  loop
    perform public.compute_week_stats(v_archived.department_id, v_archived.week_start);
  end loop;

  update public.weeks set phase = 'live'
  where phase = 'published' and week_start <= ((p_now at time zone 'Asia/Jerusalem')::date - extract(dow from p_now at time zone 'Asia/Jerusalem')::int);

  return v_count;
end;
$$;


ALTER FUNCTION "public"."advance_week_phases"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."answer_proposal"("p_token" "text", "p_accept" boolean, "p_note" "text" DEFAULT NULL::"text", "p_via" "public"."answer_channel" DEFAULT 'token'::"public"."answer_channel") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_hash text := encode(digest(p_token, 'sha256'), 'hex');
  v_proposal record;
  v_party record;
  v_requester_id uuid;
begin
  perform 1 from public.requests q where q.id in (
    select p.request_id from public.proposals p where p.token_hash=v_hash
    union select p.request_id from public.proposal_parties pp join public.proposals p on p.id=pp.proposal_id where pp.token_hash=v_hash
  ) order by q.id for update;
  select * into v_proposal from public.proposals where token_hash = v_hash;
  if v_proposal.id is not null then
    if v_proposal.status <> 'sent' then raise exception 'proposal_not_answerable' using errcode = 'P0001'; end if;
    if now() > v_proposal.expires_at then raise exception 'proposal_expired' using errcode = 'P0001'; end if;

    select requester_id into v_requester_id from public.requests where id = v_proposal.request_id;
    perform set_config('app.audit_reason', 'answer_proposal', true);

    update public.proposal_parties set response = (case when p_accept then 'accepted' else 'declined' end)::public.party_response,
      responded_at = now(), responded_via = p_via, responded_by = v_requester_id
    where proposal_id = v_proposal.id and profile_id = v_requester_id;

    update public.proposals set answered_by = v_requester_id, answered_at = now(), answered_via = p_via, answer_note = p_note
    where id = v_proposal.id;

    return jsonb_build_object('proposal_id', v_proposal.id, 'accepted', p_accept);
  end if;

  select pp.*, p.status as proposal_status, p.expires_at as proposal_expires_at, p.id as proposal_id
    into v_party
  from public.proposal_parties pp join public.proposals p on p.id = pp.proposal_id
  where pp.token_hash = v_hash;
  if v_party.proposal_id is null then raise exception 'invalid_token' using errcode = 'P0001'; end if;
  if v_party.proposal_status <> 'sent' then raise exception 'proposal_not_answerable' using errcode = 'P0001'; end if;
  if now() > v_party.proposal_expires_at then raise exception 'proposal_expired' using errcode = 'P0001'; end if;

  perform set_config('app.audit_reason', 'answer_proposal', true);
  update public.proposal_parties set response = (case when p_accept then 'accepted' else 'declined' end)::public.party_response,
    responded_at = now(), responded_via = p_via, responded_by = v_party.profile_id
  where id = v_party.id;

  update public.proposals set answered_by = v_party.profile_id, answered_at = now(), answered_via = p_via, answer_note = p_note
  where id = v_party.proposal_id and answered_by is null;

  return jsonb_build_object('proposal_id', v_party.proposal_id, 'accepted', p_accept);
end;
$$;


ALTER FUNCTION "public"."answer_proposal"("p_token" "text", "p_accept" boolean, "p_note" "text", "p_via" "public"."answer_channel") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_proposal"("p_proposal_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_prop record;
  v_req record;
  v_ride_id uuid;
  v_leg jsonb;
  v_has_driver_leg boolean;
  v_is_auto_apply boolean;
  v_existing public.rides%rowtype;
  v_old record;
  v_home uuid;
  host public.rides%rowtype;
  required_party uuid;
  combined_start timestamptz;combined_end timestamptz;
  route_before jsonb:='{}'::jsonb;
  v_has_places boolean; route_old int; route_new int; shift_start timestamptz; shift_end timestamptz;
  gap_override smallint;
  v_origin_result jsonb;
  v_leg_txt text;
begin
  select * into v_prop from public.proposals where id = p_proposal_id for update;
  if v_prop is null then raise exception 'proposal_not_found' using errcode = 'P0001'; end if;

  v_is_auto_apply := coalesce(current_setting('app.auto_applying_proposal', true), '') = 'on';
  if not v_is_auto_apply and not public.can_manage_week(v_prop.department_id, v_prop.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if v_prop.status <> 'accepted' then raise exception 'proposal_not_accepted' using errcode = 'P0001'; end if;

  select * into v_req from public.requests where id = v_prop.request_id for update;
  select home_destination_id into v_home from public.departments where id=v_prop.department_id;
  perform set_config('app.audit_reason', 'apply_proposal', true);
  perform set_config('app.system_status_transition', 'on', true);

  if v_prop.type = 'deny' then
    update public.requests set status = 'denied', status_reason = coalesce(v_prop.payload ->> 'reason', 'DENIED_BY_SADRAN')
    where id = v_prop.request_id;
  elsif v_prop.type = 'external' then
    update public.requests set status = 'external', status_reason = coalesce(v_prop.payload ->> 'reason', 'EXTERNAL')
    where id = v_prop.request_id;
  elsif v_prop.type = 'origin' then
    update public.requests set
      origin_id = (v_prop.payload ->> 'origin_id')::uuid, origin_text = null,
      preferred_car_id = (v_prop.payload ->> 'car_id')::uuid,
      status = 'submitted'
    where id = v_prop.request_id;
    v_origin_result := public.try_auto_approve(v_prop.request_id);
    if coalesce(v_origin_result ->> 'status', '') <> 'assigned' then
      raise exception 'origin_change_unavailable' using errcode = 'P0001';
    end if;
    v_ride_id := (v_origin_result ->> 'ride_id')::uuid;
  elsif v_prop.type = 'shift' then
    v_has_places := v_prop.payload ? 'origin_id' or v_prop.payload ? 'origin_text' or v_prop.payload ? 'destination_id'
      or v_prop.payload ? 'destination_text' or v_prop.payload ? 'stops';
    if v_has_places then
      perform public._assert_shift_places(v_req.id, v_req.department_id, v_prop.payload);
      route_old := (case when v_req.depart_at is not null then coalesce(public.request_leg_route_minutes(v_req.id,'out'),0) else 0 end)
        + (case when v_req.return_at is not null then coalesce(public.request_leg_route_minutes(v_req.id,'return'),0) else 0 end);
      update public.requests set
        origin_id = case when v_prop.payload ? 'origin_id' or v_prop.payload ? 'origin_text' then nullif(v_prop.payload ->> 'origin_id','')::uuid else origin_id end,
        origin_text = case when v_prop.payload ? 'origin_id' or v_prop.payload ? 'origin_text' then nullif(btrim(coalesce(v_prop.payload ->> 'origin_text','')),'') else origin_text end,
        destination_id = case when v_prop.payload ? 'destination_id' or v_prop.payload ? 'destination_text' then nullif(v_prop.payload ->> 'destination_id','')::uuid else destination_id end,
        destination_text = case when v_prop.payload ? 'destination_id' or v_prop.payload ? 'destination_text' then nullif(btrim(coalesce(v_prop.payload ->> 'destination_text','')),'') else destination_text end
      where id = v_req.id;
      if v_prop.payload ? 'stops' then
        perform public.replace_request_stops(v_req.id, v_req.department_id,
          coalesce(nullif(v_prop.payload ->> 'return_at','')::timestamptz, v_req.return_at) is not null, v_prop.payload -> 'stops');
      end if;
      select * into v_req from public.requests where id = v_prop.request_id;
      route_new := (case when v_req.depart_at is not null then coalesce(public.request_leg_route_minutes(v_req.id,'out'),0) else 0 end)
        + (case when v_req.return_at is not null then coalesce(public.request_leg_route_minutes(v_req.id,'return'),0) else 0 end);
    end if;
    if v_prop.payload ? 'car_id' and v_req.trip_type is distinct from 'round_trip' then
      -- REQ §13.94: one_way / drop_off place on the named car by trip type (_shift_place_on_car).
      v_ride_id := public._shift_place_on_car(v_prop.id);
    elsif v_prop.payload ? 'car_id' then
      select rd.* into v_existing from public.rides rd join public.ride_requests rr on rr.ride_id=rd.id
      where rr.request_id=v_req.id and rr.role='driver' and rd.status<>'cancelled' order by rd.starts_at limit 1 for update of rd;
      shift_start := coalesce((v_prop.payload->>'depart_at')::timestamptz, v_existing.starts_at, v_req.depart_at);
      shift_end := coalesce((v_prop.payload->>'return_at')::timestamptz, v_existing.ends_at, v_req.return_at);
      if v_has_places and not (v_prop.payload ? 'return_at') and v_existing.id is not null and coalesce(route_new,0) > coalesce(route_old,0) then
        shift_end := public._round_up_ride_end(shift_start, shift_end + make_interval(mins => route_new - route_old));
      end if;
      if v_prop.created_via='sadran' then
        gap_override:=public.prepare_manual_ride_window((v_prop.payload->>'car_id')::uuid,v_prop.week_start,shift_start,shift_end,v_existing.id);
      end if;
      if v_existing.id is not null then
        if v_prop.created_via<>'sadran' and exists(select 1 from public.ride_requests rr where rr.ride_id=v_existing.id and rr.request_id<>v_req.id) then raise exception 'shared_ride_requires_sadran'; end if;
        update public.rides set turnaround_override_minutes=gap_override,car_id=(v_prop.payload->>'car_id')::uuid,
          starts_at=shift_start,
          ends_at=shift_end,
          is_pinned=true,pin_reason='PROPOSAL_APPLIED' where id=v_existing.id returning id into v_ride_id;
      else
        insert into public.rides(department_id,week_start,car_id,starts_at,ends_at,origin_id,destination_id,driver_id,status,is_pinned,pin_reason,created_by,turnaround_override_minutes)
        values(v_prop.department_id,v_prop.week_start,(v_prop.payload->>'car_id')::uuid,
          shift_start,shift_end,
          coalesce((v_prop.payload->>'origin_id')::uuid,v_req.origin_id,v_home),coalesce((v_prop.payload->>'destination_id')::uuid,v_req.origin_id,v_home),v_req.requester_id,
          case when public.is_week_public(v_prop.department_id,v_prop.week_start) then 'confirmed'::public.ride_status else 'draft'::public.ride_status end,
          true,'PROPOSAL_APPLIED',v_prop.created_by,gap_override) returning id into v_ride_id;
        insert into public.ride_requests(ride_id,request_id,role,leg,car_mode) values(v_ride_id,v_req.id,'driver','both','keep');
      end if;
      update public.requests set status='assigned',status_reason='PROPOSAL_APPLIED' where id=v_req.id;
      perform public.assert_ride_request_day(v_ride_id);
      perform public.assert_ride_seats_fit(v_ride_id);
      perform public.assert_car_chain((v_prop.payload->>'car_id')::uuid,v_prop.week_start);
      if v_existing.car_id is not null and v_existing.car_id<>(v_prop.payload->>'car_id')::uuid then perform public.assert_car_chain(v_existing.car_id,v_prop.week_start); end if;
    else
      update public.requests set
        depart_at = coalesce((v_prop.payload ->> 'depart_at')::timestamptz, depart_at),
        return_at = coalesce((v_prop.payload ->> 'return_at')::timestamptz, return_at),
        trip_shape = coalesce((v_prop.payload ->> 'trip_shape')::public.trip_shape, trip_shape),
        needs_car_at_destination = coalesce((v_prop.payload ->> 'needs_car_at_destination')::boolean, needs_car_at_destination),
        status = 'submitted', status_reason = 'PROPOSAL_APPLIED_PENDING_ASSIGNMENT'
      where id = v_prop.request_id;
    end if;
  elsif v_prop.type = 'merge' then
    if not exists(select 1 from public.proposal_parties where proposal_id=v_prop.id and profile_id=v_req.requester_id and response='accepted')
      or exists(select 1 from public.proposal_parties where proposal_id=v_prop.id and response<>'accepted') then raise exception 'proposal_consent_required'; end if;
    if v_prop.payload ? 'request_fingerprint' and v_prop.payload->>'request_fingerprint' is distinct from public.merge_request_fingerprint(v_req.id) then perform public.raise_stale_version(); end if;
    for host in select * from public.rides where id in(select (value->>'ride_id')::uuid from jsonb_array_elements(coalesce(v_prop.payload->'legs','[]'))) order by id for update loop
      if host.department_id<>v_prop.department_id or host.week_start<>v_prop.week_start or host.status='cancelled' then raise exception 'ride_not_found'; end if;
      if v_prop.payload ? 'host_versions' and host.version is distinct from (v_prop.payload->'host_versions'->>host.id::text)::int then perform public.raise_stale_version(); end if;
      for required_party in select host.driver_id where host.driver_id is not null union select q.requester_id from public.ride_requests rr join public.requests q on q.id=rr.request_id where rr.ride_id=host.id loop
        if not exists(select 1 from public.proposal_parties where proposal_id=v_prop.id and profile_id=required_party and response='accepted') then raise exception 'proposal_consent_required'; end if;
      end loop;
    end loop;
    if exists(select 1 from jsonb_each_text(coalesce(v_prop.payload->'source_versions','{}')) expected left join public.rides r on r.id=expected.key::uuid
      where r.version is distinct from expected.value::int or r.status='cancelled') then perform public.raise_stale_version(); end if;
    -- Replace the request's prior solo assignment; do not leave a duplicate driver leg.
    for v_old in select rd.* from public.rides rd join public.ride_requests rr on rr.ride_id=rd.id
      where rr.request_id=v_req.id and rd.status<>'cancelled' and not exists(
        select 1 from jsonb_array_elements(coalesce(v_prop.payload->'legs','[]')) desired_leg(value) where (desired_leg.value->>'ride_id')::uuid=rd.id
      ) order by rd.id for update of rd loop
      if v_old.driver_id=v_req.requester_id or (v_old.needs_driver and not exists(select 1 from public.ride_requests where ride_id=v_old.id and request_id<>v_req.id)) then
        if exists(select 1 from public.ride_requests where ride_id=v_old.id and request_id<>v_req.id) or v_old.origin_id<>v_old.destination_id then raise exception 'shared_ride_requires_sadran'; end if;
        update public.rides set status='cancelled',cancelled_at=now(),cancelled_by=v_req.requester_id,cancel_reason='MERGED_BY_CONSENT' where id=v_old.id;
      end if;
      delete from public.ride_requests where ride_id=v_old.id and request_id=v_req.id;
      perform public.assert_car_chain(v_old.car_id,v_old.week_start);
    end loop;
    -- REQ §13.95 H1: validity + added driving of every host before the guest boards.
    for host in select * from public.rides where id in(select (value->>'ride_id')::uuid from jsonb_array_elements(coalesce(v_prop.payload->'legs','[]'))) order by id loop
      select case when count(distinct coalesce(l->>'leg','both'))>1 or bool_or(coalesce(l->>'leg','both')='both') then 'both'
                  else max(coalesce(l->>'leg','both')) end into v_leg_txt
      from jsonb_array_elements(coalesce(v_prop.payload->'legs','[]')) l where (l->>'ride_id')::uuid=host.id and coalesce(l->>'role','passenger')<>'driver';
      if v_leg_txt is not null then
        route_before:=route_before||jsonb_build_object(host.id::text,public._merge_check(host.id,v_req.id,v_leg_txt::public.ride_leg));
        if not ((route_before->host.id::text->>'ok')::boolean) then raise exception '%',route_before->host.id::text->>'error' using errcode='P0001'; end if;
      end if;
    end loop;
    v_has_driver_leg := false;
    for v_leg in select * from jsonb_array_elements(coalesce(v_prop.payload -> 'legs', '[]')) loop
      v_ride_id := (v_leg ->> 'ride_id')::uuid;
      insert into public.ride_requests (ride_id, request_id, role, leg, car_mode, detour_minutes)
      values (v_ride_id, v_prop.request_id, coalesce((v_leg ->> 'role')::public.ride_role, 'passenger'),
        coalesce((v_leg ->> 'leg')::public.ride_leg, 'both'), (v_leg ->> 'car_mode')::public.leg_car_mode,
        coalesce((v_prop.payload ->> 'detour_minutes')::smallint, 0))
      on conflict (ride_id, request_id, leg) do update set car_mode = excluded.car_mode;
      update public.rides set is_pinned = true, pin_reason = 'PROPOSAL_APPLIED' where id = v_ride_id;
      if (v_leg ->> 'role') = 'driver' then
        v_has_driver_leg := true;
      end if;
    end loop;
    for host in select * from public.rides where id in(select (value->>'ride_id')::uuid from jsonb_array_elements(coalesce(v_prop.payload->'legs','[]'))) order by id for update loop
      -- A legacy payload window (`starts_at`/`ends_at`, the consented "expanded merge") still widens the host;
      -- the route extension (start earlier / end later, REQ §13.95) is applied on top of it.
      combined_start:=least(host.starts_at,coalesce((v_prop.payload->>'starts_at')::timestamptz,host.starts_at));
      combined_end:=greatest(host.ends_at,coalesce((v_prop.payload->>'ends_at')::timestamptz,host.ends_at));
      if route_before ? host.id::text then
        combined_start:=least(combined_start,(route_before->host.id::text->>'new_starts_at')::timestamptz);
        combined_end:=greatest(combined_end,(route_before->host.id::text->>'new_ends_at')::timestamptz);
      end if;
      if combined_end>host.ends_at or combined_start<host.starts_at then
        gap_override:=host.turnaround_override_minutes;
        if v_prop.created_via='sadran' and coalesce((v_prop.payload->>'allow_tight_turnaround')::boolean,false) then
          gap_override:=public.prepare_manual_ride_window(host.car_id,host.week_start,combined_start,combined_end,host.id);
        end if;
        update public.rides set starts_at=combined_start,ends_at=combined_end,turnaround_override_minutes=gap_override where id=host.id;
      end if;
      perform public.assert_ride_request_day(host.id);
      perform public.assert_ride_seats_fit(host.id);
      perform public.assert_car_chain(host.car_id,host.week_start);
    end loop;
    update public.requests set status = (case when exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=v_req.id and r.needs_driver and r.status<>'cancelled') then 'waitlisted' when v_has_driver_leg then 'assigned' else 'merged' end)::public.request_status,
      status_reason = case when exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=v_req.id and r.needs_driver and r.status<>'cancelled') then 'UNMET_NEEDS_DRIVER' else 'PROPOSAL_APPLIED' end
    where id = v_prop.request_id;
  end if;

  perform set_config('app.system_status_transition', 'off', true);

  update public.proposals set status = 'applied', applied_at = now(), applied_ride_id = v_ride_id where id = p_proposal_id;

  perform public.enqueue_notification(v_req.requester_id, 'outcome_changed', v_prop.department_id, v_prop.week_start,
    '{}'::jsonb, jsonb_build_object('request_id', v_prop.request_id), format('outcome_changed:%s:%s', v_prop.request_id, p_proposal_id));

  if v_prop.type='merge' then
    perform public.enqueue_notification(pp.profile_id,'outcome_changed',v_prop.department_id,v_prop.week_start,'{}',jsonb_build_object('request_id',v_req.id,'ride_id',v_ride_id),format('merge_applied:%s:%s',v_prop.id,pp.profile_id))
    from public.proposal_parties pp where pp.proposal_id=v_prop.id and pp.profile_id<>v_req.requester_id;
  end if;
  return v_ride_id;
end;
$$;


ALTER FUNCTION "public"."apply_proposal"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_solver_result"("p_department_id" "uuid", "p_week_start" "date", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run_id uuid;
  v_ride jsonb;
  v_served jsonb;
  v_ride_id uuid;
  v_status jsonb;
  v_touched_cars uuid[] := '{}';
  v_input_hash text := p_payload ->> 'input_hash';
  v_preview record;
  v_preview_found boolean := false;
  v_current_fingerprint text;
  v_mode text := coalesce(p_payload ->> 'mode', 'full');
  v_existing_count int;
  v_deleted int := 0;
  v_inserted int := 0;
  v_unassigned uuid[] := '{}';
  v_series_id uuid;
  v_skipped jsonb := '[]'::jsonb;
  v_series record;
  v_lost uuid[] := '{}';
  v_unplaced int := 0;
  v_doomed_rides uuid[] := '{}';
  v_kept_rides uuid[] := '{}';
  v_prop_id uuid;
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'apply_solver_result', true);

  if v_input_hash is not null then
    select * into v_preview from public.solver_runs
    where department_id = p_department_id and week_start = p_week_start
      and input_hash = v_input_hash and applied = false
    order by started_at desc limit 1;
    v_preview_found := found;

    if v_preview_found and v_preview.state_fingerprint is not null then
      v_current_fingerprint := public.week_state_fingerprint(p_department_id, p_week_start);
      if v_current_fingerprint <> v_preview.state_fingerprint then
        raise exception 'stale_input' using errcode = 'P0409';
      end if;
    end if;
  end if;

  select count(*) into v_existing_count
  from public.rides where department_id = p_department_id and week_start = p_week_start and status <> 'cancelled';

  insert into public.solver_runs (department_id, week_start, policy_version_id, input_hash, solver_version,
    status, started_at, finished_at, duration_ms, ran_by, applied, summary, state_fingerprint)
  values (p_department_id, p_week_start, (p_payload ->> 'policy_version_id')::uuid, p_payload ->> 'input_hash',
    p_payload ->> 'solver_version', 'succeeded', (p_payload ->> 'started_at')::timestamptz,
    (p_payload ->> 'finished_at')::timestamptz, (p_payload ->> 'duration_ms')::int,
    (select auth.uid()), true, coalesce(p_payload -> 'summary', '{}'),
    public.week_state_fingerprint(p_department_id, p_week_start))
  returning id into v_run_id;

  if v_preview_found then
    update public.solver_runs set applied = true where id = v_preview.id;
  end if;

  -- "remaining" mode (bug #5): every current ride was already a fixed
  -- constraint the solver never re-solved, so it must never be deleted here
  -- — this payload's `rides` only ever adds newly-solved assignments for
  -- requests that had no ride at all. "full" mode keeps replacing every
  -- non-pinned draft (the solver's own re-solved output supersedes them).
  if v_mode = 'full' then
    -- REQ §13.94 (board drafts, plan §1/§2): a ride a live proposal depends on is kept like a
    -- pinned one. That is the host ride(s) of a draft/sent/accepted `merge` (the proposal's
    -- ride_id and every ride_id in payload.legs) and the ride a draft/sent `shift` refers to.
    -- Deleting it would withdraw the Sadran's work (or a member's pending consent).
    select coalesce(array_agg(distinct rid), '{}') into v_kept_rides from (
      select p.ride_id as rid from public.proposals p
      where p.department_id = p_department_id and p.week_start = p_week_start and p.ride_id is not null
        and ((p.type = 'merge' and p.status in ('draft', 'sent', 'accepted'))
          or (p.type = 'shift' and p.status in ('draft', 'sent')))
      union
      select (leg ->> 'ride_id')::uuid from public.proposals p
      cross join lateral jsonb_array_elements(coalesce(p.payload -> 'legs', '[]'::jsonb)) leg
      where p.department_id = p_department_id and p.week_start = p_week_start and p.type = 'merge'
        and p.status in ('draft', 'sent', 'accepted') and leg ->> 'ride_id' is not null
    ) k where rid is not null;

    -- Remember who is about to lose a draft so the reconcile step below can catch a
    -- payload that forgot to re-status one of them (docs/HARDENING_2026-09.md §2.4).
    select coalesce(array_agg(distinct rr.request_id), '{}') into v_lost
    from public.rides r join public.ride_requests rr on rr.ride_id = r.id
    where r.department_id = p_department_id and r.week_start = p_week_start and r.status = 'draft' and not r.is_pinned
      and not (r.id = any(v_kept_rides));

    -- REQ §13.90: a proposal referencing one of these about-to-be-deleted rides must
    -- never leave a dangling FK. Pending ones are withdrawn (the request's own
    -- previous_status is restored by proposals_status_guard); answered/applied ones keep
    -- their row for history with the ride link detached.
    select coalesce(array_agg(id), '{}') into v_doomed_rides
    from public.rides
    where department_id = p_department_id and week_start = p_week_start and status = 'draft' and not is_pinned
      and not (id = any(v_kept_rides));

    for v_prop_id in
      select id from public.proposals where status in ('draft', 'sent') and ride_id = any(v_doomed_rides)
      for update
    loop
      update public.proposals set status = 'withdrawn' where id = v_prop_id;
    end loop;
    -- Every reference to a doomed ride must be cleared regardless of status — the FK has
    -- no `on delete`, so a stale ride_id (even on a row just withdrawn above) would still
    -- block the delete below.
    update public.proposals set ride_id = null where ride_id = any(v_doomed_rides);
    update public.proposals set applied_ride_id = null where applied_ride_id = any(v_doomed_rides);

    delete from public.rides
    where department_id = p_department_id and week_start = p_week_start and status = 'draft' and not is_pinned
      and not (id = any(v_kept_rides));
    get diagnostics v_deleted = row_count;
  end if;

  for v_ride in select * from jsonb_array_elements(coalesce(p_payload -> 'rides', '[]'))
  loop
    -- REQ §13.77: denormalize the series onto the ride at INSERT time — rides_before_write()
    -- needs it to skip the turnaround buffer at the 23:59:00 -> 00:00:00 seam.
    select q.series_id into v_series_id
    from jsonb_array_elements(coalesce(v_ride -> 'served', '[]')) s
    join public.requests q on q.id = (s ->> 'request_id')::uuid
    where q.series_id is not null limit 1;

    insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
      driver_id, status, is_pinned, pin_reason, created_by_solver_run_id, created_by, overflow_allowed, series_id,
      needs_driver, auto_relocation, turnaround_override_minutes)
    values (p_department_id, p_week_start, (v_ride ->> 'car_id')::uuid,
      (v_ride ->> 'starts_at')::timestamptz, (v_ride ->> 'ends_at')::timestamptz,
      (v_ride ->> 'origin_id')::uuid, (v_ride ->> 'destination_id')::uuid,
      nullif(v_ride ->> 'driver_id', '')::uuid, 'draft',
      coalesce((v_ride ->> 'is_pinned')::boolean, false), v_ride ->> 'pin_reason',
      v_run_id, (select auth.uid()), coalesce((v_ride ->> 'overflow_allowed')::boolean, false), v_series_id,
      nullif(v_ride ->> 'driver_id', '') is null, coalesce((v_ride ->> 'auto_relocation')::boolean, false),
      -- Out-leg of a relay pair with less than the turnaround at X (REQ §13.88, owner 2026-09-24).
      (v_ride ->> 'turnaround_override_minutes')::smallint)
    returning id into v_ride_id;

    v_inserted := v_inserted + 1;
    v_touched_cars := array_append(v_touched_cars, (v_ride ->> 'car_id')::uuid);

    for v_served in select * from jsonb_array_elements(coalesce(v_ride -> 'served', '[]'))
    loop
      insert into public.ride_requests (ride_id, request_id, role, leg, car_mode, detour_minutes)
      values (v_ride_id, (v_served ->> 'request_id')::uuid, (v_served ->> 'role')::public.ride_role,
        coalesce((v_served ->> 'leg')::public.ride_leg, 'both'), (v_served ->> 'car_mode')::public.leg_car_mode,
        coalesce((v_served ->> 'detour_minutes')::smallint, 0));
    end loop;
  end loop;

  for v_status in select * from jsonb_array_elements(coalesce(p_payload -> 'request_statuses', '[]'))
  loop
    update public.requests
    set status = (v_status ->> 'status')::public.request_status,
        status_reason = v_status ->> 'status_reason',
        changed_since_solve = false
    where id = (v_status ->> 'request_id')::uuid
      and department_id = p_department_id and week_start = p_week_start;

    if found and (v_status ->> 'status') = 'waitlisted' then
      v_unassigned := array_append(v_unassigned, (v_status ->> 'request_id')::uuid);
    end if;
  end loop;

  -- REQ §13.77: a solved leg of a multi-day series drags the rest of the series onto the
  -- same car — including legs in the NEXT week, which place_series() materializes as pinned
  -- 'SERIES_CARRY_OVER' rides. All-or-nothing: if the car cannot take the whole span, this
  -- apply's rides for that series are rolled back (nested block = subtransaction, plus an
  -- explicit delete of the rows inserted above it), its legs go back to `submitted` /
  -- 'SERIES_CAR_UNAVAILABLE', and the caller is told in `skippedSeries` — the rest of the
  -- solve still applies.
  for v_series in
    select r.series_id as sid, (array_agg(r.car_id order by r.starts_at, r.id))[1] as car_id
    from public.rides r
    where r.created_by_solver_run_id = v_run_id and r.series_id is not null
    group by r.series_id
  loop
    begin
      perform public.place_series(v_series.sid, v_series.car_id, false, null);
    exception when others then
      v_skipped := v_skipped || jsonb_build_array(
        jsonb_build_object('series_id', v_series.sid, 'reason', coalesce(nullif(sqlerrm, ''), sqlstate)));
      delete from public.rides
      where created_by_solver_run_id = v_run_id and series_id = v_series.sid;
      perform set_config('app.system_status_transition', 'on', true);
      update public.requests set status = 'submitted', status_reason = 'SERIES_CAR_UNAVAILABLE'
      where series_id = v_series.sid and status not in ('withdrawn', 'cancelled');
      perform set_config('app.system_status_transition', 'off', true);
    end;
  end loop;

  -- Any failure here (a broken car chain, a car away at day end without
  -- acknowledgement, …) raises and unwinds every insert/delete/update this
  -- call made above — apply_solver_result is one PL/pgSQL function
  -- invocation, hence one implicit transaction; there is no partial-apply
  -- outcome, only "fully applied" or "fully rolled back, error surfaced".
  -- A request that lost its draft above and was not re-placed nor re-statused by this
  -- payload must not stay `assigned`/`merged` with no ride: put it back in the queue.
  perform set_config('app.system_status_transition', 'on', true);
  update public.requests q
  set status = 'submitted', status_reason = 'SOLVER_UNPLACED', changed_since_solve = false
  where q.id = any(v_lost) and q.status in ('assigned', 'merged')
    and not exists (select 1 from public.ride_requests rr join public.rides rd on rd.id = rr.ride_id
                    where rr.request_id = q.id and rd.status <> 'cancelled');
  get diagnostics v_unplaced = row_count;
  perform set_config('app.system_status_transition', 'off', true);
  perform public.assert_car_chain(car_id, p_week_start) from unnest(v_touched_cars) as car_id;

  return jsonb_build_object(
    'run_id', v_run_id,
    'inserted', v_inserted,
    'deleted', v_deleted,
    'unchanged', greatest(v_existing_count - v_deleted, 0),
    'unassigned_requests', coalesce(to_jsonb(v_unassigned), '[]'::jsonb),
    'skippedSeries', v_skipped,
    'unplaced_reset', v_unplaced
  );
end;
$$;


ALTER FUNCTION "public"."apply_solver_result"("p_department_id" "uuid", "p_week_start" "date", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_claim"("p_offer_id" "uuid", "p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_offer record; v_ride_id uuid;
begin
  select * into v_offer from public.freed_slot_offers where id = p_offer_id;
  if v_offer is null then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_offer.department_id, v_offer.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'approve_claim', true);

  insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
    driver_id, status, is_pinned, pin_reason, created_by)
  select r.department_id, r.week_start, v_offer.car_id, q.depart_at, q.return_at, r.origin_id, r.destination_id,
    q.requester_id, 'confirmed', true, 'FREED_SLOT_APPROVED', (select auth.uid())
  from public.rides r, public.requests q where r.id = v_offer.cancelled_ride_id and q.id = p_request_id
  returning id into v_ride_id;

  insert into public.ride_requests (ride_id, request_id, role, leg, car_mode) values (v_ride_id, p_request_id, 'driver', 'both', 'keep');
  perform public.assert_car_chain(v_offer.car_id, v_offer.week_start);

  update public.freed_slot_claims set status = 'approved', decided_at = now(), decided_by = (select auth.uid())
  where offer_id = p_offer_id and request_id = p_request_id;
  update public.freed_slot_claims set status = 'declined', decided_at = now(), decided_by = (select auth.uid())
  where offer_id = p_offer_id and request_id <> p_request_id and status in ('offered', 'claimed');
  update public.freed_slot_offers set status = 'approved', resolved_at = now(), resolved_by = (select auth.uid()),
    winning_request_id = p_request_id where id = p_offer_id;
  update public.requests set status = 'assigned', status_reason = 'FREED_SLOT_APPROVED' where id = p_request_id;

  perform public.enqueue_notification(q.requester_id, 'claim_approved', v_offer.department_id, v_offer.week_start,
    '{}'::jsonb, jsonb_build_object('ride_id', v_ride_id), format('claim_approved:%s', p_request_id))
  from public.requests q where q.id = p_request_id;
  perform public.enqueue_notification(fc.profile_id, 'claim_declined', v_offer.department_id, v_offer.week_start,
    '{}'::jsonb, jsonb_build_object('offer_id', p_offer_id), format('claim_declined:%s:%s', p_offer_id, fc.profile_id))
  from public.freed_slot_claims fc where fc.offer_id = p_offer_id and fc.request_id <> p_request_id and fc.status = 'declined';

  return v_ride_id;
end;
$$;


ALTER FUNCTION "public"."approve_claim"("p_offer_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_car_chain"("_car" "uuid", "_week" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid; v_turnaround interval; v_week_starts timestamptz;
  r record; v_next record; v_prev_loc uuid; v_request_id uuid; v_leg public.ride_leg;
  v_car_mode public.leg_car_mode; v_trip_type public.trip_type; v_widen text;
begin
  select department_id into v_dept from public.cars where id = _car;
  if v_dept is null then return; end if;

  v_turnaround := make_interval(mins => coalesce(public.required_turnaround_minutes(v_dept, _week), 30));
  v_week_starts := (_week::timestamp) at time zone 'Asia/Jerusalem';

  -- REQ §13.88/§13.93: pair up any matching drop_off legs across the department before
  -- walking this car's own chain, so a freshly-matched pair is never seen as a gap.
  perform public.pair_one_way_legs(v_dept, _week);
  -- REQ §13.95 H2: a הקפצה's out and return legs on this car, driven by the requester/companion, connect.
  perform public.connect_drop_off_legs(_car, _week);

  for r in
    select rd.id as ride_id, rd.origin_id, rd.destination_id, rd.starts_at, rd.ends_at
    from public.rides rd
    where rd.car_id = _car and rd.week_start = _week and rd.status <> 'cancelled' and not rd.planning_conflict
      and (not rd.auto_relocation or rd.driver_id is not null)
      and not public.ride_is_reservation(rd.id)
    order by rd.starts_at
  loop
    select rr.request_id, rr.leg, rr.car_mode into v_request_id, v_leg, v_car_mode
    from public.ride_requests rr
    where rr.ride_id = r.ride_id and rr.car_mode = 'relay'
    order by (rr.leg = 'out') desc limit 1;

    if v_request_id is null then
      continue; -- keep/chauffeur/reservation/pinned ride: nothing for this step to heal
    end if;

    select q.trip_type into v_trip_type from public.requests q where q.id = v_request_id;
    if v_trip_type is distinct from 'drop_off' then
      continue; -- an explicit one_way leg is never widened (§1.3a)
    end if;

    if exists (select 1 from public.ride_requests rr2 join public.rides r2 on r2.id = rr2.ride_id
               where rr2.request_id = v_request_id and rr2.car_mode = 'relay' and rr2.leg <> v_leg
                 and r2.car_id = _car and r2.week_start = _week and r2.status <> 'cancelled' and r2.id <> r.ride_id) then
      continue; -- REQ §13.95 H2: the request's own out and return legs are connected on this car
    end if;

    if v_leg = 'out' then
      select rd2.id, rd2.origin_id, rd2.destination_id into v_next
      from public.rides rd2
      where rd2.car_id = _car and rd2.status <> 'cancelled' and not rd2.planning_conflict
        and (not rd2.auto_relocation or rd2.driver_id is not null)
        and not public.ride_is_reservation(rd2.id)
        and rd2.starts_at > r.starts_at
        and (rd2.starts_at at time zone 'Asia/Jerusalem')::date = (r.starts_at at time zone 'Asia/Jerusalem')::date
      order by rd2.starts_at limit 1;
      if v_next.id is not null and v_next.origin_id = r.destination_id and v_next.destination_id <> r.destination_id then
        continue; -- paired: the next ride the same day takes the car on from X
      end if;
      v_widen := public.try_widen_one_way_leg(r.ride_id, _car, v_dept, _week, null, v_turnaround, 'out');
    else
      select coalesce(
        (select rd3.destination_id from public.rides rd3
          where rd3.car_id = _car and rd3.status <> 'cancelled' and not rd3.planning_conflict
            and (not rd3.auto_relocation or rd3.driver_id is not null)
            and not public.ride_is_reservation(rd3.id)
            and rd3.starts_at < r.starts_at and rd3.id <> r.ride_id
          order by rd3.starts_at desc limit 1),
        public.car_location_at(_car, v_week_starts))
      into v_prev_loc;
      if v_prev_loc = r.origin_id then
        continue; -- paired: the car is already at X when this pickup leg needs it
      end if;
      v_widen := public.try_widen_one_way_leg(r.ride_id, _car, v_dept, _week, null, v_turnaround, 'fetch');
    end if;
  end loop;
end $$;


ALTER FUNCTION "public"."assert_car_chain"("_car" "uuid", "_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_named_passenger_counts"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare q public.requests%rowtype; members int;
begin
  select * into q from public.requests where id=p_request_id;if not found then return;end if;
  select count(*) into members from public.request_companions where request_id=q.id;
  if members>20 then raise exception 'invalid_companions';end if;
  if members+cardinality(q.guest_passenger_names)>q.adults+q.child_seats+q.boosters-1 then raise exception 'passenger_names_exceed_seats';end if;
end $$;


ALTER FUNCTION "public"."assert_named_passenger_counts"("p_request_id" "uuid") OWNER TO "postgres";


