CREATE OR REPLACE FUNCTION "public"."assert_publication_scores"("p_department_id" "uuid", "p_week_start" "date", "p_scores" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare profile jsonb; item jsonb; n int; served_count int; total numeric; served_total numeric; actual_served boolean;
begin
  if jsonb_typeof(p_scores) is distinct from 'array' then raise exception 'invalid_publication_scores'; end if;
  if (select count(distinct x->>'profile_id') from jsonb_array_elements(p_scores) x)<>jsonb_array_length(p_scores) then raise exception 'invalid_publication_scores'; end if;
  for profile in select * from jsonb_array_elements(p_scores) loop
    if jsonb_typeof(profile->'requests') is distinct from 'array' then raise exception 'invalid_publication_scores'; end if;
    n:=0;served_count:=0;total:=0;served_total:=0;
    for item in select * from jsonb_array_elements(profile->'requests') loop
      if jsonb_typeof(item->'score') is distinct from 'number' or jsonb_typeof(item->'served') is distinct from 'boolean' then raise exception 'invalid_publication_scores'; end if;
      if not exists(select 1 from public.requests q where q.id=(item->>'request_id')::uuid and q.requester_id=(profile->>'profile_id')::uuid
        and q.department_id=p_department_id and q.week_start=p_week_start and q.status not in ('draft','withdrawn','cancelled')) then raise exception 'invalid_publication_scores'; end if;
      select exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=(item->>'request_id')::uuid and r.status<>'cancelled' and not r.needs_driver) into actual_served;
      if actual_served is distinct from (item->>'served')::boolean then raise exception 'invalid_publication_scores'; end if;
      n:=n+1;total:=total+(item->>'score')::numeric;
      if actual_served then served_count:=served_count+1;served_total:=served_total+(item->>'score')::numeric; end if;
    end loop;
    if (profile->>'request_count')::int is distinct from n or (profile->>'served_count')::int is distinct from served_count
      or abs(coalesce((profile->>'priority_total')::numeric,'Infinity'::numeric)-total)>0.000001*greatest(n,1)
      or abs(coalesce((profile->>'served_priority_total')::numeric,'Infinity'::numeric)-served_total)>0.000001*greatest(n,1) then raise exception 'invalid_publication_scores'; end if;
  end loop;
  if exists(select 1 from public.requests q where q.department_id=p_department_id and q.week_start=p_week_start and q.status not in ('draft','withdrawn','cancelled')
    and (select count(*) from jsonb_array_elements(p_scores) score_profile cross join lateral jsonb_array_elements(score_profile->'requests') score_item where (score_item->>'request_id')::uuid=q.id)<>1
  ) then raise exception 'invalid_publication_scores'; end if;
end $$;


ALTER FUNCTION "public"."assert_publication_scores"("p_department_id" "uuid", "p_week_start" "date", "p_scores" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_ride_driver"("p_ride_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.rides%rowtype; total int; drivers int;
begin
  select * into r from public.rides where id=p_ride_id;
  if not found or r.status='cancelled' then return; end if;
  select count(*),count(*) filter(where role='driver') into total,drivers from public.ride_requests where ride_id=r.id;
  if r.needs_driver and drivers<>0 then raise exception 'ride_driver_chauffeur_mismatch'; end if;
  if total>0 and not r.needs_driver and (r.driver_id is null or drivers>1) then raise exception 'ride_driver_chauffeur_mismatch'; end if;
  -- REQ §13.88/89: a driving companion may stand in for a non-driving requester.
  if exists(
    select 1 from public.ride_requests rr join public.requests q on q.id=rr.request_id
    where rr.ride_id=r.id and rr.role='driver' and q.requester_id is distinct from r.driver_id
      and not exists (
        select 1 from public.request_companions rc join public.profiles p on p.id=rc.profile_id
        where rc.request_id=q.id and rc.profile_id=r.driver_id and not p.does_not_drive)
  ) then raise exception 'driver_row_requester_mismatch'; end if;
  if r.driver_id is not null and exists (select 1 from public.profiles p where p.id = r.driver_id and p.does_not_drive) then
    raise exception 'non_driver_cannot_drive' using errcode = 'P0001';
  end if;
  -- Only meaningful when the requester themselves is the one driving (r.driver_id =
  -- requester_id) — a driving companion standing in for a non-driving requester is fine
  -- and already covered by the r.driver_id check above.
  if exists (
    select 1 from public.ride_requests rr
    join public.requests q on q.id = rr.request_id
    join public.profiles p on p.id = q.requester_id
    where rr.ride_id = r.id and rr.role = 'driver' and rr.car_mode in ('keep','relay') and p.does_not_drive
      and q.requester_id = r.driver_id
  ) then
    raise exception 'non_driver_cannot_drive' using errcode = 'P0001';
  end if;
end $$;


ALTER FUNCTION "public"."assert_ride_driver"("p_ride_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_ride_request_day"("p_ride_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if exists (
    select 1 from public.rides r join public.ride_requests rr on rr.ride_id = r.id
    join public.requests q on q.id = rr.request_id
    where r.id = p_ride_id and r.status <> 'cancelled'
      and (r.starts_at at time zone 'Asia/Jerusalem')::date <>
          ((case when rr.leg = 'return' or q.trip_shape = 'one_way_from' then q.return_at else q.depart_at end) at time zone 'Asia/Jerusalem')::date
  ) then raise exception 'ride_request_day_mismatch' using errcode = 'P0001'; end if;
end $$;


ALTER FUNCTION "public"."assert_ride_request_day"("p_ride_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_ride_seats_fit"("v_ride" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r record;
begin
  for r in
    select leg_side,
           sum(q.adults) a, sum(q.child_seats) c, sum(q.boosters) b, rd.car_id
    from public.ride_requests rr
    join public.requests q on q.id = rr.request_id
    join public.rides rd on rd.id = rr.ride_id
    cross join lateral (values ('out'), ('return')) as legs(leg_side)
    where rr.ride_id = v_ride and rd.status <> 'cancelled'
      and ((legs.leg_side = 'out' and rr.covers_out) or (legs.leg_side = 'return' and rr.covers_return))
    group by leg_side, rd.car_id
  loop
    if not exists (select 1 from public.ride_requests x where x.ride_id = v_ride and x.role = 'driver')
      and not exists (select 1 from public.ride_requests x join public.requests q on q.id=x.request_id join public.rides rd on rd.id=x.ride_id
        where x.ride_id=v_ride and q.requester_id=rd.driver_id and ((r.leg_side='out' and x.covers_out) or (r.leg_side='return' and x.covers_return))) then
      r.a := r.a + 1;   -- chauffeur ride: the volunteer has no request of their own (§5.2)
    end if;
    if not public.car_fits(r.car_id, r.a::int, r.c::int, r.b::int) then
      raise exception 'seat_config_violation' using detail =
        format('ride %s leg %s needs (%s,%s,%s)', v_ride, r.leg_side, r.a, r.c, r.b);
    end if;
  end loop;
end $$;


ALTER FUNCTION "public"."assert_ride_seats_fit"("v_ride" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_same_day_window"("p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_start is null or p_end is null or p_end<=p_start
    or (p_start at time zone 'Asia/Jerusalem')::date<>(p_end at time zone 'Asia/Jerusalem')::date
    or (p_end at time zone 'Asia/Jerusalem')::time>time '23:59:00'
  then raise exception 'ride_must_end_same_day'; end if;
end $$;


