    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.department_id is distinct from old.department_id then raise exception 'catalog_department_locked' using errcode='P0001'; end if;
  return new;
end $$;


