CREATE OR REPLACE FUNCTION "public"."claim_freed_slot"("p_offer_id" "uuid", "p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.requests where id = p_request_id and requester_id = (select auth.uid())) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'claim_freed_slot', true);
  update public.freed_slot_claims set status = 'claimed', claimed_at = now()
  where offer_id = p_offer_id and request_id = p_request_id and status = 'offered';
end;
$$;


ALTER FUNCTION "public"."claim_freed_slot"("p_offer_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_ride_driver"("p_ride_id" "uuid", "p_expected_version" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.rides%rowtype; passenger record;
begin
  select * into r from public.rides where id=p_ride_id for update;
  if not found then raise exception 'ride_not_found'; end if;
  if not public.member_of(r.department_id) or (not public.is_week_public(r.department_id,r.week_start) and not public.can_manage_week(r.department_id,r.week_start)) then raise exception 'not_authorized'; end if;
  if p_expected_version is null or r.version<>p_expected_version then perform public.raise_stale_version(); end if;
  if not r.needs_driver or r.status='cancelled' then raise exception 'ride_driver_already_assigned'; end if;
  if r.ends_at<=now() or exists(select 1 from public.weeks where department_id=r.department_id and week_start=r.week_start and phase='archived') then raise exception 'ride_in_past'; end if;
  if not exists(select 1 from public.cars where id=r.car_id and status='active') then raise exception 'car_unavailable'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ride-driver:'||(select auth.uid())::text,0));
  if exists(select 1 from public.rides where driver_id=(select auth.uid()) and id<>r.id and status<>'cancelled'
    and tstzrange(starts_at,ends_at,'[)') && tstzrange(r.starts_at,r.ends_at,'[)')) then raise exception 'driver_already_busy'; end if;
  perform set_config('app.audit_reason','claim_ride_driver',true);
  update public.rides set driver_id=(select auth.uid()),needs_driver=false,
    status=case when status='flagged' and flag_reason='NEEDS_DRIVER' then 'confirmed'::public.ride_status else status end,
    flag_reason=case when flag_reason='NEEDS_DRIVER' then null else flag_reason end where id=r.id;
  perform public.assert_ride_driver(r.id);perform public.assert_ride_seats_fit(r.id);perform public.assert_car_chain(r.car_id,r.week_start);
  perform set_config('app.system_status_transition','on',true);
  update public.requests set status='merged',status_reason='DRIVER_CLAIMED' where id in(select request_id from public.ride_requests where ride_id=r.id);
  for passenger in select q.id,q.requester_id from public.ride_requests rr join public.requests q on q.id=rr.request_id where rr.ride_id=r.id loop
    perform public.enqueue_notification(passenger.requester_id,'outcome_changed',r.department_id,r.week_start,'{}',
      jsonb_build_object('request_id',passenger.id,'ride_id',r.id),format('driver_claimed:%s:%s:%s',r.id,r.version,passenger.id));
  end loop;
  perform set_config('app.system_status_transition','off',true);
end $$;


ALTER FUNCTION "public"."claim_ride_driver"("p_ride_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_removed_department_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if old.removed_at is null and new.removed_at is not null then
    delete from public.sadran_assignments where department_id=new.department_id and profile_id=new.profile_id
      and (week_start is null or week_start >= ((now() at time zone 'Asia/Jerusalem')::date-extract(dow from now() at time zone 'Asia/Jerusalem')::int));
    update public.profiles p set default_department_id=(
      select dm.department_id from public.department_members dm join public.departments d on d.id=dm.department_id
      where dm.profile_id=new.profile_id and dm.removed_at is null and d.is_active
      order by dm.created_at,dm.department_id limit 1)
    where p.id=new.profile_id and p.default_department_id=new.department_id;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."cleanup_removed_department_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_errors_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.message := left(new.message, 2048);
  new.stack := left(new.stack, 8192);
  if new.profile_id is not null and (
    select count(*) from public.client_errors
    where profile_id = new.profile_id and created_at > now() - interval '1 hour'
  ) >= 20 then
    raise exception 'client_error_rate_limited' using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."client_errors_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_offer"("p_offer_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_offer record;
begin
  select * into v_offer from public.freed_slot_offers where id = p_offer_id;
  if v_offer is null then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_offer.department_id, v_offer.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'close_offer', true);
  update public.freed_slot_offers set status = 'closed', resolved_at = now(), resolved_by = (select auth.uid())
  where id = p_offer_id;
end;
$$;


