CREATE OR REPLACE FUNCTION "public"."departments_create_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  insert into public.department_settings (department_id) values (new.id)
  on conflict (department_id) do nothing;
  return new;
end;
$$;


