CREATE OR REPLACE FUNCTION "public"."discard_proposal"("p_proposal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_p public.proposals%rowtype;
begin
  select * into v_p from public.proposals where id = p_proposal_id for update;
  if not found then raise exception 'proposal_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_p.department_id, v_p.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if v_p.status <> 'draft' then raise exception 'proposal_not_draft' using errcode = 'P0001'; end if;
  perform set_config('app.audit_reason', 'discard_proposal', true);
  update public.proposals set status = 'withdrawn' where id = p_proposal_id;
end;
$$;


ALTER FUNCTION "public"."discard_proposal"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_push_outbox_row"("_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_url text; v_secret text;
begin
  perform public.assert_not_direct_rpc('dispatch_push_outbox_row');
  select value ->> 'value' into v_url from public.app_settings where key = 'push_dispatch_url';
  select value ->> 'value' into v_secret from public.app_secrets where key = 'cron_secret';
  if v_url is not null and v_url <> '' then
    perform net.http_post(
      url := v_url,
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', coalesce(v_secret, '')),
      body := jsonb_build_object('outbox_id', _id)
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."dispatch_push_outbox_row"("_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."drain_push_outbox"("_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count int := 0;
  r record;
  v_backoff int[] := array[1,5,15,60];
begin
  perform public.assert_not_direct_rpc('drain_push_outbox');
  for r in
    select id, attempts, created_at from public.push_outbox
    where status in ('pending','failed') and next_attempt_at <= _now
    for update skip locked
  loop
    if r.created_at <= _now - interval '24 hours' then
      update public.push_outbox set status = 'dead' where id = r.id;
      continue;
    end if;
    update public.push_outbox
    set attempts = r.attempts + 1,
        next_attempt_at = _now + make_interval(mins => v_backoff[least(r.attempts + 1, array_length(v_backoff, 1))])
    where id = r.id;
    perform public.dispatch_push_outbox_row(r.id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."drain_push_outbox"("_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_ride"("p_ride" "jsonb", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid := nullif(p_ride ->> 'id', '')::uuid; v_ride public.rides%rowtype;
  v_new_car uuid := nullif(p_ride ->> 'car_id', '')::uuid; v_idx smallint; v_cnt smallint; v_ver int;
  v_time_change boolean;
begin
  if v_id is null then
    if exists (select 1 from jsonb_array_elements(coalesce(p_ride -> 'served', '[]')) s
               join public.requests q on q.id = (s ->> 'request_id')::uuid where q.series_id is not null) then
      raise exception 'series_edit_not_supported' using errcode = 'MDR02';
    end if;
    return public.edit_ride_before_series(p_ride, p_expected_version);
  end if;

  select * into v_ride from public.rides where id = v_id;
  if v_ride.id is null or v_ride.series_id is null then
    return public.edit_ride_before_series(p_ride, p_expected_version);
  end if;

  select q.series_index, q.series_count into v_idx, v_cnt
  from public.ride_requests rr join public.requests q on q.id = rr.request_id
  where rr.ride_id = v_id and q.series_id = v_ride.series_id limit 1;

  if p_ride ? 'starts_at' and (p_ride ->> 'starts_at')::timestamptz is distinct from v_ride.starts_at
     and coalesce(v_idx, 0) <> 1 then
    raise exception 'series_edit_not_supported' using errcode = 'MDR02';
  end if;
  if p_ride ? 'ends_at' and (p_ride ->> 'ends_at')::timestamptz is distinct from v_ride.ends_at
     and coalesce(v_idx, 0) is distinct from v_cnt then
    raise exception 'series_edit_not_supported' using errcode = 'MDR02';
  end if;

  if v_new_car is not null and v_new_car <> v_ride.car_id then
    if p_expected_version is null or v_ride.version <> p_expected_version then perform public.raise_stale_version(); end if;
    perform public.move_series(v_ride.series_id, v_new_car, null);
    select version into v_ver from public.rides where id = v_id;
    v_time_change :=
      (p_ride ? 'starts_at' and (p_ride ->> 'starts_at')::timestamptz is distinct from v_ride.starts_at)
      or (p_ride ? 'ends_at' and (p_ride ->> 'ends_at')::timestamptz is distinct from v_ride.ends_at)
      or (p_ride ? 'driver_id' and nullif(p_ride ->> 'driver_id', '')::uuid is distinct from v_ride.driver_id)
      or (p_ride ? 'notes' and nullif(trim(p_ride ->> 'notes'), '') is distinct from v_ride.notes);
    if v_time_change then return public.edit_ride_before_series(p_ride, v_ver); end if;
    return v_id;
  end if;

  return public.edit_ride_before_series(p_ride, p_expected_version);
end $$;


ALTER FUNCTION "public"."edit_ride"("p_ride" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_ride_before_planning"("p_ride" "jsonb", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid := nullif(p_ride->>'id', '')::uuid;
  v_dept uuid := (p_ride->>'department_id')::uuid;
  v_week date := (p_ride->>'week_start')::date;
  v_existing public.rides%rowtype;
  v_manage boolean;
  v_served jsonb;
  v_old_requests uuid[];
  v_needs_driver boolean;
  v_override smallint;
begin
  if not public.is_approved() then raise exception 'not_authorized'; end if;
  if v_id is not null then
    select * into v_existing from public.rides where id = v_id for update;
    if not found then raise exception 'ride_not_found'; end if;
    if v_dept is distinct from v_existing.department_id or v_week is distinct from v_existing.week_start then raise exception 'not_authorized'; end if;
    if p_expected_version is null or v_existing.version <> p_expected_version then perform public.raise_stale_version(); end if;
    if v_existing.status = 'cancelled' then raise exception 'ride_not_found'; end if;
  end if;
  v_manage := public.can_manage_week(v_dept,v_week);
  if exists (select 1 from public.weeks where department_id=v_dept and week_start=v_week and phase='archived') then raise exception 'week_archived'; end if;
  if not v_manage then
    if v_id is null or v_existing.driver_id is distinct from (select auth.uid()) or not public.is_week_public(v_dept,v_week) then raise exception 'not_authorized'; end if;
    if (p_ride->>'starts_at')::timestamptz <= now() then raise exception 'ride_in_past'; end if;
    if (p_ride ? 'driver_id' and (p_ride->>'driver_id')::uuid is distinct from v_existing.driver_id)
      or (p_ride ? 'origin_id' and (p_ride->>'origin_id')::uuid is distinct from v_existing.origin_id)
      or (p_ride ? 'destination_id' and (p_ride->>'destination_id')::uuid is distinct from v_existing.destination_id)
      or ((p_ride->>'starts_at')::timestamptz at time zone 'Asia/Jerusalem')::date <> (v_existing.starts_at at time zone 'Asia/Jerusalem')::date
      or exists (select 1 from public.ride_requests rr join public.requests q on q.id=rr.request_id where rr.ride_id=v_id and (q.requester_id <> (select auth.uid()) or rr.car_mode <> 'keep'))
    then raise exception 'not_authorized'; end if;
  end if;
  if not exists (select 1 from public.cars where id=(p_ride->>'car_id')::uuid and status='active' and department_id=v_dept) then raise exception 'car_unavailable'; end if;
  v_needs_driver:=case when v_manage then coalesce((p_ride->>'needs_driver')::boolean,v_existing.needs_driver,false) else false end;
  perform set_config('app.audit_reason','edit_ride',true);
  if v_manage then
    v_override:=public.prepare_manual_ride_window((p_ride->>'car_id')::uuid,v_week,(p_ride->>'starts_at')::timestamptz,(p_ride->>'ends_at')::timestamptz,v_id);
  end if;
  if v_id is null then
    insert into public.rides(department_id,week_start,car_id,starts_at,ends_at,origin_id,destination_id,driver_id,status,is_pinned,pin_reason,created_by,notes,needs_driver,turnaround_override_minutes)
    values(v_dept,v_week,(p_ride->>'car_id')::uuid,(p_ride->>'starts_at')::timestamptz,(p_ride->>'ends_at')::timestamptz,
      (p_ride->>'origin_id')::uuid,(p_ride->>'destination_id')::uuid,nullif(p_ride->>'driver_id','')::uuid,
      case when public.is_week_public(v_dept,v_week) then 'confirmed'::public.ride_status else 'draft'::public.ride_status end,
      true,coalesce(p_ride->>'pin_reason','SADRAN_MANUAL'),(select auth.uid()),nullif(trim(p_ride->>'notes'),''),v_needs_driver,v_override) returning id into v_id;
  else
    update public.rides set needs_driver=v_needs_driver,turnaround_override_minutes=v_override,car_id=(p_ride->>'car_id')::uuid,starts_at=(p_ride->>'starts_at')::timestamptz,ends_at=(p_ride->>'ends_at')::timestamptz,
      origin_id=coalesce((p_ride->>'origin_id')::uuid,origin_id),destination_id=coalesce((p_ride->>'destination_id')::uuid,destination_id),
      driver_id=case when v_manage and p_ride ? 'driver_id' then nullif(p_ride->>'driver_id','')::uuid else driver_id end,
      notes=case when v_manage and p_ride ? 'notes' then nullif(trim(p_ride->>'notes'),'') else notes end,
      overflow_allowed=case when v_manage then coalesce((p_ride->>'overflow_allowed')::boolean,overflow_allowed) else overflow_allowed end,
      overnight_ack_by=case when v_manage and (p_ride->>'overnight_ack')::boolean then (select auth.uid()) else overnight_ack_by end,
      overnight_ack_at=case when v_manage and (p_ride->>'overnight_ack')::boolean then now() else overnight_ack_at end,
      is_pinned=case when v_needs_driver then true when v_manage then coalesce((p_ride->>'is_pinned')::boolean,true) else true end,pin_reason=coalesce(p_ride->>'pin_reason',case when v_manage then 'SADRAN_EDIT' else 'MEMBER_EDIT' end)
    where id=v_id;
  end if;
  if v_manage and p_ride ? 'served' then
    select array_agg(request_id) into v_old_requests from public.ride_requests where ride_id=v_id;
    delete from public.ride_requests where ride_id=v_id;
    for v_served in select * from jsonb_array_elements(p_ride->'served') loop
      if exists (select 1 from public.rides where id=v_id and driver_id is null and not needs_driver) then raise exception 'reservation_cannot_serve_requests'; end if;
      insert into public.ride_requests(ride_id,request_id,role,leg,car_mode,detour_minutes)
      values(v_id,(v_served->>'request_id')::uuid,(v_served->>'role')::public.ride_role,
        coalesce((v_served->>'leg')::public.ride_leg,'both'),(v_served->>'car_mode')::public.leg_car_mode,coalesce((v_served->>'detour_minutes')::smallint,0));
      update public.requests set status=case when v_needs_driver then 'waitlisted'::public.request_status when v_served->>'role'='driver' then 'assigned'::public.request_status else 'merged'::public.request_status end,status_reason=case when v_needs_driver then 'UNMET_NEEDS_DRIVER' else 'SADRAN_ASSIGNED' end
      where id=(v_served->>'request_id')::uuid;
    end loop;
    update public.requests q set status='waitlisted',status_reason='SADRAN_UNASSIGNED'
    where q.id=any(v_old_requests) and not exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=q.id and r.status<>'cancelled');
  end if;
  perform public.assert_ride_driver(v_id);
  if v_manage then
    perform public.refresh_car_turnarounds((p_ride->>'car_id')::uuid,v_week);
    if v_existing.car_id is not null and v_existing.car_id<>(p_ride->>'car_id')::uuid then perform public.refresh_car_turnarounds(v_existing.car_id,v_week); end if;
  end if;
  perform public.assert_ride_request_day(v_id);
  perform public.assert_ride_seats_fit(v_id);
  perform public.assert_car_chain((p_ride->>'car_id')::uuid,v_week);
  if v_existing.car_id is not null and v_existing.car_id<>(p_ride->>'car_id')::uuid then perform public.assert_car_chain(v_existing.car_id,v_week); end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."edit_ride_before_planning"("p_ride" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_ride_before_series"("p_ride" "jsonb", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare existing public.rides%rowtype; v_id uuid:=nullif(p_ride->>'id','')::uuid;
  v_dept uuid:=(p_ride->>'department_id')::uuid; v_week date:=(p_ride->>'week_start')::date;
  v_car uuid:=(p_ride->>'car_id')::uuid; v_start timestamptz:=(p_ride->>'starts_at')::timestamptz;
  v_end timestamptz:=(p_ride->>'ends_at')::timestamptz; wants_planning boolean:=coalesce((p_ride->>'allow_conflict')::boolean,false);
  collision boolean; old_setting text:=coalesce(current_setting('app.coordinator_planning',true),''); result uuid; leg record;
begin
  if not public.is_approved() then raise exception 'not_authorized'; end if;
  if wants_planning and not public.can_manage_week(v_dept,v_week) then raise exception 'not_authorized'; end if;
  perform public.assert_same_day_window(v_start,v_end);
  if not(public.week_range(v_week) @> tstzrange(v_start,v_end,'[)')) then raise exception 'ride_outside_week'; end if;
  if v_id is not null then
    select * into existing from public.rides where id=v_id for update;
    if not found or existing.status='cancelled' then raise exception 'ride_not_found'; end if;
    if existing.department_id<>v_dept or existing.week_start<>v_week then raise exception 'not_authorized'; end if;
    if p_expected_version is null or existing.version<>p_expected_version then perform public.raise_stale_version(); end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_car::text,0));
  select exists(select 1 from public.rides r where r.car_id=v_car and r.id is distinct from v_id and r.status<>'cancelled'
    and tstzrange(r.starts_at,r.ends_at,'[)') && tstzrange(v_start,v_end,'[)')) into collision;
  if wants_planning and collision and existing.id is not null and existing.status<>'draft' then
    if exists(select 1 from public.weeks where department_id=v_dept and week_start=v_week and phase='archived') then raise exception 'week_archived'; end if;
    if not exists(select 1 from public.cars where id=v_car and department_id=v_dept and status='active'
      and (type='shared' or owner_id=existing.driver_id)) then raise exception 'car_unavailable'; end if;
    if (v_start at time zone 'Asia/Jerusalem')::date<>(existing.starts_at at time zone 'Asia/Jerusalem')::date then raise exception 'ride_request_day_mismatch'; end if;
    if not public.is_quarter_hour(v_start) or not(public.is_quarter_hour(v_end) or public.is_same_day_end(v_end)) then raise exception 'invalid_ride_window'; end if;
    if exists(select 1 from public.car_maintenance_blocks b where b.car_id=v_car
      and tstzrange(b.starts_at,b.ends_at,'[)') && tstzrange(v_start,v_end,'[)')) then raise exception 'ride_conflicts_with_maintenance'; end if;
    -- Seat counts already include request owners. Add the volunteer only if not
    -- represented in this leg; never double count a driver/requester.
    for leg in select side,sum(q.adults)::int adults,sum(q.child_seats)::int children,sum(q.boosters)::int boosters,
      bool_or(q.requester_id=existing.driver_id) driver_included
      from public.ride_requests rr join public.requests q on q.id=rr.request_id
      cross join lateral(values('out'),('return')) legs(side)
      where rr.ride_id=v_id and ((side='out' and rr.covers_out) or (side='return' and rr.covers_return)) group by side loop
      if not public.car_fits(v_car,leg.adults+case when coalesce(leg.driver_included,false) then 0 else 1 end,leg.children,leg.boosters) then raise exception 'seat_config_violation'; end if;
    end loop;
    if exists(select 1 from public.ride_change_requests where ride_id=v_id and status='pending' and not is_planning) then raise exception 'ride_change_already_pending'; end if;
    update public.ride_change_requests set status='cancelled' where ride_id=v_id and status='pending' and is_planning;
    insert into public.ride_change_requests(department_id,week_start,requester_id,ride_id,car_id,starts_at,ends_at,expected_version,is_planning)
      values(v_dept,v_week,(select auth.uid()),v_id,v_car,v_start,v_end,existing.version,true);
    return v_id;
  end if;
  perform set_config('app.coordinator_planning',case when wants_planning then 'on' else '' end,true);
  result:=public.edit_ride_before_planning(p_ride,p_expected_version);
  perform set_config('app.coordinator_planning',old_setting,true);
  -- A successful placement resolves its saved private shadow, if any.
  update public.ride_change_requests set status='cancelled' where ride_id=result and status='pending' and is_planning;
  return result;
end $$;


ALTER FUNCTION "public"."edit_ride_before_series"("p_ride" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eligible_leg_driver"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select q.requester_id from public.requests q join public.profiles p on p.id = q.requester_id
     where q.id = p_request_id and not p.does_not_drive),
    (select rc.profile_id from public.request_companions rc join public.profiles p on p.id = rc.profile_id
     where rc.request_id = p_request_id and not p.does_not_drive
     order by rc.profile_id limit 1)
  );
$$;


ALTER FUNCTION "public"."eligible_leg_driver"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification"("_recipient" "uuid", "_event" "public"."notification_event", "_department_id" "uuid", "_week_start" "date", "_vars" "jsonb" DEFAULT '{}'::"jsonb", "_data" "jsonb" DEFAULT '{}'::"jsonb", "_dedupe_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_meta record;
  v_muted boolean;
  v_is_sadran_role_event boolean;
  v_bypass_mute boolean := false;
  v_inbox_title text; v_inbox_body text;
  v_push_title text; v_push_body text;
  v_notification_id uuid;
  v_sub record;
begin
  if _event = 'auto_approved' then return null; end if;
  _data := coalesce(_data, '{}'::jsonb);
  if nullif(_data ->> 'url', '') is null then
    _data := _data || jsonb_build_object('url', public.notification_default_url(_event, _data, _department_id, _week_start));
  end if;
  _vars := public.notification_context(_recipient,_department_id,_week_start,_data) || coalesce(_vars,'{}'::jsonb);

  select member_mutable, sadran_role into v_meta from public.notification_event_meta where event = _event;

  if not (coalesce(v_meta.member_mutable, false) = false and coalesce(v_meta.sadran_role, false) = false) then
    select coalesce(_event = any(p.muted_events), false) into v_muted from public.profiles p where p.id = _recipient;

    if v_muted then
      v_is_sadran_role_event := coalesce(v_meta.sadran_role, false)
        and (_event <> 'window_open' or _data->>'variant'='sadran');
      if v_is_sadran_role_event and _department_id is not null and _week_start is not null then
        select exists (select 1 from public.sadranim_of(_department_id, _week_start) s where s = _recipient)
          into v_bypass_mute;
      end if;
      if not v_bypass_mute then
        return null;
      end if;
    end if;
  end if;

  select title, body into v_inbox_title, v_inbox_body from public.notification_templates
  where event = _event and channel = 'inbox' and variant is not distinct from coalesce(_data->>'variant',case when _data ? 'ride_change_id' then 'ride_change' else null end);
  select title, body into v_push_title, v_push_body from public.notification_templates
  where event = _event and channel = 'push' and variant is not distinct from coalesce(_data->>'variant',case when _data ? 'ride_change_id' then 'ride_change' else null end);

  if v_inbox_body is null then
    select title,body into v_inbox_title,v_inbox_body from public.notification_templates
      where event=_event and channel='inbox' and variant is null;
  end if;
  if v_push_body is null then
    select title,body into v_push_title,v_push_body from public.notification_templates
      where event=_event and channel='push' and variant is null;
  end if;

  insert into public.notifications (recipient_id, department_id, week_start, event, title_he, body_he, data, dedupe_key)
  values (_recipient, _department_id, _week_start, _event,
          public.render_notification_text(v_inbox_title, _vars),
          public.render_notification_text(v_inbox_body, _vars),
          _data, _dedupe_key)
  on conflict (recipient_id, dedupe_key) where dedupe_key is not null do nothing
  returning id into v_notification_id;

  if v_notification_id is null then
    return null;   -- deduped
  end if;

  for v_sub in select id from public.push_subscriptions where profile_id = _recipient loop
    insert into public.push_outbox (notification_id, subscription_id, payload)
    values (v_notification_id, v_sub.id, jsonb_build_object(
      'title', public.render_notification_text(coalesce(v_push_title, v_inbox_title), _vars),
      'body', public.render_notification_text(coalesce(v_push_body, v_inbox_body), _vars),
      'url', _data ->> 'url',
      'tag', _dedupe_key
    ));
  end loop;

  return v_notification_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_notification"("_recipient" "uuid", "_event" "public"."notification_event", "_department_id" "uuid", "_week_start" "date", "_vars" "jsonb", "_data" "jsonb", "_dedupe_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_department_weeks"("p_department_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare w record;
begin
  if not (public.is_admin() or public.member_of(p_department_id)) then
    raise exception 'not_authorized' using errcode='P0001';
  end if;
  perform public.materialize_department_weeks(p_department_id,now());
  for w in update public.weeks set phase='solving'
    where department_id=p_department_id and phase='open' and close_at<=now()
    returning * loop
    perform public.enqueue_notification(s.profile_id,'window_closed_solve_now',w.department_id,w.week_start,
      '{}','{}',format('window_closed_solve_now:%s:%s',w.department_id,w.week_start))
      from public.sadranim_of(w.department_id,w.week_start) s(profile_id);
  end loop;
end $$;


ALTER FUNCTION "public"."ensure_department_weeks"("p_department_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_upcoming_week"("p_department_id" "uuid", "p_week_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare settings public.department_settings%rowtype; times record;
begin
  select ds.* into settings from public.department_settings ds
    join public.departments d on d.id=ds.department_id
    where ds.department_id=p_department_id and d.is_active;
  if not found then
    raise exception 'series_week_not_open' using errcode = 'MDR01';
  end if;
  select * into times from public.week_phase_timestamps(settings, p_week_start);
  insert into public.weeks(department_id,week_start,phase,open_at,close_at,publish_at)
    values(p_department_id,p_week_start,'upcoming',times.open_at,times.close_at,times.publish_at)
    on conflict(department_id,week_start) do nothing;
end $$;


ALTER FUNCTION "public"."ensure_upcoming_week"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enter_waiting_list"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result jsonb;
  request_id uuid;
  request_row public.requests%rowtype;
  week_row public.weeks%rowtype;
  request_day date;
begin
  if p_payload ? 'request_id' then raise exception 'request_not_editable' using errcode='P0001'; end if;
  result := public.submit_request(p_payload - 'waitlist');
  request_id := (result->>'request_id')::uuid;
  select * into request_row from public.requests where id=request_id for update;
  select * into week_row from public.weeks where department_id=request_row.department_id and week_start=request_row.week_start;
  request_day := (coalesce(request_row.depart_at,request_row.return_at) at time zone 'Asia/Jerusalem')::date;
  if week_row.phase not in ('published','live') or not request_day=any(week_row.published_days) then
    raise exception 'request_window_closed' using errcode='P0001';
  end if;

  if result->>'status' = 'assigned' then
    return result || jsonb_build_object('car_was_free', true);
  end if;

  if request_row.status <> 'waitlisted' then
    perform set_config('app.system_status_transition','on',true);
    update public.requests set status='waitlisted', status_reason='WAITLISTED_NO_CAR' where id=request_id;
    perform set_config('app.system_status_transition','off',true);
    return result || jsonb_build_object('status','waitlisted','reason','WAITLISTED_NO_CAR');
  end if;

  -- submit_request's own try_auto_approve() already waitlisted it (round-trip, no free car) —
  -- keep its result (status + reason already present) instead of overwriting.
  return result;
end;
$$;


ALTER FUNCTION "public"."enter_waiting_list"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_freed_offers"("_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_count int;
begin
  perform public.assert_not_direct_rpc('expire_freed_offers');
  update public.freed_slot_offers
  set status = 'expired', resolved_at = _now
  where status in ('open','pending_approval') and expires_at <= _now;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."expire_freed_offers"("_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_proposals"("_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_count int := 0; request_row record; r record; v_today date;
begin
  perform public.assert_not_direct_rpc('expire_proposals');
  v_today := (_now at time zone 'Asia/Jerusalem')::date;
  for request_row in
    select q.id, q.department_id, q.week_start,
      (coalesce(q.depart_at, q.return_at) at time zone 'Asia/Jerusalem')::date as req_day
    from public.requests q
    where exists(select 1 from public.proposals p where p.request_id = q.id and p.status = 'sent')
    order by q.id for update skip locked
  loop
    if request_row.req_day < v_today
      or public.is_day_public(request_row.department_id, request_row.week_start, request_row.req_day)
    then
      for r in
        update public.proposals set status = 'expired'
        where request_id = request_row.id and status = 'sent'
        returning id, department_id, week_start, request_id, previous_status, created_by
      loop
        v_count := v_count + 1;
        perform public.enqueue_notification(r.created_by, 'proposal_answered', r.department_id, r.week_start,
          '{}'::jsonb, jsonb_build_object('variant', 'expired', 'request_id', r.request_id),
          format('proposal_expired:%s', r.id));
      end loop;
    end if;
  end loop;
  return v_count;
end $$;


ALTER FUNCTION "public"."expire_proposals"("_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fairness_stats"("p_department_id" "uuid", "p_week_start" "date", "p_lookback_weeks" integer) RETURNS TABLE("profile_id" "uuid", "granted_hours" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode='P0001';
  end if;

  return query
    select p.id,
      coalesce(sum(
        coalesce(
          extract(epoch from (q.return_at - q.depart_at)) / 3600.0,
          (select sum(extract(epoch from (r.ends_at-r.starts_at)) / 3600.0)
           from public.ride_requests rr join public.rides r on r.id=rr.ride_id
           where rr.request_id=q.id and r.status<>'cancelled')
        )
      ) filter (where q.status in ('assigned','merged')), 0)::numeric as granted_hours
    from public.department_members dm
    join public.profiles p on p.id=dm.profile_id
    left join public.requests q on q.requester_id=p.id and q.department_id=p_department_id
      and q.week_start >= p_week_start-(p_lookback_weeks*7) and q.week_start<p_week_start
    where dm.department_id=p_department_id and dm.removed_at is null
    group by p.id;
end;
$$;


ALTER FUNCTION "public"."fairness_stats"("p_department_id" "uuid", "p_week_start" "date", "p_lookback_weeks" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flag_rides_in_maintenance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride record;
  v_sadran_id uuid;
begin
  for v_ride in
    select r.id, r.department_id, r.week_start, r.driver_id
    from public.rides r
    where r.car_id = new.car_id and r.status not in ('cancelled','flagged')
      and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(new.starts_at, new.ends_at, '[)')
  loop
    update public.rides set status = 'flagged', flag_reason = 'maintenance' where id = v_ride.id;
    perform public.enqueue_notification(v_ride.driver_id, 'maintenance_affects', v_ride.department_id, v_ride.week_start,
      '{}'::jsonb, jsonb_build_object('ride_id', v_ride.id), format('maintenance_affects:%s:%s', v_ride.id, new.id));
    for v_sadran_id in select * from public.sadranim_of(v_ride.department_id, v_ride.week_start) loop
      perform public.enqueue_notification(v_sadran_id, 'maintenance_affects', v_ride.department_id, v_ride.week_start,
        '{}'::jsonb, jsonb_build_object('ride_id', v_ride.id),
        format('maintenance_affects:%s:%s:%s', v_ride.id, new.id, v_sadran_id));
    end loop;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "public"."flag_rides_in_maintenance"() OWNER TO "postgres";


