CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_invite record;
  v_email text := lower(trim(coalesce(new.email, '')));
  v_profile_id uuid;
  v_admin_id uuid;
begin
  select * into v_invite from public.member_invites where email = v_email and consumed_at is null limit 1;

  insert into public.profiles (id, email, full_name, phone, approval_status, default_department_id, approved_at)
  values (
    new.id, v_email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', ''),
    v_invite.phone,
    case when v_invite.id is not null then 'approved'::public.approval_status else 'pending'::public.approval_status end,
    v_invite.department_id,
    case when v_invite.id is not null then now() else null end
  )
  returning id into v_profile_id;

  if v_invite.id is not null then
    update public.member_invites set consumed_at = now() where id = v_invite.id;
    insert into public.department_members (department_id, profile_id, role)
    values (v_invite.department_id, v_profile_id, coalesce(v_invite.role, 'member'))
    on conflict (department_id, profile_id) do nothing;
  else
    -- Hebrew copy lives only in notification_templates (hard rule 3); enqueue_notification
    -- is defined later (20260907091200_notifications.sql) but resolved at call time.
    for v_admin_id in select id from public.profiles where is_admin and approval_status='approved' loop
      perform public.enqueue_notification(v_admin_id, 'access_request', null, null,
        jsonb_build_object('email', v_email), jsonb_build_object('email', v_email,'profile_id',v_profile_id,'url','/admin/members'),
        format('access_request:%s', v_email));
    end loop;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."haversine_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (6371 * 2 * asin(least(1, sqrt(
    sin(radians((lat2 - lat1)::double precision) / 2) ^ 2 +
    cos(radians(lat1::double precision)) * cos(radians(lat2::double precision)) *
    sin(radians((lng2 - lng1)::double precision) / 2) ^ 2
  ))))::numeric;
$$;


ALTER FUNCTION "public"."haversine_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."housekeeping"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_hour int; v_last_prune date;
begin
  perform public.assert_not_direct_rpc('housekeeping');
  perform public.expire_freed_offers(p_now);

  v_hour := extract(hour from (p_now at time zone 'Asia/Jerusalem'));
  select (value ->> 'value')::date into v_last_prune from public.app_settings where key = 'housekeeping_last_run';

  if v_last_prune is null or v_last_prune < (p_now at time zone 'Asia/Jerusalem')::date then
    perform public.materialize_templates();

    if v_hour >= 3 then
      delete from public.notifications where created_at < p_now - interval '90 days';
      delete from public.push_outbox where status in ('sent', 'dead') and created_at < p_now - interval '30 days';
      delete from public.client_errors where created_at < p_now - interval '90 days';
      delete from public.push_subscriptions where last_used_at < p_now - interval '180 days';
      -- token_hash cannot be null (unique not-null column); scramble it instead so old links die.
      update public.proposals set token_hash = encode(digest(gen_random_uuid()::text, 'sha256'), 'hex')
      where expires_at < p_now - interval '30 days' and status in ('expired', 'withdrawn', 'applied', 'declined');
      delete from public.audit_log where at < p_now - interval '1 year'
        and table_name not in ('requests', 'rides', 'proposals', 'policies', 'weeks', 'siddur_versions');
      delete from public.audit_log where at < p_now - interval '3 years';
      delete from public.request_templates where not is_active and updated_at < p_now - interval '1 year';

      insert into public.app_settings (key, value, updated_at)
      values ('housekeeping_last_run', to_jsonb((p_now at time zone 'Asia/Jerusalem')::date::text), p_now)
      on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."housekeeping"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_department_catalogs"("p_department_id" "uuid", "p_source_department_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare d record; c record; p record; v record; new_id uuid; new_policy_id uuid; new_version_id uuid; source_home uuid;
begin
  if not public.is_admin() then raise exception 'not_authorized' using errcode='P0001'; end if;
  select * into d from public.departments where id=p_department_id for update;
  if not found or p_department_id=p_source_department_id then raise exception 'invalid_department' using errcode='P0001'; end if;
  select home_destination_id into source_home from public.departments where id=p_source_department_id;
  if not found then raise exception 'invalid_department' using errcode='P0001'; end if;
  if exists(select 1 from public.destinations where department_id=p_department_id)
    or exists(select 1 from public.ride_types where department_id=p_department_id)
    or exists(select 1 from public.policies where department_id=p_department_id)
    or d.home_destination_id is not null then raise exception 'department_catalogs_already_initialized' using errcode='P0001'; end if;
  perform set_config('app.audit_reason','initialize_department_catalogs',true);
  for c in select * from public.destinations where department_id=p_source_department_id and is_approved loop
    insert into public.destinations(department_id,name,aliases,zone,lat,lng,distance_km,travel_minutes,public_transport_score,is_approved,created_by)
    values(p_department_id,c.name,c.aliases,c.zone,c.lat,c.lng,c.distance_km,c.travel_minutes,c.public_transport_score,true,(select auth.uid())) returning id into new_id;
    if c.id=source_home then update public.departments set home_destination_id=new_id where id=p_department_id; end if;
  end loop;
  insert into public.ride_types(department_id,code,name_he,sort_order,is_active)
    select p_department_id,code,name_he,sort_order,is_active from public.ride_types where department_id=p_source_department_id;
  for p in select * from public.policies where department_id=p_source_department_id loop
    insert into public.policies(department_id,name,is_active,created_by) values(p_department_id,p.name,p.is_active,(select auth.uid())) returning id into new_policy_id;
    if p.current_version_id is not null then
      select * into v from public.policy_versions where id=p.current_version_id;
      insert into public.policy_versions(policy_id,version_no,rules,note,created_by) values(new_policy_id,1,v.rules,'Copied from department '||p_source_department_id::text,(select auth.uid())) returning id into new_version_id;
      update public.policies set current_version_id=new_version_id where id=new_policy_id;
    end if;
  end loop;
end $$;


