CREATE OR REPLACE FUNCTION "public"."join_waitlist_group"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req record; v_day date; v_turnaround interval; v_group uuid; v_other uuid;
begin
  select * into v_req from public.requests where id = p_request_id;
  if v_req.id is null or v_req.trip_shape <> 'round_trip' or v_req.status <> 'waitlisted'
     or v_req.depart_at is null or v_req.return_at is null
     or v_req.series_id is not null then                -- REQ §13.77: series are never grouped
    return null;
  end if;
  if exists (select 1 from public.waitlist_group_members m
             where m.request_id = p_request_id and m.chosen is null) then
    return null;
  end if;

  v_day := (v_req.depart_at at time zone 'Asia/Jerusalem')::date;
  if not public.is_day_public(v_req.department_id, v_req.week_start, v_day) then
    return null;
  end if;

  select make_interval(mins => s.turnaround_minutes) into v_turnaround
  from public.department_settings s where s.department_id = v_req.department_id;
  v_turnaround := coalesce(v_turnaround, interval '30 minutes');

  select g.id into v_group
  from public.waitlist_groups g
  where g.department_id = v_req.department_id and g.week_start = v_req.week_start
    and g.day = v_day and g.status = 'open'
    and tstzrange(g.starts_at, g.ends_at + v_turnaround, '[)')
        && tstzrange(v_req.depart_at, v_req.return_at + v_turnaround, '[)')
  order by g.starts_at, g.id limit 1
  for update;

  if v_group is not null then
    insert into public.waitlist_group_members (group_id, request_id, profile_id, department_id, week_start,
      depart_at, return_at, adults, child_seats, boosters, destination)
    select v_group, v_req.id, v_req.requester_id, v_req.department_id, v_req.week_start,
      v_req.depart_at, v_req.return_at, v_req.adults, v_req.child_seats, v_req.boosters,
      coalesce(d.name, v_req.destination_text)
    from (select 1) x left join public.destinations d on d.id = v_req.destination_id;

    perform set_config('app.audit_reason', 'waitlist_group_joined', true);
    update public.waitlist_groups
    set starts_at = least(starts_at, v_req.depart_at), ends_at = greatest(ends_at, v_req.return_at)
    where id = v_group;

    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status_reason = 'WAITLISTED_CONTESTED' where id = p_request_id;
    perform set_config('app.system_status_transition', 'off', true);

    perform public.notify_waitlist_contested(v_group, 'joined', v_req.requester_id);
    return v_group;
  end if;

  select q.id into v_other
  from public.requests q
  where q.department_id = v_req.department_id and q.week_start = v_req.week_start
    and q.id <> p_request_id and q.trip_shape = 'round_trip' and q.status = 'waitlisted'
    and q.series_id is null
    and (q.depart_at at time zone 'Asia/Jerusalem')::date = v_day
    and not exists (select 1 from public.waitlist_group_members m
                    where m.request_id = q.id and m.chosen is null)
    and tstzrange(q.depart_at, q.return_at + v_turnaround, '[)')
        && tstzrange(v_req.depart_at, v_req.return_at + v_turnaround, '[)')
  order by q.created_at, q.id limit 1;

  if v_other is null then return null; end if;

  v_group := public.create_waitlist_group(v_req.department_id, v_req.week_start, v_day,
    array[v_other, p_request_id]);
  if v_group is null then return null; end if;
  perform public.notify_waitlist_contested(v_group);
  return v_group;
end;
$$;


ALTER FUNCTION "public"."join_waitlist_group"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."joinable_rides_for_request"("p_request_id" "uuid") RETURNS TABLE("ride_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "car_name" "text", "car_type" "public"."car_type", "destination_name" "text", "driver_name" "text", "distance_km" numeric, "free_seats" integer, "driver_phone" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.requests;
  v_radius numeric;
  v_use_return boolean;
  v_anchor timestamptz;
begin
  select * into v_request from public.requests where id = p_request_id;
  if not found then
    raise exception 'request_not_found' using errcode = 'P0001';
  end if;
  if not (v_request.requester_id = (select auth.uid()) or public.can_manage_week(v_request.department_id, v_request.week_start)) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  -- Free-text destination (owner A8) or free-text origin (REQ §13.93): nothing to compare
  -- against, no rows.
  if v_request.destination_id is null or v_request.origin_id is null then
    return;
  end if;

  select coalesce(s.join_radius_km, 10) into v_radius
  from public.department_settings s where s.department_id = v_request.department_id;

  -- Waiting-list-only, published/live weeks only (owner A10) — defensive: the client only ever
  -- calls this after a `waitlisted` result, which itself only happens once try_auto_approve()/
  -- enter_waiting_list() has run (published/live weeks), but this guard makes the RPC's own
  -- contract hold regardless of caller.
  if not exists (
    select 1 from public.weeks w
    where w.department_id = v_request.department_id and w.week_start = v_request.week_start
      and w.phase in ('published', 'live')
  ) then
    return;
  end if;

  v_use_return := (v_request.trip_shape = 'one_way_from');
  v_anchor := case when v_use_return then v_request.return_at else v_request.depart_at end;

  return query
  select
    rd.id,
    rd.starts_at,
    rd.ends_at,
    c.name,
    c.type,
    rdest.name,
    coalesce(p.full_name, ''),
    round(public.haversine_km(qdest.lat, qdest.lng, rdest.lat, rdest.lng), 1),
    greatest(coalesce(cfg.max_adults, 0) - coalesce(load.adults, 0), 0)::int,
    p.phone
  from public.rides rd
  join lateral (
    select q2.id as request_id, q2.destination_id, rr2.leg
    from public.ride_requests rr2
    join public.requests q2 on q2.id = rr2.request_id
    where rr2.ride_id = rd.id
    order by (rr2.role = 'driver') desc, rr2.request_id
    limit 1
  ) trip on true
  left join lateral (
    select array_agg(pt.place_id order by pt."position") as route_ids
    from public.request_leg_route_points(trip.request_id, case when trip.leg = 'return' then 'return'::public.ride_leg else 'out'::public.ride_leg end) pt
  ) route on true
  join public.destinations rdest on rdest.id = trip.destination_id
  join public.destinations qdest on qdest.id = v_request.destination_id
  join public.cars c on c.id = rd.car_id
  left join public.profiles p on p.id = rd.driver_id
  left join lateral (
    select max(adults) as max_adults from public.car_seat_configs where car_id = rd.car_id
  ) cfg on true
  left join lateral (
    select sum(q.adults)::int as adults
    from public.ride_requests rr
    join public.requests q on q.id = rr.request_id
    where rr.ride_id = rd.id
  ) load on true
  where rd.department_id = v_request.department_id
    and rd.week_start = v_request.week_start
    and rd.status <> 'cancelled'
    -- REQ §13.93 "Multi-stop rides": the candidate's origin is any place on the host's served
    -- leg route (same-origin is the a = route[0] special case); destination stays a radius
    -- match, same as before stops existed.
    and route.route_ids is not null
    and array_position(route.route_ids, v_request.origin_id) is not null
    -- REQ §13.95 H1: boards strictly before the route's final destination, detour within the limits.
    and array_position(route.route_ids, v_request.origin_id) < cardinality(route.route_ids)
    and coalesce((public._merge_check(rd.id, v_request.id,
          (case when v_use_return then 'return' else 'out' end)::public.ride_leg) ->> 'ok')::boolean, false)
    and qdest.lat is not null and qdest.lng is not null
    and rdest.lat is not null and rdest.lng is not null
    and public.haversine_km(qdest.lat, qdest.lng, rdest.lat, rdest.lng) <= v_radius
    and (case when v_use_return then rd.ends_at else rd.starts_at end at time zone 'Asia/Jerusalem')::date
        = (v_anchor at time zone 'Asia/Jerusalem')::date
    and abs(extract(epoch from ((case when v_use_return then rd.ends_at else rd.starts_at end) - v_anchor))) <= 120 * 60
    and greatest(coalesce(cfg.max_adults, 0) - coalesce(load.adults, 0), 0) >= 1
    and not exists (select 1 from public.ride_requests xr where xr.ride_id = rd.id and xr.request_id = v_request.id)
  order by 8 asc, rd.starts_at asc, rd.id asc;
end;
$$;


ALTER FUNCTION "public"."joinable_rides_for_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_car_care"("_car_id" "uuid", "_kind" "public"."car_care_kind", "_tires" "jsonb" DEFAULT NULL::"jsonb", "_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid;
  v_car_name text;
  v_by_name text;
  v_event_id uuid;
  v_recipient uuid;
  v_low_count int := 0;
  v_very_low_count int := 0;
  v_key_count int;
  v_bad_key_count int;
  v_bad_value_count int;
  v_tires jsonb;
begin
  select department_id, name into v_dept, v_car_name from public.cars where id = _car_id;
  if v_dept is null then
    raise exception 'car_not_found' using errcode = 'P0001';
  end if;
  if not public.member_of(v_dept) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  if _kind = 'tire_fill' then
    if _tires is null or jsonb_typeof(_tires) <> 'object' then
      raise exception 'tires_required' using errcode = 'P0001';
    end if;
    select count(*) into v_key_count from jsonb_object_keys(_tires) k;
    select count(*) into v_bad_key_count from jsonb_object_keys(_tires) k
      where k not in ('front_left', 'front_right', 'rear_left', 'rear_right', 'spare');
    if v_key_count <> 5 or v_bad_key_count > 0 then
      raise exception 'tires_incomplete' using errcode = 'P0001';
    end if;
    select count(*) into v_bad_value_count from jsonb_each_text(_tires) e
      where e.value not in ('ok', 'low', 'very_low');
    if v_bad_value_count > 0 then
      raise exception 'invalid_tire_state' using errcode = 'P0001';
    end if;
    select count(*) filter (where e.value = 'low'), count(*) filter (where e.value = 'very_low')
      into v_low_count, v_very_low_count
    from jsonb_each_text(_tires) e;
    v_tires := _tires;
  else
    v_tires := null;
  end if;

  insert into public.car_care_events (department_id, car_id, kind, tires, note, reported_by)
  values (v_dept, _car_id, _kind, v_tires, _note, (select auth.uid()))
  returning id into v_event_id;

  select full_name into v_by_name from public.profiles where id = (select auth.uid());

  for v_recipient in select * from public.car_care_recipients(_car_id) loop
    perform public.enqueue_notification(v_recipient, 'car_care', v_dept, null,
      jsonb_build_object('carName', v_car_name, 'byName', coalesce(v_by_name, ''),
        'lowCount', v_low_count::text, 'veryLowCount', v_very_low_count::text),
      jsonb_build_object('variant', _kind::text, 'car_id', _car_id, 'car_care_event_id', v_event_id),
      format('car_care:%s:%s:%s', _kind::text, v_event_id, v_recipient));
  end loop;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."log_car_care"("_car_id" "uuid", "_kind" "public"."car_care_kind", "_tires" "jsonb", "_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_department_weeks"("p_department_id" "uuid", "p_now" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare settings public.department_settings%rowtype; target date; local_day date;
  times record; n int; total int:=0;
begin
  select ds.* into settings from public.department_settings ds
    join public.departments d on d.id=ds.department_id
    where ds.department_id=p_department_id and d.is_active;
  if not found then return 0; end if;
  local_day:=(p_now at time zone 'Asia/Jerusalem')::date;
  for offset_weeks in 0..greatest(0,settings.weeks_open_ahead) loop
    target:=local_day-extract(dow from local_day)::int+7*offset_weeks;
    select * into times from public.week_phase_timestamps(settings, target);
    if times.open_at > p_now then continue; end if;
    insert into public.weeks(department_id,week_start,phase,open_at,close_at,publish_at)
      values(p_department_id,target,'open',times.open_at,times.close_at,times.publish_at)
      on conflict(department_id,week_start) do update
        set phase='open', open_at=excluded.open_at, close_at=excluded.close_at, publish_at=excluded.publish_at
        where public.weeks.phase='upcoming';
    get diagnostics n=row_count;
    total:=total+n;
  end loop;
  return total;
end $$;


ALTER FUNCTION "public"."materialize_department_weeks"("p_department_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


