CREATE OR REPLACE FUNCTION "public"."move_series"("p_series_id" "uuid", "p_new_car_id" "uuid", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid; v_home uuid; v_first timestamptz; v_last timestamptz; v_turnaround interval;
  v_weeks date[]; w date; v_first_ride public.rides%rowtype; v_old_car uuid;
begin
  select (array_agg(q.department_id))[1], min(q.depart_at), max(q.return_at), array_agg(distinct q.week_start)
    into v_dept, v_first, v_last, v_weeks
  from public.requests q where q.series_id = p_series_id and q.status not in ('withdrawn','cancelled');
  if v_dept is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;

  foreach w in array v_weeks loop
    if not public.can_manage_week(v_dept, w) then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  end loop;

  select * into v_first_ride from public.rides
  where series_id = p_series_id and status <> 'cancelled' order by starts_at, id limit 1 for update;
  if v_first_ride.id is null then
    return public.place_series(p_series_id, p_new_car_id, true, 'SERIES_PLACED');
  end if;
  if p_expected_version is not null and v_first_ride.version <> p_expected_version then
    perform public.raise_stale_version();
  end if;
  v_old_car := v_first_ride.car_id;
  if v_old_car = p_new_car_id then
    return jsonb_build_object('series_id', p_series_id, 'car_id', p_new_car_id, 'moved', 0);
  end if;

  begin
    if not exists (select 1 from public.cars c
      where c.id = p_new_car_id and c.department_id = v_dept and c.status = 'active' and c.type = 'shared') then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_not_shared_active';
    end if;
    if exists (select 1 from public.requests q where q.series_id = p_series_id
      and not public.car_fits(p_new_car_id, q.adults, q.child_seats, q.boosters)) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'seat_config_violation';
    end if;

    select coalesce(make_interval(mins => s.turnaround_minutes), interval '30 minutes') into v_turnaround
    from public.department_settings s where s.department_id = v_dept;
    v_turnaround := coalesce(v_turnaround, interval '30 minutes');
    select d.home_destination_id into v_home from public.departments d where d.id = v_dept;

    if exists (select 1 from public.rides r
      where r.car_id = p_new_car_id and r.status <> 'cancelled' and not r.planning_conflict
        and r.series_id is distinct from p_series_id
        and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_first, v_last + v_turnaround, '[)')) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_busy';
    end if;
    if exists (select 1 from public.car_maintenance_blocks b where b.car_id = p_new_car_id
      and tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(v_first, v_last + v_turnaround, '[)')) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'ride_conflicts_with_maintenance';
    end if;
    if coalesce((select r.destination_id from public.rides r
      where r.car_id = p_new_car_id and r.status <> 'cancelled' and not r.planning_conflict
        and r.series_id is distinct from p_series_id and r.starts_at < v_first
        and not public.ride_is_reservation(r.id)
      order by r.starts_at desc limit 1), v_home) <> v_home then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_not_home';
    end if;

    perform set_config('app.audit_reason', 'move_series', true);
    update public.rides set car_id = p_new_car_id where series_id = p_series_id and status <> 'cancelled';

    foreach w in array v_weeks loop
      perform public.refresh_car_turnarounds(p_new_car_id, w);
      perform public.refresh_car_turnarounds(v_old_car, w);
      perform public.assert_car_chain(p_new_car_id, w);
      perform public.assert_car_chain(v_old_car, w);
    end loop;
  exception when others then
    if sqlstate = 'MDR03' then raise; end if;
    raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = sqlerrm;
  end;

  return jsonb_build_object('series_id', p_series_id, 'car_id', p_new_car_id,
    'moved', (select count(*) from public.rides where series_id = p_series_id and status <> 'cancelled'));
end $$;


ALTER FUNCTION "public"."move_series"("p_series_id" "uuid", "p_new_car_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_public_request_details"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.ride_description:=nullif(trim(new.ride_description),'');
  if length(new.ride_description)>1000 then raise exception 'invalid_ride_description';end if;
  select coalesce(array_agg(trim(name) order by n),'{}') into new.guest_passenger_names
    from unnest(coalesce(new.guest_passenger_names,'{}')) with ordinality x(name,n) where nullif(trim(name),'') is not null;
  if cardinality(new.guest_passenger_names)>20 or exists(select 1 from unnest(new.guest_passenger_names) name where length(name)>100) then raise exception 'invalid_passenger_names';end if;
  if tg_table_name='request_templates' then
    new.companion_ids:=coalesce(new.companion_ids,'{}');
    if cardinality(new.companion_ids)>20 or cardinality(new.companion_ids)<>(select count(distinct id) from unnest(new.companion_ids) id)
      or exists(select 1 from unnest(new.companion_ids) candidate(profile_id) where candidate.profile_id=new.requester_id or not exists(
        select 1 from public.profiles p join public.department_members dm on dm.profile_id=p.id
        where p.id=candidate.profile_id and p.approval_status='approved' and dm.department_id=new.department_id and dm.removed_at is null)) then raise exception 'invalid_companions';end if;
    if cardinality(new.companion_ids)+cardinality(new.guest_passenger_names)>new.adults+new.child_seats+new.boosters-1 then raise exception 'passenger_names_exceed_seats';end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."normalize_public_request_details"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_context"("_recipient" "uuid", "_department_id" "uuid", "_week_start" "date", "_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare q public.requests%rowtype; r public.rides%rowtype; pr public.proposals%rowtype; w public.weeks%rowtype;
  v jsonb; dt timestamptz; dest text; fullname text; carname text;
  v_home uuid; v_origin_name text; v_origin text; v_route text; v_trip_type text;
begin
  select * into w from public.weeks where department_id=_department_id and week_start=_week_start;
  select * into pr from public.proposals where id=nullif(_data->>'proposal_id','')::uuid;
  select * into q from public.requests where id=coalesce(nullif(_data->>'request_id','')::uuid,pr.request_id);
  select rd.* into r from public.rides rd where rd.id=coalesce(nullif(_data->>'ride_id','')::uuid,pr.ride_id,
    (select rr.ride_id from public.ride_requests rr join public.rides x on x.id=rr.ride_id where rr.request_id=q.id and x.status<>'cancelled' limit 1));
  select name into dest from public.destinations where id=q.destination_id;
  select full_name into fullname from public.profiles where id=coalesce(q.requester_id,_recipient);
  select name into carname from public.cars where id=r.car_id;
  dt:=coalesce(q.depart_at,q.return_at,r.starts_at);

  select home_destination_id into v_home from public.departments where id=_department_id;
  select name into v_origin_name from public.destinations where id=q.origin_id;
  v_origin_name := coalesce(v_origin_name, q.origin_text);
  v_origin := case when q.id is null or q.origin_id is null or q.origin_id = v_home then '' else coalesce(v_origin_name,'') end;

  if q.id is not null then
    v_route := public.request_route_label(q.id);
  else
    v_route := public.render_notification_text(
      (select body from public.text_fragments where key='route.to'),
      jsonb_build_object('destination', coalesce(dest,q.destination_text,'')));
  end if;

  v_trip_type := coalesce((select body from public.text_fragments where key = 'trip_type.' || q.trip_type::text), '');

  v:=jsonb_build_object('weekLabel',to_char(_week_start,'DD/MM/YY'),
    'closeTime',to_char(w.close_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI'),
    'firstName',coalesce(fullname,''),'destination',coalesce(dest,q.destination_text,''),
    'origin',v_origin,'route',coalesce(v_route,''),'tripType',v_trip_type,
    'date',to_char(dt at time zone 'Asia/Jerusalem','DD/MM/YY'),'day',public.day_date_label(dt),
    'depart',to_char(coalesce(r.starts_at,q.depart_at) at time zone 'Asia/Jerusalem','HH24:MI'),
    'return',to_char(coalesce(r.ends_at,q.return_at) at time zone 'Asia/Jerusalem','HH24:MI'),
    'car',coalesce(carname,''),'outcomeLine',coalesce(carname,dest,q.destination_text,''),
    'diffLine',concat_ws(' · ',carname,to_char(coalesce(r.starts_at,dt) at time zone 'Asia/Jerusalem','DD/MM HH24:MI')),
    'sadranName',(select full_name from public.profiles where id=pr.created_by),
    -- N3: the composer's stored WhatsApp text keeps `{{link}}` for send time; a member's
    -- inbox/push must never show the raw token (the row itself deep-links via _data.url).
    'proposalShort',public.render_notification_text(coalesce(pr.reason_he,''),jsonb_build_object('link','')),
    'expiresAt',to_char(pr.expires_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI'),
    'count',coalesce(_data->>'count',''),'email',(select email from public.profiles where id=_recipient));
  return v;
end $$;


ALTER FUNCTION "public"."notification_context"("_recipient" "uuid", "_department_id" "uuid", "_week_start" "date", "_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_default_url"("_event" "public"."notification_event", "_data" "jsonb", "_department_id" "uuid", "_week_start" "date") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_token text := nullif(_data ->> 'token', '');
  v_proposal_id uuid := nullif(_data ->> 'proposal_id', '')::uuid;
  v_ride_change_id uuid := nullif(_data ->> 'ride_change_id', '')::uuid;
  v_request_id uuid := coalesce(nullif(_data ->> 'request_id', '')::uuid, nullif(_data ->> 'offer_id', '')::uuid);
  v_ride_id uuid := nullif(_data ->> 'ride_id', '')::uuid;
  v_car_id uuid := nullif(_data ->> 'car_id', '')::uuid;
  v_group_id uuid := nullif(_data ->> 'group_id', '')::uuid;
  v_day text := nullif(_data ->> 'day', '');
  v_week_scoped boolean;
  v_sadran_role boolean;
  v_is_sadran_event boolean;
begin
  if v_token is not null then
    return '/p/' || v_token;
  end if;

  if v_proposal_id is not null and _department_id is not null and _week_start is not null then
    return format('/sadran/%s/%s/proposals?proposal=%s', _department_id, _week_start, v_proposal_id);
  end if;

  if v_group_id is not null and v_day is not null and _department_id is not null and _week_start is not null then
    return format('/siddur/%s/%s?day=%s&group=%s', _department_id, _week_start, v_day, v_group_id);
  end if;

  if v_ride_change_id is not null then
    return format('/inbox?change=%s', v_ride_change_id);
  end if;

  if v_request_id is not null then
    return format('/requests?focus=%s', v_request_id);
  end if;

  if v_ride_id is not null and _department_id is not null and _week_start is not null then
    return format('/siddur/%s/%s?ride=%s', _department_id, _week_start, v_ride_id);
  end if;

  if v_car_id is not null then
    return format('/cars/%s', v_car_id);
  end if;

  select week_scoped, sadran_role into v_week_scoped, v_sadran_role
  from public.notification_event_meta where event = _event;

  if _department_id is not null and _week_start is not null and coalesce(v_week_scoped, false) then
    v_is_sadran_event := coalesce(v_sadran_role, false)
      and (_event <> 'window_open' or _data ->> 'variant' = 'sadran');
    if v_is_sadran_event then
      return format('/sadran/%s/%s', _department_id, _week_start);
    end if;
    return format('/siddur/%s/%s', _department_id, _week_start);
  end if;

  return '/inbox';
end;
$$;


ALTER FUNCTION "public"."notification_default_url"("_event" "public"."notification_event", "_data" "jsonb", "_department_id" "uuid", "_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notifications_protect_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.title_he is distinct from old.title_he or new.body_he is distinct from old.body_he
     or new.event is distinct from old.event or new.data is distinct from old.data
     or new.dedupe_key is distinct from old.dedupe_key or new.recipient_id is distinct from old.recipient_id then
    raise exception 'notification_fields_locked' using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."notifications_protect_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_department_member_status_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare member_row public.department_members%rowtype; variant text; department_name text;
begin
  if tg_op='DELETE' then
    member_row:=old; variant:='removed';
  else
    member_row:=new;
    if tg_op='UPDATE' then
      if old.role is not distinct from new.role and (old.removed_at is null)=(new.removed_at is null) then return new; end if;
    end if;
    variant:=case when new.removed_at is not null then 'removed' else new.role::text end;
  end if;
  -- Cascading account/department deletion has no remaining recipient/context.
  if not exists(select 1 from public.profiles where id=member_row.profile_id) then return null; end if;
  select name into department_name from public.departments where id=member_row.department_id;
  if not found then return null; end if;
  perform public.enqueue_notification(member_row.profile_id,'status_changed',member_row.department_id,null,
    jsonb_build_object('departmentName',department_name),
    jsonb_build_object('variant',variant,'url','/profile','department_id',member_row.department_id));
  return null;
end $$;


ALTER FUNCTION "public"."notify_department_member_status_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_profile_status_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare administrator uuid;
begin
  if new.approval_status is distinct from old.approval_status then
    if new.approval_status='approved' then
      perform public.enqueue_notification(new.id,'access_approved',null,null,'{}',jsonb_build_object('url','/'));
    else
      perform public.enqueue_notification(new.id,'status_changed',null,null,'{}',
        jsonb_build_object('variant',new.approval_status::text,'url','/pending'));
      if new.approval_status='pending' then
        for administrator in select id from public.profiles where is_admin and approval_status='approved' loop
          perform public.enqueue_notification(administrator,'access_request',null,null,
            jsonb_build_object('email',new.email),jsonb_build_object('url','/admin/members','profile_id',new.id));
        end loop;
      end if;
    end if;
  end if;
  if new.is_admin is distinct from old.is_admin then
    perform public.enqueue_notification(new.id,'status_changed',null,null,'{}',
      jsonb_build_object('variant',case when new.is_admin then 'admin_granted' else 'admin_revoked' end,
        'url',case when new.is_admin and new.approval_status='approved' then '/admin' else '/' end));
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."notify_profile_status_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_waitlist_contested"("_group_id" "uuid", "_variant" "text" DEFAULT NULL::"text", "_new_profile" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  g record; m record; v_sadran uuid;
  v_all text; v_others text; v_new_name text; v_count int;
  v_day text; v_depart text; v_return text; v_data jsonb; v_key text;
begin
  select * into g from public.waitlist_groups where id = _group_id;
  if g.id is null or g.status <> 'open' then return; end if;

  select count(*), string_agg(coalesce(p.full_name, ''), ', ' order by m2.created_at, m2.id)
    into v_count, v_all
  from public.waitlist_group_members m2
  join public.profiles p on p.id = m2.profile_id
  where m2.group_id = _group_id and m2.chosen is null;

  select full_name into v_new_name from public.profiles where id = _new_profile;
  v_key := coalesce(_new_profile::text, 'new');
  v_day := to_char(g.day, 'DD/MM');
  v_depart := to_char(g.starts_at at time zone 'Asia/Jerusalem', 'HH24:MI');
  v_return := to_char(g.ends_at at time zone 'Asia/Jerusalem', 'HH24:MI');

  for m in
    select m3.request_id, m3.profile_id
    from public.waitlist_group_members m3
    where m3.group_id = _group_id and m3.chosen is null
    order by m3.created_at, m3.id
  loop
    select string_agg(coalesce(p.full_name, ''), ', ' order by m4.created_at, m4.id) into v_others
    from public.waitlist_group_members m4
    join public.profiles p on p.id = m4.profile_id
    where m4.group_id = _group_id and m4.chosen is null and m4.request_id <> m.request_id;

    v_data := jsonb_build_object('group_id', _group_id, 'request_id', m.request_id, 'day', g.day::text);
    -- The newcomer gets the plain "you are in a contested group" copy; everyone already in
    -- the group gets the `joined` variant naming them.
    if _variant is not null and m.profile_id is distinct from _new_profile then
      v_data := v_data || jsonb_build_object('variant', _variant);
    end if;

    perform public.enqueue_notification(m.profile_id, 'waitlist_contested', g.department_id, g.week_start,
      jsonb_build_object('names', coalesce(v_others, ''), 'newName', coalesce(v_new_name, ''),
        'day', v_day, 'depart', v_depart, 'return', v_return, 'count', v_count::text),
      v_data,
      format('waitlist_contested:%s:%s:%s', _group_id, v_key, m.profile_id));
  end loop;

  for v_sadran in select * from public.sadranim_of(g.department_id, g.week_start) loop
    perform public.enqueue_notification(v_sadran, 'waitlist_contested', g.department_id, g.week_start,
      jsonb_build_object('names', coalesce(v_all, ''), 'newName', coalesce(v_new_name, ''),
        'day', v_day, 'depart', v_depart, 'return', v_return, 'count', v_count::text),
      jsonb_build_object('group_id', _group_id, 'day', g.day::text, 'variant', 'sadran'),
      format('waitlist_contested:%s:%s:sadran:%s', _group_id, v_key, v_sadran));
  end loop;
end;
$$;


ALTER FUNCTION "public"."notify_waitlist_contested"("_group_id" "uuid", "_variant" "text", "_new_profile" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_week_opened"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.phase <> 'open' then return new; end if;
  perform public.enqueue_notification(dm.profile_id,'window_open',new.department_id,new.week_start,
    '{}','{}',format('window_open:%s:%s',new.department_id,new.week_start))
    from public.department_members dm join public.profiles p on p.id=dm.profile_id
    where dm.department_id=new.department_id and dm.removed_at is null and p.approval_status='approved';
  perform public.enqueue_notification(s.profile_id,'window_open',new.department_id,new.week_start,
    jsonb_build_object('closeTime',to_char(new.close_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI'),
      'publishTime',to_char(new.publish_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI')),
    jsonb_build_object('variant','sadran','url','/sadran'),
    format('window_open_sadran:%s:%s',new.department_id,new.week_start))
    from public.sadranim_of(new.department_id,new.week_start) s(profile_id)
    join public.profiles p on p.id=s.profile_id where p.approval_status='approved';
  return new;
end $$;


ALTER FUNCTION "public"."notify_week_opened"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_week_sadran_assigned"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare w public.weeks%rowtype;
begin
  if new.week_start is null then return new; end if;
  select * into w from public.weeks where department_id=new.department_id and week_start=new.week_start;
  if not found or w.phase in ('archived','upcoming') then return new; end if;
  perform public.enqueue_notification(new.profile_id,'window_open',new.department_id,new.week_start,
    jsonb_build_object('closeTime',to_char(w.close_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI'),
      'publishTime',to_char(w.publish_at at time zone 'Asia/Jerusalem','DD/MM HH24:MI')),
    jsonb_build_object('variant','sadran','url','/sadran/'||new.department_id||'/'||new.week_start||'/board'),
    format('window_open_sadran:%s:%s',new.department_id,new.week_start));
  return new;
end $$;


ALTER FUNCTION "public"."notify_week_sadran_assigned"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_week"("p_department_id" "uuid", "p_week_start" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_settings record;
  v_open_at timestamptz;
  v_close_at timestamptz;
  v_publish_at timestamptz;
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  select * into v_settings from public.department_settings where department_id = p_department_id;

  v_open_at := ((p_week_start - 7 + v_settings.open_dow) + v_settings.open_time) at time zone 'Asia/Jerusalem';
  v_close_at := ((p_week_start - 7 + v_settings.close_dow) + v_settings.close_time) at time zone 'Asia/Jerusalem';
  v_publish_at := ((p_week_start - 7 + v_settings.publish_dow) + v_settings.publish_time) at time zone 'Asia/Jerusalem';

  perform set_config('app.audit_reason', 'open_week', true);
  insert into public.weeks (department_id, week_start, phase, open_at, close_at, publish_at, opened_by)
  values (p_department_id, p_week_start, 'open', v_open_at, v_close_at, v_publish_at, (select auth.uid()))
  on conflict (department_id, week_start) do update
    set phase = 'open', opened_by = excluded.opened_by
    where public.weeks.phase = 'upcoming';

  perform public.enqueue_notification(dm.profile_id, 'window_open', p_department_id, p_week_start,
    '{}'::jsonb, '{}'::jsonb, format('window_open:%s:%s', p_department_id, p_week_start))
  from public.department_members dm where dm.department_id = p_department_id and dm.removed_at is null;

  return p_department_id;
end;
$$;


ALTER FUNCTION "public"."open_week"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pair_one_way_legs"("p_dept" "uuid", "p_week" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_turnaround interval; v_travel int;
  out_leg record; ret_leg record;
  v_driver_out uuid; v_driver_ret uuid;
  v_out_start timestamptz; v_out_end timestamptz; v_ret_start timestamptz; v_ret_end timestamptz;
  v_target_car uuid;
  v_gap_override smallint;
  v_out_load record; v_ret_load record;
  v_prev_flag text;
begin
  v_turnaround := make_interval(mins => coalesce(public.required_turnaround_minutes(p_dept, p_week), 30));

  for out_leg in
    select r.id as ride_id, r.car_id, r.driver_id, r.needs_driver,
           rr.request_id, q.origin_id, q.destination_id, q.depart_at
    from public.rides r
    join public.ride_requests rr on rr.ride_id = r.id
    join public.requests q on q.id = rr.request_id
    where r.department_id = p_dept and r.week_start = p_week and r.status <> 'cancelled' and not r.planning_conflict
      and not r.auto_relocation and r.overnight_ack_by is null
      and q.trip_shape = 'one_way_to' and q.trip_type = 'drop_off'
      and q.origin_id is not null and q.destination_id is not null
      and (select count(*) from public.ride_requests rr2 where rr2.ride_id = r.id) = 1
    order by r.starts_at
  loop
    v_travel := greatest(coalesce(public.request_leg_route_minutes(out_leg.request_id, 'out'), 30), 0);
    v_out_start := out_leg.depart_at;
    v_out_end := v_out_start + make_interval(mins => v_travel);
    if not public.is_quarter_hour(v_out_end) then
      v_out_end := to_timestamp(ceil(extract(epoch from v_out_end) / 900) * 900);
    end if;

    select x.ride_id, x.car_id, x.request_id, x.ret_start, x.ret_end into ret_leg
    from (
      select r2.id as ride_id, r2.car_id, q2.id as request_id,
             q2.return_at - make_interval(mins => greatest(coalesce(public.request_leg_route_minutes(q2.id, 'return'), 30), 0)) as ret_start,
             q2.return_at as ret_end
      from public.requests q2
      join public.ride_requests rr2 on rr2.request_id = q2.id
      join public.rides r2 on r2.id = rr2.ride_id
      where q2.trip_shape = 'one_way_from' and q2.trip_type = 'drop_off'
        and q2.destination_id = out_leg.destination_id and q2.origin_id = out_leg.origin_id
        and r2.department_id = p_dept and r2.week_start = p_week and r2.status <> 'cancelled' and not r2.planning_conflict
        and not r2.auto_relocation and r2.overnight_ack_by is null
        and (select count(*) from public.ride_requests rr3 where rr3.ride_id = r2.id) = 1
      union all
      select r2.id, r2.car_id, q2.id,
             q2.depart_at,
             q2.depart_at + make_interval(mins => greatest(coalesce(public.request_leg_route_minutes(q2.id, 'out'), 30), 0))
      from public.requests q2
      join public.ride_requests rr2 on rr2.request_id = q2.id
      join public.rides r2 on r2.id = rr2.ride_id
      where q2.trip_shape = 'one_way_to' and q2.trip_type = 'drop_off'
        and q2.origin_id = out_leg.destination_id and q2.destination_id = out_leg.origin_id
        and r2.department_id = p_dept and r2.week_start = p_week and r2.status <> 'cancelled' and not r2.planning_conflict
        and not r2.auto_relocation and r2.overnight_ack_by is null
        and (select count(*) from public.ride_requests rr3 where rr3.ride_id = r2.id) = 1
    ) x
    -- REQ §13.88 (owner 2026-09-24): any non-overlapping gap at X pairs, even one shorter
    -- than the turnaround -- the car just waits there; the out-leg stores the actual gap.
    where x.ret_start >= v_out_end
    order by x.ret_start limit 1;

    if ret_leg.ride_id is null then continue; end if;

    v_driver_out := public.eligible_leg_driver(out_leg.request_id);
    v_driver_ret := public.eligible_leg_driver(ret_leg.request_id);
    if v_driver_out is null or v_driver_ret is null then continue; end if;

    -- Idempotent: already paired correctly (out-leg already relay with the right driver,
    -- on the same car as the return leg) — nothing to do.
    if out_leg.needs_driver = false and out_leg.driver_id = v_driver_out and out_leg.car_id = ret_leg.car_id then
      continue;
    end if;

    if not public.is_quarter_hour(ret_leg.ret_start) then
      v_ret_start := to_timestamp(floor(extract(epoch from ret_leg.ret_start) / 900) * 900);
    else
      v_ret_start := ret_leg.ret_start;
    end if;
    if not public.is_quarter_hour(ret_leg.ret_end) then
      v_ret_end := to_timestamp(ceil(extract(epoch from ret_leg.ret_end) / 900) * 900);
    else
      v_ret_end := ret_leg.ret_end;
    end if;
    v_gap_override := case when v_ret_start - v_out_end < v_turnaround
      then (extract(epoch from (v_ret_start - v_out_end)) / 60)::smallint end;

    -- Owner 2026-09-24 (docs/TODO.md Q8): both legs end up on one car, so each leg's own load
    -- must fit it (the deferred ride_seat_fit_on_car_change trigger would otherwise fail the
    -- caller's whole transaction at commit). No fitting, free car → keep the separate chauffeur rides.
    select adults, child_seats, boosters into v_out_load from public.requests where id = out_leg.request_id;
    select adults, child_seats, boosters into v_ret_load from public.requests where id = ret_leg.request_id;
    v_target_car := null;
    if out_leg.car_id = ret_leg.car_id then
      v_target_car := out_leg.car_id;
    elsif public.car_fits(out_leg.car_id, v_out_load.adults, v_out_load.child_seats, v_out_load.boosters)
      and public.car_fits(out_leg.car_id, v_ret_load.adults, v_ret_load.child_seats, v_ret_load.boosters)
      and not exists (
        select 1 from public.rides x where x.car_id = out_leg.car_id and x.id not in (out_leg.ride_id, ret_leg.ride_id)
          and x.status <> 'cancelled' and not x.planning_conflict
          and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_ret_start, v_ret_end + v_turnaround, '[)'))
    then
      v_target_car := out_leg.car_id;
    elsif public.car_fits(ret_leg.car_id, v_out_load.adults, v_out_load.child_seats, v_out_load.boosters)
      and public.car_fits(ret_leg.car_id, v_ret_load.adults, v_ret_load.child_seats, v_ret_load.boosters)
      and not exists (
        select 1 from public.rides x where x.car_id = ret_leg.car_id and x.id not in (out_leg.ride_id, ret_leg.ride_id)
          and x.status <> 'cancelled' and not x.planning_conflict
          and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_out_start, v_out_end + v_turnaround, '[)'))
    then
      v_target_car := ret_leg.car_id;
    end if;
    if v_target_car is null then
      continue; -- no car is free for, and fits, both legs; heal each independently for now
    end if;

    update public.rides set car_id = v_target_car, origin_id = out_leg.origin_id, destination_id = out_leg.destination_id,
      starts_at = v_out_start, ends_at = v_out_end, needs_driver = false, driver_id = v_driver_out,
      turnaround_override_minutes = v_gap_override
    where id = out_leg.ride_id;
    update public.ride_requests set role = 'driver', car_mode = 'relay'
    where ride_id = out_leg.ride_id and request_id = out_leg.request_id;

    update public.rides set car_id = v_target_car, origin_id = out_leg.destination_id, destination_id = out_leg.origin_id,
      starts_at = v_ret_start, ends_at = v_ret_end, needs_driver = false, driver_id = v_driver_ret
    where id = ret_leg.ride_id;
    update public.ride_requests set role = 'driver', car_mode = 'relay'
    where ride_id = ret_leg.ride_id and request_id = ret_leg.request_id;

    -- A leg created as a lone chauffeur reservation (needs_driver, REQ §8) marks its
    -- request 'waitlisted'/UNMET_NEEDS_DRIVER; now that it is an ordinary driven relay
    -- leg, the request is assigned like any other driver placement.
    -- Restore the caller's flag instead of forcing 'off' (a caller such as
    -- reserve_live_one_way_slot() still has system status writes to make after this).
    v_prev_flag := coalesce(current_setting('app.system_status_transition', true), 'off');
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'assigned', status_reason = 'RELAY_PAIRED'
    where id in (out_leg.request_id, ret_leg.request_id) and status is distinct from 'assigned';
    perform set_config('app.system_status_transition', v_prev_flag, true);
  end loop;
end $$;


ALTER FUNCTION "public"."pair_one_way_legs"("p_dept" "uuid", "p_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."phone_of"("_profile" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select p.phone from public.profiles p where p.id=_profile and (
    _profile=(select auth.uid()) or public.is_admin()
    or exists(select 1 from public.department_members dm
      where dm.profile_id=_profile and dm.removed_at is null and public.is_sadran_any(dm.department_id))
    or exists(select 1 from public.requests q
      where (q.requester_id=_profile or exists(select 1 from public.request_companions rc
        where rc.request_id=q.id and rc.profile_id=_profile))
      and public.is_sadran(q.department_id,q.week_start))
    or exists(select 1 from public.rides r where r.driver_id=_profile
      and r.status<>'cancelled' and public.is_sadran(r.department_id,r.week_start))
    or exists(select 1 from public.proposal_parties pp join public.proposals proposal on proposal.id=pp.proposal_id
      where pp.profile_id=_profile and public.is_sadran(proposal.department_id,proposal.week_start))
    or public.shares_ride_with(_profile));
$$;


ALTER FUNCTION "public"."phone_of"("_profile" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_request_on_car"("p_request_id" "uuid", "p_car_id" "uuid", "p_manual" boolean, "p_actor" "uuid", "p_named_driver" "uuid", "p_dep" timestamp with time zone, "p_ret" timestamp with time zone, "p_reason" "text" DEFAULT 'PROPOSAL_APPLIED'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  q public.requests%rowtype; v_home uuid;
  v_car uuid; v_dep timestamptz; v_ret timestamptz; v_manual boolean; v_public boolean;
  v_named uuid; v_driver uuid; v_old record; v_old_cars uuid[] := '{}'; v_old_car uuid;
  v_ride uuid; v_first uuid; v_rides uuid[] := '{}'; v_end timestamptz;
  v_travel int; v_dur int; v_dwell int; v_gap smallint; v_buffer int;
  v_week_from timestamptz; v_week_until timestamptz; v_day date;
  v_leg public.ride_leg; v_at timestamptz; v_legs int := 0; v_wanted int := 0;
  v_s timestamptz; v_e timestamptz; v_loc uuid; v_ok boolean; k int; c int; v_rid uuid;
begin
  select * into q from public.requests where id = p_request_id for update;
  if q.id is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  v_car := p_car_id;
  if not exists(select 1 from public.cars where id = v_car and department_id = q.department_id and status = 'active') then
    raise exception 'shift_car_invalid' using errcode = 'P0001';
  end if;
  v_manual := coalesce(p_manual, false);
  v_public := public.is_week_public(q.department_id, q.week_start);
  v_dep := case when q.trip_shape = 'one_way_from' then null else coalesce(p_dep, q.depart_at) end;
  v_ret := case when q.trip_type = 'one_way' or q.trip_shape = 'one_way_to' then null
                else coalesce(p_ret, q.return_at) end;
  if v_dep is null and v_ret is null then raise exception 'shift_car_invalid' using errcode = 'P0001'; end if;
  if v_dep is distinct from q.depart_at or v_ret is distinct from q.return_at then
    update public.requests set depart_at = v_dep, return_at = v_ret where id = q.id;
  end if;
  select * into q from public.requests where id = q.id;
  v_day := (coalesce(v_dep, v_ret) at time zone 'Asia/Jerusalem')::date;
  v_week_from := q.week_start::timestamp at time zone 'Asia/Jerusalem';
  v_week_until := (q.week_start + 7)::timestamp at time zone 'Asia/Jerusalem';
  v_buffer := coalesce(public.required_turnaround_minutes(q.department_id, q.week_start), 30);

  -- Replace the request's previous placement.
  for v_old in select rd.* from public.rides rd join public.ride_requests rr on rr.ride_id = rd.id
    where rr.request_id = q.id and rd.status <> 'cancelled' order by rd.id for update of rd loop
    if exists(select 1 from public.ride_requests where ride_id = v_old.id and request_id <> q.id) then
      if not v_manual then raise exception 'shared_ride_requires_sadran'; end if;
    else
      update public.rides set status = 'cancelled', cancelled_at = now(),
        cancelled_by = coalesce(p_actor, q.requester_id), cancel_reason = 'REPLACED_BY_PROPOSAL' where id = v_old.id;
    end if;
    delete from public.ride_requests where ride_id = v_old.id and request_id = q.id;
    v_old_cars := v_old_cars || v_old.car_id;
  end loop;

  if q.trip_type = 'round_trip' then
    -- REQ §13.95 H3: a round trip is one ride, the requester (or a driving companion) drives, car kept.
    v_driver := public.eligible_leg_driver(q.id);
    if v_driver is null then raise exception 'non_driver_needs_drop_off' using errcode = 'P0001'; end if;
    if v_dep is null or v_ret is null then raise exception 'shift_car_invalid' using errcode = 'P0001'; end if;
    select home_destination_id into v_home from public.departments where id = q.department_id;
    v_loc := coalesce(q.origin_id, v_home);
    v_gap := null;
    if v_manual then v_gap := public.prepare_manual_ride_window(v_car, q.week_start, v_dep, v_ret, null); end if;
    insert into public.rides(department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id, driver_id,
      status, is_pinned, pin_reason, created_by, turnaround_override_minutes)
    values(q.department_id, q.week_start, v_car, v_dep, v_ret, v_loc, v_loc, v_driver,
      case when v_public then 'confirmed'::public.ride_status else 'draft'::public.ride_status end,
      true, p_reason, p_actor, v_gap) returning id into v_ride;
    insert into public.ride_requests(ride_id, request_id, role, leg, car_mode) values(v_ride, q.id, 'driver', 'both', 'keep');
    v_first := v_ride; v_rides := array[v_ride];
    update public.requests set status = 'assigned', status_reason = p_reason where id = q.id;
  elsif q.trip_type = 'one_way' then
    if q.origin_id is null or q.destination_id is null then raise exception 'shift_car_invalid' using errcode = 'P0001'; end if;
    v_driver := public.eligible_leg_driver(q.id);
    if v_driver is null then raise exception 'no_eligible_driver' using errcode = 'P0001'; end if;
    v_travel := greatest(coalesce(public.request_leg_route_minutes(q.id, 'out'), 30), 0);
    v_end := greatest(public._round_up_ride_end(v_dep, v_dep + make_interval(mins => v_travel)), v_dep + interval '15 minutes');
    if public.car_location_at(v_car, v_dep) is distinct from q.origin_id then
      raise exception 'car_not_at_leg_origin' using errcode = 'P0001';
    end if;
    if coalesce(public.car_next_ride_origin(v_car, v_end), q.destination_id) <> q.destination_id then
      raise exception 'car_next_ride_elsewhere' using errcode = 'P0001';
    end if;
    v_gap := null;
    if v_manual then v_gap := public.prepare_manual_ride_window(v_car, q.week_start, v_dep, v_end, null); end if;
    insert into public.rides(department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id, driver_id,
      status, is_pinned, pin_reason, created_by, turnaround_override_minutes)
    values(q.department_id, q.week_start, v_car, v_dep, v_end, q.origin_id, q.destination_id, v_driver,
      case when v_public then 'confirmed'::public.ride_status else 'draft'::public.ride_status end,
      true, p_reason, p_actor, v_gap) returning id into v_ride;
    insert into public.ride_requests(ride_id, request_id, role, leg, car_mode) values(v_ride, q.id, 'driver', 'out', 'relay');
    v_first := v_ride; v_rides := array[v_ride];
    update public.requests set status = 'assigned', status_reason = p_reason where id = q.id;
  else
    -- drop_off: one chauffeur ride per leg.
    v_named := p_named_driver;
    if v_named is not null and not exists(select 1 from public.department_members
      where department_id = q.department_id and profile_id = v_named and removed_at is null) then
      raise exception 'shift_car_invalid' using errcode = 'P0001';
    end if;
    select coalesce((w.settings_overrides ->> 'chauffeur_dwell_minutes')::int, s.chauffeur_dwell_minutes, 10) into v_dwell
    from public.department_settings s join public.weeks w on w.department_id = s.department_id and w.week_start = q.week_start
    where s.department_id = q.department_id;
    v_dwell := coalesce(v_dwell, 10);
    for k in 1..2 loop
      if k = 1 then v_leg := 'out'; v_at := v_dep; else v_leg := 'return'; v_at := v_ret; end if;
      continue when v_at is null;
      v_wanted := v_wanted + 1;
      v_travel := greatest(coalesce(public.request_leg_route_minutes(q.id, v_leg), 30), 0);
      v_dur := greatest(15, ceil((2 * v_travel + greatest(v_dwell, 0)) / 15.0)::int * 15);
      v_ok := false;
      for c in 1..2 loop
        continue when c = 2 and v_leg <> 'out';
        if c = 1 then
          v_loc := q.origin_id;
          if v_leg = 'out' then v_s := v_at; v_e := v_at + make_interval(mins => v_dur);
          else v_e := v_at; v_s := v_at - make_interval(mins => v_dur); end if;
        else
          v_loc := q.destination_id;
          v_e := v_at + make_interval(mins => ceil(v_travel / 15.0)::int * 15); v_s := v_e - make_interval(mins => v_dur);
        end if;
        continue when v_loc is null or v_s < v_week_from or v_e > v_week_until
          or (v_s at time zone 'Asia/Jerusalem')::date <> v_day
          or ((v_e - interval '1 minute') at time zone 'Asia/Jerusalem')::date <> v_day
          or public.car_location_at(v_car, v_s) is distinct from v_loc
          or exists(select 1 from public.rides r where r.car_id = v_car and r.status <> 'cancelled'
            and tstzrange(r.starts_at, case when v_manual then r.ends_at else r.blocked_until end, '[)')
              && tstzrange(v_s, case when v_manual then v_e else v_e + make_interval(mins => v_buffer) end, '[)'))
          or exists(select 1 from public.car_maintenance_blocks b where b.car_id = v_car
            and tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(v_s, v_e, '[)'));
        v_ok := true; exit;
      end loop;
      continue when not v_ok;
      v_gap := null;
      if v_manual then v_gap := public.prepare_manual_ride_window(v_car, q.week_start, v_s, v_e, null); end if;
      insert into public.rides(department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id, driver_id, needs_driver,
        status, is_pinned, pin_reason, created_by, turnaround_override_minutes)
      values(q.department_id, q.week_start, v_car, v_s, v_e, v_loc, v_loc, v_named, v_named is null,
        case when v_public then 'confirmed'::public.ride_status else 'draft'::public.ride_status end,
        true, case when v_named is null then 'MISSING_DRIVER' else p_reason end, p_actor, v_gap)
      returning id into v_ride;
      insert into public.ride_requests(ride_id, request_id, role, leg, car_mode) values(v_ride, q.id, 'passenger', v_leg, 'chauffeur');
      v_legs := v_legs + 1; v_rides := v_rides || v_ride;
      v_first := coalesce(v_first, v_ride);
    end loop;
    if v_legs = 0 then raise exception 'car_not_at_leg_place' using errcode = 'P0001'; end if;
    if v_named is null then
      update public.requests set status = 'waitlisted', status_reason = 'UNMET_NEEDS_DRIVER' where id = q.id;
    else
      update public.requests set status = 'assigned',
        status_reason = case when v_legs < v_wanted then p_reason || '_PARTIAL' else p_reason end where id = q.id;
    end if;
  end if;

  foreach v_rid in array v_rides loop
    perform public.assert_ride_request_day(v_rid);
    perform public.assert_ride_seats_fit(v_rid);
    perform public.assert_ride_driver(v_rid);
  end loop;
  perform public.assert_car_chain(v_car, q.week_start);
  foreach v_old_car in array v_old_cars loop
    if v_old_car <> v_car then perform public.assert_car_chain(v_old_car, q.week_start); end if;
  end loop;
  return v_first;
end;
$$;


ALTER FUNCTION "public"."place_request_on_car"("p_request_id" "uuid", "p_car_id" "uuid", "p_manual" boolean, "p_actor" "uuid", "p_named_driver" "uuid", "p_dep" timestamp with time zone, "p_ret" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_series"("p_series_id" "uuid", "p_car_id" "uuid", "p_pin" boolean DEFAULT false, "p_pin_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid; v_origin uuid; v_dest uuid; v_first timestamptz; v_last timestamptz;
  v_first_week date; v_turnaround interval; v_legs int; v_expected int; v_actor uuid := (select auth.uid());
  v_ride_ids uuid[] := '{}'; v_weeks date[] := '{}';
  leg record; v_ride_id uuid; v_origin_leg uuid; v_destination uuid; v_pin boolean; v_reason text;
  w date;
begin
  begin
    select q.department_id, min(q.depart_at), max(q.return_at), count(*)::int, max(q.series_count)::int
      into v_dept, v_first, v_last, v_legs, v_expected
    from public.requests q
    where q.series_id = p_series_id and q.status not in ('withdrawn','cancelled','denied','external')
    group by q.department_id;
    if v_dept is null or v_legs is distinct from v_expected then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'series_incomplete';
    end if;

    select min(q.week_start) into v_first_week from public.requests q where q.series_id = p_series_id;
    select q.origin_id into v_origin from public.requests q
    where q.series_id = p_series_id order by q.series_index limit 1;
    if v_origin is null then raise exception 'no_home_location' using errcode = 'P0412'; end if;
    select coalesce(q.destination_id, v_origin) into v_dest
    from public.requests q where q.series_id = p_series_id order by q.series_index limit 1;

    if not exists (select 1 from public.cars c
      where c.id = p_car_id and c.department_id = v_dept and c.status = 'active' and c.type = 'shared') then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_not_shared_active';
    end if;
    if exists (select 1 from public.requests q where q.series_id = p_series_id
      and not public.car_fits(p_car_id, q.adults, q.child_seats, q.boosters)) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'seat_config_violation';
    end if;
    -- Every leg on the SAME car: a leg already parked on a different car blocks the move.
    if exists (select 1 from public.rides r
      where r.series_id = p_series_id and r.status <> 'cancelled' and r.car_id <> p_car_id) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'series_split_across_cars';
    end if;

    select coalesce(make_interval(mins => s.turnaround_minutes), interval '30 minutes') into v_turnaround
    from public.department_settings s where s.department_id = v_dept;
    v_turnaround := coalesce(v_turnaround, interval '30 minutes');

    -- Nobody else uses the car anywhere inside the span.
    if exists (select 1 from public.rides r
      where r.car_id = p_car_id and r.status <> 'cancelled' and not r.planning_conflict
        and r.series_id is distinct from p_series_id
        and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_first, v_last + v_turnaround, '[)')) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_busy';
    end if;
    if exists (select 1 from public.car_maintenance_blocks b where b.car_id = p_car_id
      and tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(v_first, v_last + v_turnaround, '[)')) then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'ride_conflicts_with_maintenance';
    end if;
    -- The car must be at the series' own origin when the series starts (own legs ignored so
    -- re-runs are idempotent).
    if coalesce((select r.destination_id from public.rides r
      where r.car_id = p_car_id and r.status <> 'cancelled' and not r.planning_conflict
        and r.series_id is distinct from p_series_id and r.starts_at < v_first
        and not public.ride_is_reservation(r.id)
      order by r.starts_at desc limit 1), v_origin) <> v_origin then
      raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = 'car_not_home';
    end if;

    perform set_config('app.audit_reason', 'place_series', true);
    for leg in select q.* from public.requests q where q.series_id = p_series_id order by q.series_index loop
      v_weeks := v_weeks || leg.week_start;
      if exists (select 1 from public.ride_requests rr join public.rides r on r.id = rr.ride_id
                 where rr.request_id = leg.id and r.status <> 'cancelled') then
        continue;                                   -- already placed on p_car_id (checked above)
      end if;
      v_origin_leg  := case when leg.series_index = 1 then v_origin else v_dest end;
      v_destination := case when leg.series_index = leg.series_count then v_origin else v_dest end;
      v_pin    := p_pin or leg.week_start <> v_first_week;
      v_reason := case when leg.week_start <> v_first_week then 'SERIES_CARRY_OVER'
                       else coalesce(p_pin_reason, 'SERIES_PLACED') end;
      insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
        driver_id, status, is_pinned, pin_reason, created_by, series_id)
      values (v_dept, leg.week_start, p_car_id, leg.depart_at, leg.return_at, v_origin_leg, v_destination,
        leg.requester_id,
        case when public.is_week_public(v_dept, leg.week_start) then 'confirmed'::public.ride_status
             else 'draft'::public.ride_status end,
        v_pin, case when v_pin then v_reason else null end, coalesce(v_actor, leg.requester_id), p_series_id)
      returning id into v_ride_id;
      insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
      values (v_ride_id, leg.id, 'driver', 'both', 'keep');
      perform public.assert_ride_seats_fit(v_ride_id);
      v_ride_ids := array_append(v_ride_ids, v_ride_id);
    end loop;

    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'assigned', status_reason = 'SERIES_PLACED' where series_id = p_series_id;
    perform set_config('app.system_status_transition', 'off', true);

    for w in select distinct x from unnest(v_weeks) x order by 1 loop
      perform public.assert_car_chain(p_car_id, w);
    end loop;
  exception when others then
    if sqlstate = 'MDR03' then raise; end if;
    raise exception 'series_car_unavailable' using errcode = 'MDR03', detail = sqlerrm;
  end;

  return jsonb_build_object('series_id', p_series_id, 'car_id', p_car_id,
    'ride_ids', coalesce(to_jsonb(v_ride_ids), '[]'::jsonb),
    'weeks', coalesce(to_jsonb((select array_agg(distinct x order by x) from unnest(v_weeks) x)), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."place_series"("p_series_id" "uuid", "p_car_id" "uuid", "p_pin" boolean, "p_pin_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_travel"("p_from" "uuid", "p_to" "uuid") RETURNS TABLE("distance_km" numeric, "travel_minutes" integer, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_from public.destinations;
  v_to public.destinations;
  v_route public.place_distances;
  v_home_from boolean;
  v_home_to boolean;
  v_km numeric;
begin
  if p_from = p_to then
    return query select 0::numeric, 0, 'same'::text;
    return;
  end if;

  select * into v_from from public.destinations where id = p_from;
  select * into v_to from public.destinations where id = p_to;
  if v_from.id is null or v_to.id is null then
    return query select null::numeric, null::int, null::text;
    return;
  end if;

  select * into v_route from public.place_distances pd
    where pd.department_id = v_from.department_id
      and ((pd.from_id = p_from and pd.to_id = p_to) or (pd.from_id = p_to and pd.to_id = p_from))
    limit 1;
  if v_route.id is not null then
    return query select v_route.distance_km, v_route.travel_minutes, 'route'::text;
    return;
  end if;

  v_home_from := exists(select 1 from public.departments d where d.id = v_from.department_id and d.home_destination_id = p_from);
  v_home_to := exists(select 1 from public.departments d where d.id = v_to.department_id and d.home_destination_id = p_to);
  if v_home_from and not v_home_to then
    return query select v_to.distance_km, v_to.travel_minutes, 'preset'::text;
    return;
  elsif v_home_to and not v_home_from then
    return query select v_from.distance_km, v_from.travel_minutes, 'preset'::text;
    return;
  end if;

  if v_from.lat is not null and v_from.lng is not null and v_to.lat is not null and v_to.lng is not null then
    v_km := (6371 * asin(sqrt(
        power(sin(radians(v_to.lat - v_from.lat) / 2), 2)
        + cos(radians(v_from.lat)) * cos(radians(v_to.lat)) * power(sin(radians(v_to.lng - v_from.lng) / 2), 2)
      ))) * 1.3;
    -- 60 km/h: minutes = km / 60 * 60, i.e. numerically equal to the (road-factored) km.
    return query select round(v_km, 1), round(v_km)::int, 'estimate'::text;
    return;
  end if;

  return query select null::numeric, null::int, null::text;
end;
$$;


ALTER FUNCTION "public"."place_travel"("p_from" "uuid", "p_to" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_travel_for_week"("p_department_id" "uuid", "p_week_start" "date") RETURNS TABLE("origin_id" "uuid", "destination_id" "uuid", "distance_km" numeric, "travel_minutes" integer, "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.member_of(p_department_id) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  return query
    with places as (
      select q.origin_id as place_id from public.requests q
        where q.department_id = p_department_id and q.week_start = p_week_start and q.origin_id is not null
      union
      select q.destination_id from public.requests q
        where q.department_id = p_department_id and q.week_start = p_week_start and q.destination_id is not null
      union
      select s.place_id from public.request_stops s join public.requests q on q.id = s.request_id
        where q.department_id = p_department_id and q.week_start = p_week_start and s.place_id is not null
      union
      select d.home_destination_id from public.departments d
        where d.id = p_department_id and d.home_destination_id is not null
    )
    select a.place_id, b.place_id, pt.distance_km, pt.travel_minutes, pt.source
    from places a
    join places b on a.place_id < b.place_id
    cross join lateral public.place_travel(a.place_id, b.place_id) pt;
end;
$$;


ALTER FUNCTION "public"."place_travel_for_week"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


