CREATE OR REPLACE FUNCTION "public"."proposal_parties_roll_up"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_total int; v_accepted int; v_declined int; v_status public.proposal_status;
  v_prop record;
  v_new_status public.proposal_status;
begin
  select status into v_status from public.proposals where id = new.proposal_id;
  if v_status <> 'sent' then
    return new;
  end if;
  select count(*), count(*) filter (where response = 'accepted'), count(*) filter (where response = 'declined')
    into v_total, v_accepted, v_declined
  from public.proposal_parties where proposal_id = new.proposal_id;

  if v_declined > 0 then
    v_new_status := 'declined';
  elsif v_accepted = v_total then
    v_new_status := 'accepted';
  end if;

  if v_new_status is not null then
    update public.proposals set status = v_new_status where id = new.proposal_id
    returning * into v_prop;

    -- `variant` selects the Hebrew copy in notification_templates (accepted/declined);
    -- `proposal_id` in `_data` lets notification_default_url() (20260909090000) link back
    -- to the Sadran's proposals list without a token.
    if v_prop.created_by is not null then
      perform public.enqueue_notification(v_prop.created_by, 'proposal_answered', v_prop.department_id, v_prop.week_start,
        '{}'::jsonb, jsonb_build_object('variant', v_new_status::text, 'proposal_id', v_prop.id),
        format('proposal_answered:%s:%s', v_prop.id, v_prop.created_by));
    else
      perform public.enqueue_notification(s.profile_id, 'proposal_answered', v_prop.department_id, v_prop.week_start,
        '{}'::jsonb, jsonb_build_object('variant', v_new_status::text, 'proposal_id', v_prop.id),
        format('proposal_answered:%s:%s', v_prop.id, s.profile_id))
      from public.sadranim_of(v_prop.department_id, v_prop.week_start) as s(profile_id);
    end if;

    if v_new_status = 'accepted' then
      perform public.maybe_apply_accepted_proposal(v_prop.id);
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."proposal_parties_roll_up"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."proposals_status_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_prev_flag text := coalesce(current_setting('app.system_status_transition', true), 'off');
begin
  if tg_op = 'INSERT' or new.status = old.status then
    return new;
  end if;

  if old.status = 'draft' and new.status not in ('sent','withdrawn') then
    raise exception 'invalid_proposal_transition' using errcode = 'P0001';
  elsif old.status = 'sent' and new.status not in ('accepted','declined','expired','withdrawn') then
    raise exception 'invalid_proposal_transition' using errcode = 'P0001';
  elsif old.status in ('accepted','declined','expired','withdrawn','applied') and new.status <> 'applied'
and not (old.status = 'accepted' and new.status = 'withdrawn') then
    raise exception 'invalid_proposal_transition' using errcode = 'P0001';
  elsif old.status = 'applied' then
    raise exception 'invalid_proposal_transition' using errcode = 'P0001';
  elsif new.status = 'applied' and old.status <> 'accepted' then
    raise exception 'invalid_proposal_transition' using errcode = 'P0001';
  end if;

  if new.status = 'sent' then
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'proposed' where id = new.request_id;
    perform set_config('app.system_status_transition', v_prev_flag, true);
  elsif new.status in ('declined','expired','withdrawn') and old.status <> 'draft' then
    -- A draft never moved its request out of its own status (only `send_proposal` does), so
    -- discarding one must not "restore" a possibly stale previous_status.
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = new.previous_status where id = new.request_id;
    perform set_config('app.system_status_transition', v_prev_flag, true);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."proposals_status_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publication_conflicting_ride_ids"("p_department_id" "uuid", "p_week_start" "date", "p_days" "date"[]) RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r record; here uuid; bad boolean; res boolean;
begin
  for r in
    select * from public.rides where department_id=p_department_id and week_start=p_week_start and status<>'cancelled'
      and (starts_at at time zone 'Asia/Jerusalem')::date=any(p_days)
  loop
    res:=public.ride_is_reservation(r.id);
    bad:=r.starts_at>=r.ends_at or (r.starts_at at time zone 'Asia/Jerusalem')::date<>(r.ends_at at time zone 'Asia/Jerusalem')::date
      or (r.ends_at at time zone 'Asia/Jerusalem')::time>'23:59'::time
      or (r.starts_at at time zone 'Asia/Jerusalem')::date not between p_week_start and p_week_start+6;
    bad:=bad or exists(select 1 from public.rides other where other.id<>r.id and other.status<>'cancelled'
      and (other.car_id=r.car_id or (r.driver_id is not null and other.driver_id=r.driver_id))
      and tstzrange(other.starts_at,other.ends_at,'[)') && tstzrange(r.starts_at,r.ends_at,'[)'));
    bad:=bad or exists(select 1 from public.car_maintenance_blocks b where b.car_id=r.car_id
      and tstzrange(b.starts_at,b.ends_at,'[)') && tstzrange(r.starts_at,r.ends_at,'[)'));
    bad:=bad or not exists(select 1 from public.cars c where c.id=r.car_id and c.department_id=p_department_id and c.status='active');
    if not res then
      here:=coalesce((select prev.destination_id from public.rides prev
        where prev.car_id=r.car_id and prev.status<>'cancelled' and (prev.starts_at,prev.id)<(r.starts_at,r.id)
          and not public.ride_is_reservation(prev.id)
        order by prev.starts_at desc,prev.id desc limit 1),public.car_base_location(r.car_id));
      bad:=bad or r.origin_id is distinct from here;
    end if;
    bad:=bad or (not res and exists(select 1 from public.rides following where following.id=(select nxt.id from public.rides nxt
      where nxt.car_id=r.car_id and nxt.week_start=p_week_start and nxt.status<>'cancelled' and (nxt.starts_at,nxt.id)>(r.starts_at,r.id)
        and not public.ride_is_reservation(nxt.id)
      order by nxt.starts_at,nxt.id limit 1) and following.origin_id is distinct from r.destination_id));
    begin
      perform public.assert_ride_request_day(r.id);
      perform public.assert_ride_driver(r.id);
      perform public.assert_ride_seats_fit(r.id);
    exception when raise_exception or check_violation then bad:=true;
    end;
    if bad then return next r.id;end if;
  end loop;
  -- 1020 adds private provisional shadows. JSON access keeps this migration
  -- applicable first, while making pending provisional edits a hard blocker.
  return query select distinct c.ride_id from public.ride_change_requests c
    where c.department_id=p_department_id and c.week_start=p_week_start and c.status='pending'
      and coalesce((to_jsonb(c)->>'is_planning')::boolean,false)
      and (c.starts_at at time zone 'Asia/Jerusalem')::date=any(p_days);
end;
$$;


ALTER FUNCTION "public"."publication_conflicting_ride_ids"("p_department_id" "uuid", "p_week_start" "date", "p_days" "date"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publication_readiness"("p_department_id" "uuid", "p_week_start" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare result jsonb:='[]'; d date; requests_n int; unresolved_n int; incomplete_n int; pending_n int; draft_n int; missing_n int; conflicts_n int;
begin
  if not public.can_manage_week(p_department_id,p_week_start) then raise exception 'not_authorized';end if;
  if exists(select 1 from public.weeks w where w.department_id=p_department_id and w.week_start=p_week_start and w.phase='upcoming') then raise exception 'week_not_open'; end if;
  for d in select p_week_start+i from generate_series(0,6) i loop
    select count(*),
      count(*) filter(where q.status in ('submitted','waitlisted','proposed')),
      count(*) filter(where q.status in ('assigned','merged') and not (
        (q.trip_shape='one_way_from' or exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id
          where rr.request_id=q.id and rr.covers_out and r.status<>'cancelled' and not r.needs_driver))
        and (q.trip_shape='one_way_to' or exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id
          where rr.request_id=q.id and rr.covers_return and r.status<>'cancelled' and not r.needs_driver))
      ))
    into requests_n,unresolved_n,incomplete_n from public.requests q where q.department_id=p_department_id and q.week_start=p_week_start
      and q.status not in ('draft','withdrawn','cancelled') and (coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date=d;
    -- 20261005110300: unsent drafts are counted separately (draftProposals) and no longer in
    -- pendingProposals, so a day with a draft is not blocked twice with two messages.
    select count(*) filter(where p.status in ('sent','accepted')), count(*) filter(where p.status='draft') into pending_n,draft_n
      from public.proposals p join public.requests q on q.id=p.request_id
      where p.department_id=p_department_id and p.week_start=p_week_start and p.status in ('draft','sent','accepted')
        and ((coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date=d
          or exists(select 1 from public.rides r where r.id=p.ride_id and (r.starts_at at time zone 'Asia/Jerusalem')::date=d));
    pending_n:=pending_n+(select count(*) from public.ride_change_requests c where c.department_id=p_department_id and c.week_start=p_week_start
      and c.status='pending' and (c.starts_at at time zone 'Asia/Jerusalem')::date=d);
    select count(*) into missing_n from public.rides r where r.department_id=p_department_id and r.week_start=p_week_start
      and r.status<>'cancelled' and r.needs_driver and (r.starts_at at time zone 'Asia/Jerusalem')::date=d;
    select count(distinct id) into conflicts_n from public.publication_conflicting_ride_ids(p_department_id,p_week_start,array[d]) id;
    result:=result||jsonb_build_array(jsonb_build_object('day',d,'published',public.is_day_public(p_department_id,p_week_start,d),
      'requestCount',requests_n,'unresolvedRequests',unresolved_n+incomplete_n,'incompleteAssignments',incomplete_n,
      'pendingProposals',pending_n,'draftProposals',draft_n,'missingDriverRides',missing_n,'conflictRides',conflicts_n,
      'ready',incomplete_n=0 and pending_n=0 and draft_n=0 and missing_n=0 and conflicts_n=0));
  end loop;
  return result;
end;
$$;


ALTER FUNCTION "public"."publication_readiness"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_scores_fingerprint"("p_department_id" "uuid", "p_week_start" "date") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.can_manage_week(p_department_id,p_week_start) then raise exception 'not_authorized'; end if;
  return md5(jsonb_build_object(
    'proposals',(select jsonb_agg(to_jsonb(p) order by id) from public.proposals p where department_id=p_department_id and week_start=p_week_start),
    'proposal_parties',(select jsonb_agg(to_jsonb(pp) order by pp.proposal_id,pp.profile_id) from public.proposal_parties pp join public.proposals p on p.id=pp.proposal_id where p.department_id=p_department_id and p.week_start=p_week_start),
    'ride_changes',(select jsonb_agg(to_jsonb(c) order by id) from public.ride_change_requests c where department_id=p_department_id and week_start=p_week_start),
    'ride_change_parties',(select jsonb_agg(to_jsonb(cp) order by cp.id) from public.ride_change_parties cp join public.ride_change_requests c on c.id=cp.change_id where c.department_id=p_department_id and c.week_start=p_week_start),
    'week',(select to_jsonb(w) from public.weeks w where department_id=p_department_id and week_start=p_week_start),
    'requests',(select jsonb_agg(to_jsonb(q) order by id) from public.requests q where department_id=p_department_id),
    'rides',(select jsonb_agg(to_jsonb(r) order by id) from public.rides r where department_id=p_department_id),
    'served',(select jsonb_agg(to_jsonb(rr) order by rr.ride_id,rr.request_id,rr.leg) from public.ride_requests rr join public.rides r on r.id=rr.ride_id where r.department_id=p_department_id),
    'policies',(select jsonb_agg(to_jsonb(p) order by id) from public.policies p where department_id=p_department_id),
    'settings',(select to_jsonb(s) from public.department_settings s where department_id=p_department_id),
    'cars',(select jsonb_agg(to_jsonb(c) order by id) from public.cars c where department_id=p_department_id),
    'seats',(select jsonb_agg(to_jsonb(s) order by s.id) from public.car_seat_configs s join public.cars c on c.id=s.car_id where c.department_id=p_department_id),
    'blocks',(select jsonb_agg(to_jsonb(b) order by id) from public.car_maintenance_blocks b where department_id=p_department_id),
    'destinations',(select jsonb_agg(to_jsonb(d) order by id) from public.destinations d where d.department_id=p_department_id)
  )::text);
end $$;


ALTER FUNCTION "public"."publish_scores_fingerprint"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_siddur"("p_department_id" "uuid", "p_week_start" "date", "p_profile_scores" "jsonb" DEFAULT '[]'::"jsonb", "p_expected_fingerprint" "text" DEFAULT NULL::"text", "p_policy_scores" "jsonb" DEFAULT '[]'::"jsonb", "p_days" "date"[] DEFAULT NULL::"date"[], "p_allow_unanswered" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_snapshot jsonb;
  v_days date[]; v_prior_days date[]; v_public_days date[]; readiness jsonb;
  v_day date;
  v_version_id uuid := gen_random_uuid();
  v_prev record;
  v_phase public.week_phase;
  v_req record;
  v_notified int := 0;
  v_prev_status text;
  v_event public.notification_event;
  policy_score jsonb;
  n int; served_n int; total numeric; served_total numeric;
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  perform 1 from public.weeks where department_id=p_department_id and week_start=p_week_start for update;
  if not found then raise exception 'week_not_open'; end if;
  if exists(select 1 from public.weeks where department_id=p_department_id and week_start=p_week_start and phase='archived') then raise exception 'week_archived'; end if;
  if exists(select 1 from public.weeks where department_id=p_department_id and week_start=p_week_start and phase='upcoming') then raise exception 'week_not_open'; end if;
  -- Lock publication inputs while the snapshot and scores are checked and saved.
  lock table public.requests,public.rides,public.ride_requests,public.policies,public.department_settings,public.cars,public.car_seat_configs,public.car_maintenance_blocks,public.destinations,public.proposals,public.proposal_parties,public.ride_change_requests,public.ride_change_parties in share mode;
  if p_expected_fingerprint is not null and p_expected_fingerprint<>public.publish_scores_fingerprint(p_department_id,p_week_start) then
    raise exception 'stale_input' using errcode='P0409';
  end if;
  select array_agg(distinct d order by d) into v_days from unnest(coalesce(p_days,array(select p_week_start+i from generate_series(0,6) i))) d;
  if coalesce(cardinality(v_days),0)=0 or exists(select 1 from unnest(v_days) d where d is null or d<p_week_start or d>p_week_start+6) then
    raise exception 'invalid_publication_days';
  end if;
  select published_days into v_prior_days from public.weeks where department_id=p_department_id and week_start=p_week_start;
  select array_agg(distinct d order by d) into v_public_days from unnest(v_prior_days||v_days) d;
  if exists(select 1 from public.publication_conflicting_ride_ids(p_department_id,p_week_start,v_days)) then raise exception 'publication_conflicts';end if;
  readiness:=public.publication_readiness(p_department_id,p_week_start);
  -- 20260910091800: `unresolvedRequests` is informational now. A still-unresolved
  -- round-trip request no longer blocks publication — form_waitlist_groups() below either
  -- auto-approves it onto a free car or puts it into a contested group (REQ §7.3,
  -- consistency decision 25). What still blocks is a *defective* board: a request that IS
  -- assigned/merged but whose legs are not fully covered (`incompleteAssignments`), a
  -- pending proposal/ride change, or a ride with no driver.
  -- 20261005110300 (REQ §13.94): unsent draft proposals on a selected day always block, and
  -- `p_allow_unanswered` does not bypass it — a draft is the Sadran's own unfinished work.
  if exists(select 1 from jsonb_array_elements(readiness) item
    where (item->>'day')::date=any(v_days) and (item->>'draftProposals')::int>0)
  then raise exception 'publication_drafts';end if;
  if not coalesce(p_allow_unanswered,false) and exists(select 1 from jsonb_array_elements(readiness) item
    where (item->>'day')::date=any(v_days) and ((item->>'incompleteAssignments')::int>0 or (item->>'pendingProposals')::int>0 or (item->>'missingDriverRides')::int>0))
  then raise exception 'publication_unanswered';end if;
  if jsonb_typeof(p_profile_scores) is distinct from 'array' or jsonb_typeof(p_policy_scores) is distinct from 'array' then
    raise exception 'invalid_publication_scores';
  end if;
  if p_expected_fingerprint is null then
    raise exception 'stale_input' using errcode='P0409';
  end if;
  -- A missing or unavailable score calculation must never prevent publication — scores are
  -- a reporting snapshot and can be recomputed later. But score data that IS supplied must
  -- still be complete (one entry per scoreable request, no orphan entries) and internally
  -- consistent (per-policy sums match); wrong/partial data would otherwise corrupt the
  -- fairness history permanently.
  if jsonb_array_length(p_profile_scores) > 0 then
    if exists(select 1 from jsonb_array_elements(p_profile_scores) score where not exists (
        select 1 from public.requests q where q.requester_id=(score->>'profile_id')::uuid and q.department_id=p_department_id and q.week_start=p_week_start
      )) or exists (
        select 1 from public.requests q where q.department_id=p_department_id and q.week_start=p_week_start and q.status not in ('draft','withdrawn','cancelled')
          and (select count(*) from jsonb_array_elements(p_profile_scores) score cross join lateral jsonb_array_elements(score->'requests') item
               where (score->>'profile_id')::uuid=q.requester_id and (item->>'request_id')::uuid=q.id and jsonb_typeof(item->'score')='number')<>1
      ) or exists (
        select 1 from jsonb_array_elements(p_profile_scores) score cross join lateral jsonb_array_elements(score->'requests') item
        where not exists(select 1 from public.requests q where q.id=(item->>'request_id')::uuid and q.requester_id=(score->>'profile_id')::uuid
          and q.department_id=p_department_id and q.week_start=p_week_start and q.status not in ('draft','withdrawn','cancelled'))
      ) then raise exception 'invalid_publication_scores'; end if;
    perform public.assert_publication_scores(p_department_id,p_week_start,p_profile_scores);
  end if;
  if jsonb_array_length(p_policy_scores) > 0 then
    if (select count(distinct x->>'policy_id') from jsonb_array_elements(p_policy_scores) x)<>jsonb_array_length(p_policy_scores) then raise exception 'invalid_publication_scores'; end if;
    if exists(select 1 from public.policies p where (department_id=p_department_id or department_id is null) and current_version_id is not null
      and not exists(select 1 from jsonb_array_elements(p_policy_scores) x where (x->>'policy_id')::uuid=p.id and (x->>'policy_version_id')::uuid=p.current_version_id)
    ) then raise exception 'invalid_publication_scores'; end if;
    for policy_score in select * from jsonb_array_elements(p_policy_scores) loop
      if not exists(select 1 from public.policies p where p.id=(policy_score->>'policy_id')::uuid and p.current_version_id=(policy_score->>'policy_version_id')::uuid
        and (p.department_id=p_department_id or p.department_id is null)) then raise exception 'invalid_publication_scores'; end if;
      perform public.assert_publication_scores(p_department_id,p_week_start,policy_score->'profiles');
      select coalesce(sum((x->>'request_count')::int),0),coalesce(sum((x->>'served_count')::int),0),
        coalesce(sum((x->>'priority_total')::numeric),0),coalesce(sum((x->>'served_priority_total')::numeric),0)
        into n,served_n,total,served_total from jsonb_array_elements(policy_score->'profiles') x;
      if (policy_score->>'request_count')::int is distinct from n or (policy_score->>'served_count')::int is distinct from served_n
        or abs(coalesce((policy_score->>'priority_total')::numeric,'Infinity'::numeric)-total)>0.000001
        or abs(coalesce((policy_score->>'served_priority_total')::numeric,'Infinity'::numeric)-served_total)>0.000001
      then raise exception 'invalid_publication_scores'; end if;
    end loop;
  end if;
  -- 20260910091800 (contested waiting-list groups, REQ §7.3): before the snapshot is taken
  -- and before anybody is notified, settle each published day's leftovers — every trivially
  -- satisfiable round-trip request is auto-approved onto a free shared car, and each set of
  -- mutually overlapping requests that cannot all be served becomes one waitlist_groups row
  -- whose members are all told at once. Deliberately placed after the score validation
  -- above (which is checked against the pre-publish board) and before the snapshot below
  -- (so `rides`/`requests` in the siddur version, and the `published` notifications, carry
  -- the final outcome). Idempotent, so re-publishing a day is safe.
  foreach v_day in array v_days loop
    perform public.form_waitlist_groups(p_department_id, p_week_start, v_day);
  end loop;

  select * into v_prev from public.siddur_versions
  where department_id = p_department_id and week_start = p_week_start order by version_no desc limit 1;

  select jsonb_build_object(
    'selected_days',to_jsonb(v_days),
    'published_days',to_jsonb(v_public_days),
    'unanswered_acknowledged',coalesce(p_allow_unanswered,false),
    'scores_scope','whole_board',
    'profile_scores',p_profile_scores,
    'policy_scores',p_policy_scores,
    'policy_version_id',(select current_version_id from public.policies where is_active and (department_id=p_department_id or department_id is null) order by department_id nulls last limit 1),
    'scores_fingerprint',p_expected_fingerprint,
    'rides', (select coalesce(jsonb_agg(to_jsonb(r)), '[]') from public.rides r
              where r.department_id = p_department_id and r.week_start = p_week_start and r.status <> 'cancelled'),
    'requests', (select coalesce(jsonb_agg(jsonb_build_object(
                    'id', q.id, 'requester_id', q.requester_id, 'status', q.status, 'status_reason', q.status_reason)), '[]')
                 from public.requests q where q.department_id = p_department_id and q.week_start = p_week_start),
    'cars', (select coalesce(jsonb_agg(to_jsonb(c)), '[]') from public.cars c where c.department_id = p_department_id),
    'blocks', (select coalesce(jsonb_agg(to_jsonb(b)), '[]') from public.car_maintenance_blocks b where b.department_id = p_department_id)
  ) into v_snapshot;

  perform set_config('app.audit_reason', 'publish_siddur', true);

  -- Compute notified_count up front (§ above) — enqueue_notification writes are safe to
  -- run before the siddur_versions row exists since this whole RPC is one transaction:
  -- either everything commits together or everything rolls back together.
  -- 20260910096000 (owner decision, REQ §9): one notification per recipient per publish
  -- call, not one per request. Group every non-cancelled request in scope by requester,
  -- split into a `published` set (day newly public) and an `outcome_changed` set (status
  -- changed since the previous version, on an already-public day), and enqueue at most one
  -- notification of each kind per recipient, listing every affected day/request. The
  -- explicit `days`/`outcomeLine`/`diffLine` vars below win over the single-request
  -- defaults notification_context() would otherwise compute from `data.request_id`
  -- (enqueue_notification does `notification_context(...) || _vars`, right side wins).
  for v_req in
    with scoped as (
      select q.id, q.requester_id, q.status,
        (coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date as request_day,
        (coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date = any(v_prior_days) as day_was_public,
        (select elem ->> 'status' from jsonb_array_elements(coalesce(v_prev.snapshot -> 'requests','[]'::jsonb)) elem
          where (elem ->> 'id')::uuid = q.id) as prev_status,
        coalesce(rd.starts_at,q.depart_at,q.return_at) as line_dt,
        coalesce(rd.starts_at,q.depart_at) as line_depart,
        coalesce(rd.ends_at,q.return_at) as line_return,
        coalesce(c.name,dest.name,q.destination_text,'') as line_place
      from public.requests q
      left join lateral (
        select rr.ride_id from public.ride_requests rr join public.rides x on x.id = rr.ride_id
        where rr.request_id = q.id and x.status <> 'cancelled' limit 1
      ) rl on true
      left join public.rides rd on rd.id = rl.ride_id
      left join public.cars c on c.id = rd.car_id
      left join public.destinations dest on dest.id = q.destination_id
      where q.department_id = p_department_id and q.week_start = p_week_start and q.status not in ('draft','withdrawn','cancelled')
        and (coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date = any(v_days)
    ), classified as (
      select s.*,
        case when v_prev is null or not day_was_public then 'published'
          when prev_status is distinct from status::text then 'outcome_changed'
          else null end as event_kind,
        concat_ws(' · ',
          public.day_date_label(line_dt) || ' ' ||
            to_char(line_depart at time zone 'Asia/Jerusalem','HH24:MI') || '–' ||
            to_char(line_return at time zone 'Asia/Jerusalem','HH24:MI'),
          nullif(line_place,'')
        ) as request_line
      from scoped s
    ), days_agg as (
      select requester_id, event_kind, string_agg(public.weekday_short_label(request_day), ', ' order by request_day) as days_list
      from (select distinct requester_id, event_kind, request_day from classified where event_kind is not null) d
      group by requester_id, event_kind
    ), lines_agg as (
      select requester_id, event_kind,
        string_agg(request_line, chr(10) order by request_day, id) as lines,
        (array_agg(id order by request_day, id))[1] as first_id
      from classified where event_kind is not null
      group by requester_id, event_kind
    )
    select l.requester_id, l.event_kind, d.days_list, l.lines, l.first_id
    from lines_agg l join days_agg d using (requester_id, event_kind)
  loop
    v_event := v_req.event_kind::public.notification_event;
    perform public.enqueue_notification(v_req.requester_id, v_event, p_department_id, p_week_start,
      case when v_event = 'published' then jsonb_build_object('days', v_req.days_list, 'outcomeLine', v_req.lines)
        else jsonb_build_object('days', v_req.days_list, 'diffLine', v_req.lines) end,
      jsonb_build_object('request_id', v_req.first_id), format('%s:%s:%s', v_event, v_version_id, v_req.requester_id));
    v_notified := v_notified + 1;
  end loop;

  insert into public.siddur_versions (id, department_id, week_start, snapshot, published_by, notified_count)
  values (v_version_id, p_department_id, p_week_start, v_snapshot, (select auth.uid()), v_notified);

  perform set_config('app.in_publish', 'on', true);

  v_phase := case when p_week_start <= public.current_week_start() then 'live' else 'published' end;

  update public.weeks set published_version_id = v_version_id, published_at = now(), phase = v_phase, published_days=v_public_days,
    open_at=least(open_at,now()-interval '1 second'),close_at=now(),publish_at=greatest(publish_at,now())
  where department_id = p_department_id and week_start = p_week_start;

  update public.rides set status = 'confirmed'
  where department_id = p_department_id and week_start = p_week_start and status = 'draft'
    and (starts_at at time zone 'Asia/Jerusalem')::date=any(v_days);

  perform set_config('app.in_publish', 'off', true);

  -- New (this migration): the day(s) just published are now public per is_day_public(), so
  -- any `sent` proposal still pending for one of them is settled face-to-face — expire it
  -- now instead of leaving it for the next app.tick().
  perform public.expire_proposals();

  return v_version_id;
end;
$$;


ALTER FUNCTION "public"."publish_siddur"("p_department_id" "uuid", "p_week_start" "date", "p_profile_scores" "jsonb", "p_expected_fingerprint" "text", "p_policy_scores" "jsonb", "p_days" "date"[], "p_allow_unanswered" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_outbox_notify_dispatch"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  perform public.dispatch_push_outbox_row(new.id);
  return new;
end;
$$;


ALTER FUNCTION "public"."push_outbox_notify_dispatch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."raise_stale_version"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin
  raise exception 'stale_version' using errcode = 'P0409';
end;
$$;


ALTER FUNCTION "public"."raise_stale_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_answer_on_behalf"("p_proposal_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_prop record;
begin
  perform 1 from public.requests q where q.id=(select request_id from public.proposals where id=p_proposal_id) for update;
  select * into v_prop from public.proposals where id = p_proposal_id;
  if v_prop is null then raise exception 'proposal_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_prop.department_id, v_prop.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if v_prop.status <> 'sent' then raise exception 'proposal_not_answerable' using errcode = 'P0001'; end if;

  perform set_config('app.audit_reason', 'record_answer_on_behalf', true);
  update public.proposal_parties set response = (case when p_accept then 'accepted' else 'declined' end)::public.party_response,
    responded_at = now(), responded_via = 'sadran', responded_by = (select auth.uid())
  where proposal_id = p_proposal_id and profile_id = p_profile_id;

  update public.proposals set answered_by = coalesce(answered_by, p_profile_id), answered_at = coalesce(answered_at, now()),
    answered_via = coalesce(answered_via, 'sadran'), answer_note = coalesce(p_note, answer_note)
  where id = p_proposal_id;
end;
$$;


ALTER FUNCTION "public"."record_answer_on_behalf"("p_proposal_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_solver_preview"("p_department_id" "uuid", "p_week_start" "date", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_run_id uuid;
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  insert into public.solver_runs (department_id, week_start, policy_version_id, input_hash, solver_version,
    status, started_at, finished_at, duration_ms, ran_by, applied, summary, error, state_fingerprint)
  values (p_department_id, p_week_start, (p_payload ->> 'policy_version_id')::uuid, p_payload ->> 'input_hash',
    p_payload ->> 'solver_version', coalesce((p_payload ->> 'status')::public.solver_run_status, 'succeeded'),
    (p_payload ->> 'started_at')::timestamptz, (p_payload ->> 'finished_at')::timestamptz,
    (p_payload ->> 'duration_ms')::int, (select auth.uid()), false, coalesce(p_payload -> 'summary', '{}'),
    p_payload ->> 'error', public.week_state_fingerprint(p_department_id, p_week_start))
  returning id into v_run_id;
  return v_run_id;
end;
$$;


ALTER FUNCTION "public"."record_solver_preview"("p_department_id" "uuid", "p_week_start" "date", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_car_turnarounds"("p_car_id" "uuid", "p_week_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r record; next_start timestamptz; required int; override_value smallint;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_car_id::text,0));
  for r in select * from public.rides where car_id=p_car_id and week_start=p_week_start and status<>'cancelled' and not planning_conflict and turnaround_override_minutes is not null order by starts_at desc for update loop
    required:=public.required_turnaround_minutes(r.department_id,r.week_start);
    select min(starts_at) into next_start from public.rides where car_id=p_car_id and status<>'cancelled' and not planning_conflict and starts_at>=r.ends_at and id<>r.id;
    override_value:=case when next_start<r.ends_at+make_interval(mins=>required) then (extract(epoch from(next_start-r.ends_at))/60)::smallint end;
    if r.turnaround_override_minutes is distinct from override_value then update public.rides set turnaround_override_minutes=override_value where id=r.id; end if;
  end loop;
end $$;


ALTER FUNCTION "public"."refresh_car_turnarounds"("p_car_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_push_subscription"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into public.push_subscriptions (profile_id, endpoint, p256dh, auth, user_agent, created_at, last_used_at)
  values ((select auth.uid()), p_endpoint, p_p256dh, p_auth, p_user_agent, now(), now())
  on conflict (endpoint) do update set p256dh = excluded.p256dh, auth = excluded.auth,
    user_agent = excluded.user_agent, last_used_at = now(), failure_count = 0, profile_id = excluded.profile_id
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."register_push_subscription"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_request_draft_rides"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r record; ids uuid[];
begin
  perform set_config('app.system_status_transition','on',true);
  for r in select rd.* from public.rides rd join public.ride_requests rr on rr.ride_id=rd.id where rr.request_id=p_request_id and rd.status='draft' order by rd.id for update of rd loop
    select array_agg(request_id) into ids from public.ride_requests where ride_id=r.id;
    update public.rides set status='cancelled',cancelled_at=now(),cancelled_by=(select auth.uid()),cancel_reason='REQUEST_EDITED' where id=r.id;
    delete from public.ride_requests where ride_id=r.id;
    update public.requests q set status='submitted',status_reason=null where id=any(ids) and not exists(
      select 1 from public.ride_requests rr join public.rides rd on rd.id=rr.ride_id where rr.request_id=q.id and rd.status<>'cancelled');
  end loop;
  perform set_config('app.system_status_transition','off',true);
end $$;


ALTER FUNCTION "public"."release_request_draft_rides"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_ride_person"("p_ride_id" "uuid", "p_expected_version" integer, "p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_actor uuid := (select auth.uid());
  v_actor_name text;
  v_destination_name text;
  v_route text;
  v_prefix text;
  v_request_id uuid;
  v_profile_id uuid;
  v_child_id uuid;
  v_ride_passenger_id uuid;
  v_n int;
  v_display_name text;
  v_new_version int;
  v_removed_person_id uuid;
  v_removed_child_id uuid;
  v_removed_display_name text;
  v_skip_notify boolean := false;
  v_guardian record;
begin
  select * into v_ride from public.rides where id = p_ride_id for update;
  if not found or v_ride.status = 'cancelled' then raise exception 'ride_not_found' using errcode = 'P0001'; end if;

  if not public.member_of(v_ride.department_id) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if not (public.is_week_public(v_ride.department_id, v_ride.week_start) or public.can_manage_week(v_ride.department_id, v_ride.week_start)) then
    raise exception 'ride_week_not_public' using errcode = 'P0001';
  end if;

  if p_expected_version is null or v_ride.version <> p_expected_version then
    perform public.raise_stale_version();
  end if;

  if exists (select 1 from public.weeks where department_id = v_ride.department_id and week_start = v_ride.week_start and phase = 'archived') then
    raise exception 'week_archived' using errcode = 'P0001';
  end if;

  v_prefix := split_part(coalesce(p_key, ''), ':', 1);
  perform set_config('app.audit_reason', 'remove_ride_person', true);

  if v_prefix = 'driver' then
    raise exception 'ride_driver_not_removable' using errcode = 'P0001';

  elsif v_prefix = 'added' then
    v_ride_passenger_id := nullif(split_part(p_key, ':', 2), '')::uuid;
    select person_id, child_id, display_name into v_removed_person_id, v_removed_child_id, v_removed_display_name
    from public.ride_passengers where id = v_ride_passenger_id and ride_id = p_ride_id;
    if not found then raise exception 'ride_not_found' using errcode = 'P0001'; end if;
    delete from public.ride_passengers where id = v_ride_passenger_id;
    v_skip_notify := v_removed_person_id is null and v_removed_child_id is null; -- free-text guest

  elsif v_prefix = 'comp' then
    v_request_id := nullif(split_part(p_key, ':', 2), '')::uuid;
    v_profile_id := nullif(split_part(p_key, ':', 3), '')::uuid;
    if v_request_id is null or v_profile_id is null
      or not exists (select 1 from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id)
    then
      raise exception 'ride_not_found' using errcode = 'P0001';
    end if;
    select full_name into v_removed_display_name from public.profiles where id = v_profile_id;
    delete from public.request_companions where request_id = v_request_id and profile_id = v_profile_id;
    update public.requests set updated_at = now() where id = v_request_id;
    v_removed_person_id := v_profile_id;

  elsif v_prefix = 'child' then
    v_request_id := nullif(split_part(p_key, ':', 2), '')::uuid;
    v_child_id := nullif(split_part(p_key, ':', 3), '')::uuid;
    if v_request_id is null or v_child_id is null
      or not exists (select 1 from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id)
    then
      raise exception 'ride_not_found' using errcode = 'P0001';
    end if;
    select full_name into v_removed_display_name from public.children where id = v_child_id;
    delete from public.request_children where request_id = v_request_id and child_id = v_child_id;
    update public.requests set updated_at = now() where id = v_request_id;
    v_removed_child_id := v_child_id;

  elsif v_prefix = 'guest' then
    v_request_id := nullif(split_part(p_key, ':', 2), '')::uuid;
    v_n := nullif(split_part(p_key, ':', 3), '')::int;
    if v_request_id is null or v_n is null or v_n < 1
      or not exists (select 1 from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id)
    then
      raise exception 'ride_not_found' using errcode = 'P0001';
    end if;
    update public.requests
      set guest_passenger_names = guest_passenger_names[1 : v_n - 1] || guest_passenger_names[v_n + 1 : cardinality(guest_passenger_names)]
      where id = v_request_id and v_n <= cardinality(guest_passenger_names);
    if not found then raise exception 'ride_not_found' using errcode = 'P0001'; end if;
    v_skip_notify := true; -- free-text guest: nobody is notified

  elsif v_prefix = 'req' then
    v_request_id := nullif(split_part(p_key, ':', 2), '')::uuid;
    if v_request_id is null then raise exception 'ride_not_found' using errcode = 'P0001'; end if;
    select requester_id into v_profile_id from public.requests where id = v_request_id;
    if v_profile_id is null
      or not exists (select 1 from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id)
    then
      raise exception 'ride_not_found' using errcode = 'P0001';
    end if;
    if v_profile_id = v_ride.driver_id then
      raise exception 'ride_driver_not_removable' using errcode = 'P0001';
    end if;
    select full_name into v_removed_display_name from public.profiles where id = v_profile_id;
    delete from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id;
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'withdrawn', status_reason = 'WITHDRAWN_BY_MEMBER' where id = v_request_id;
    perform set_config('app.system_status_transition', 'off', true);
    v_removed_person_id := v_profile_id;

  else
    raise exception 'invalid_ride_passenger' using errcode = 'P0001';
  end if;

  update public.rides set updated_at = now() where id = p_ride_id
  returning version into v_new_version;

  if not v_skip_notify then
    select full_name into v_actor_name from public.profiles where id = v_actor;

    -- The driver is always told who was removed, unless the driver is the one removing them.
    if v_ride.driver_id is not null and v_ride.driver_id is distinct from v_actor then
      perform public.enqueue_notification(v_ride.driver_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
        jsonb_build_object('byName', coalesce(v_actor_name, ''), 'names', coalesce(v_removed_display_name, '')),
        jsonb_build_object('variant', 'passengers_removed', 'ride_id', p_ride_id),
        format('passengers_removed:%s:%s:%s', p_ride_id, v_new_version, v_ride.driver_id));
    end if;

    if v_removed_person_id is not null and v_removed_person_id is distinct from v_actor then
      select name into v_destination_name from public.destinations where id = v_ride.destination_id;
      v_route := public.route_label(v_ride.department_id, v_ride.origin_id, null, v_ride.destination_id, null);
      perform public.enqueue_notification(v_removed_person_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
        jsonb_build_object('byName', coalesce(v_actor_name, ''), 'destination', coalesce(v_destination_name, ''), 'route', coalesce(v_route, '')),
        jsonb_build_object('variant', 'passenger_removed_you', 'ride_id', p_ride_id),
        format('passenger_removed_you:%s:%s:%s', p_ride_id, v_new_version, v_removed_person_id));
    end if;

    if v_removed_child_id is not null then
      select name into v_destination_name from public.destinations where id = v_ride.destination_id;
      v_route := public.route_label(v_ride.department_id, v_ride.origin_id, null, v_ride.destination_id, null);
      for v_guardian in select cg.profile_id from public.child_guardians cg where cg.child_id = v_removed_child_id loop
        if v_guardian.profile_id is distinct from v_actor then
          perform public.enqueue_notification(v_guardian.profile_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
            jsonb_build_object('byName', coalesce(v_actor_name, ''), 'childName', coalesce(v_removed_display_name, ''), 'destination', coalesce(v_destination_name, ''), 'route', coalesce(v_route, '')),
            jsonb_build_object('variant', 'child_removed', 'ride_id', p_ride_id),
            format('child_removed:%s:%s:%s:%s', p_ride_id, v_new_version, v_removed_child_id, v_guardian.profile_id));
        end if;
      end loop;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."remove_ride_person"("p_ride_id" "uuid", "p_expected_version" integer, "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."render_notification_text"("_text" "text", "_vars" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare result text:=coalesce(_text,''); k text; v text;
begin
  for k,v in select key,value from jsonb_each_text(coalesce(_vars,'{}'::jsonb)) loop
    result:=replace(result,'{{'||k||'}}',coalesce(v,''));
  end loop;
  return regexp_replace(result,'\{\{[^{}]+\}\}','','g');
end $$;


ALTER FUNCTION "public"."render_notification_text"("_text" "text", "_vars" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_week"("p_department_id" "uuid", "p_week_start" "date", "p_phase" "public"."week_phase", "p_expected_fingerprint" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare w public.weeks%rowtype; deadline timestamptz;
begin
  if not public.is_approved() or not public.can_manage_week(p_department_id,p_week_start) then raise exception 'not_authorized';end if;
  if p_phase not in ('open','solving') or p_phase is null then raise exception 'not_authorized';end if;
  select * into w from public.weeks where department_id=p_department_id and week_start=p_week_start for update;
  if not found then raise exception 'week_not_open';end if;
  if w.phase='archived' or now()>=upper(public.week_range(p_week_start)) then raise exception 'week_archived';end if;
  lock table public.requests,public.rides,public.ride_requests,public.proposals,public.proposal_parties,public.ride_change_requests,public.ride_change_parties in share mode;
  if p_expected_fingerprint is null or p_expected_fingerprint<>public.publish_scores_fingerprint(p_department_id,p_week_start) then
    raise exception 'stale_input' using errcode='P0409';
  end if;
  deadline:=case when p_phase='open' then greatest(w.close_at,upper(public.week_range(p_week_start))) else now() end;
  perform set_config('app.audit_reason','reopen_week',true);
  perform set_config('app.in_publish','on',true);
  update public.weeks set phase=p_phase,published_days='{}',published_version_id=null,published_at=null,
    open_at=least(open_at,now()-interval '1 second'),close_at=deadline,publish_at=greatest(publish_at,deadline)
    where department_id=p_department_id and week_start=p_week_start;
  -- Keep real ongoing/completed rides intact. Future assignments become private
  -- drafts with all IDs, windows, drivers, seats, pins and request links preserved.
  update public.rides set status='draft' where department_id=p_department_id and week_start=p_week_start
    and status in ('confirmed','flagged') and starts_at>now();
  perform set_config('app.in_publish','off',true);
end;
$$;


ALTER FUNCTION "public"."reopen_week"("p_department_id" "uuid", "p_week_start" "date", "p_phase" "public"."week_phase", "p_expected_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_request_stops"("p_request_id" "uuid", "p_department_id" "uuid", "p_has_return" boolean, "p_stops" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_item jsonb; v_leg text; v_place_id uuid; v_place_text text;
  v_out_pos smallint := 0; v_return_pos smallint := 0;
begin
  if jsonb_typeof(p_stops) is distinct from 'array' then
    raise exception 'invalid_stops' using errcode = 'P0001';
  end if;

  delete from public.request_stops where request_id = p_request_id;

  for v_item in select * from jsonb_array_elements(p_stops) loop
    if jsonb_typeof(v_item) <> 'object' then raise exception 'invalid_stops' using errcode = 'P0001'; end if;
    v_leg := v_item ->> 'leg';
    v_place_id := nullif(v_item ->> 'place_id', '')::uuid;
    v_place_text := nullif(v_item ->> 'place_text', '');

    if v_leg not in ('out', 'return') then raise exception 'invalid_stops' using errcode = 'P0001'; end if;
    if (v_place_id is null) = (v_place_text is null) then raise exception 'invalid_stops' using errcode = 'P0001'; end if;
    if v_place_id is not null and not exists (
      select 1 from public.destinations d
      where d.id = v_place_id and d.department_id = p_department_id and d.is_approved
    ) then raise exception 'invalid_stops' using errcode = 'P0001'; end if;

    if v_leg = 'out' then
      v_out_pos := v_out_pos + 1;
      if v_out_pos > 10 then raise exception 'invalid_stops' using errcode = 'P0001'; end if;
      insert into public.request_stops (request_id, department_id, leg, "position", place_id, place_text)
      values (p_request_id, p_department_id, 'out', v_out_pos, v_place_id, v_place_text);
    else
      v_return_pos := v_return_pos + 1;
      if v_return_pos > 10 then raise exception 'invalid_stops' using errcode = 'P0001'; end if;
      insert into public.request_stops (request_id, department_id, leg, "position", place_id, place_text)
      values (p_request_id, p_department_id, 'return', v_return_pos, v_place_id, v_place_text);
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."replace_request_stops"("p_request_id" "uuid", "p_department_id" "uuid", "p_has_return" boolean, "p_stops" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_car_issue"("_car_id" "uuid", "_category" "public"."car_issue_category", "_description" "text", "_photo_path" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid;
  v_car_name text;
  v_by_name text;
  v_issue_id uuid;
  v_recipient uuid;
begin
  select department_id, name into v_dept, v_car_name from public.cars where id = _car_id;
  if v_dept is null then
    raise exception 'car_not_found' using errcode = 'P0001';
  end if;
  if not public.member_of(v_dept) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if length(trim(coalesce(_description, ''))) = 0 then
    raise exception 'description_required' using errcode = 'P0001';
  end if;

  insert into public.car_issues (car_id, reported_by, description, category, photo_path)
  values (_car_id, (select auth.uid()), _description, _category, _photo_path)
  returning id into v_issue_id;

  select full_name into v_by_name from public.profiles where id = (select auth.uid());

  for v_recipient in select * from public.car_care_recipients(_car_id) loop
    perform public.enqueue_notification(v_recipient, 'car_care', v_dept, null,
      jsonb_build_object('carName', v_car_name, 'byName', coalesce(v_by_name, ''),
        'description', left(_description, 100)),
      jsonb_build_object('variant', 'issue_' || _category::text, 'car_id', _car_id, 'issue_id', v_issue_id),
      format('car_care:issue:%s:%s', v_issue_id, v_recipient));
  end loop;

  return v_issue_id;
end;
$$;


ALTER FUNCTION "public"."report_car_issue"("_car_id" "uuid", "_category" "public"."car_issue_category", "_description" "text", "_photo_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_car_issue_unsafe_to_maintenance"("p_issue_id" "uuid", "p_hours" integer DEFAULT 24) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_issue record; v_block_id uuid;
begin
  select * into v_issue from public.car_issues where id = p_issue_id;
  if v_issue is null then raise exception 'car_issue_not_found' using errcode = 'P0001'; end if;
  if not (public.is_admin() or public.is_sadran_any(v_issue.department_id)) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'report_car_issue_unsafe_to_maintenance', true);
  insert into public.car_maintenance_blocks (car_id, starts_at, ends_at, reason, created_by)
  values (v_issue.car_id, now(), now() + make_interval(hours => p_hours), 'UNSAFE_ISSUE', (select auth.uid()))
  returning id into v_block_id;
  update public.cars set status = 'maintenance' where id = v_issue.car_id;
  return v_block_id;
end;
$$;


ALTER FUNCTION "public"."report_car_issue_unsafe_to_maintenance"("p_issue_id" "uuid", "p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_companions_not_requester"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if exists (select 1 from public.requests q where q.id = new.request_id and q.requester_id = new.profile_id) then
    raise exception 'companion_cannot_be_requester' using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."request_companions_not_requester"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_leg_route_km"("p_request_id" "uuid", "p_leg" "public"."ride_leg") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_total numeric := 0; v_prev record; v_cur record; v_has_prev boolean := false;
begin
  for v_cur in select * from public.request_leg_route_points(p_request_id, p_leg) order by "position" loop
    if v_has_prev then
      v_total := v_total + coalesce(
        case when v_prev.place_id is not null and v_cur.place_id is not null
          then (select distance_km from public.place_travel(v_prev.place_id, v_cur.place_id))
        end, 0);
    end if;
    v_prev := v_cur;
    v_has_prev := true;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."request_leg_route_km"("p_request_id" "uuid", "p_leg" "public"."ride_leg") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_leg_route_minutes"("p_request_id" "uuid", "p_leg" "public"."ride_leg") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid; v_stop_minutes int; v_total int := 0; v_stop_count int;
  v_prev record; v_cur record; v_has_prev boolean := false;
begin
  select department_id into v_dept from public.requests where id = p_request_id;
  if v_dept is null then return null; end if;

  select stop_minutes into v_stop_minutes from public.department_settings where department_id = v_dept;
  v_stop_minutes := coalesce(v_stop_minutes, 5);

  -- REQ §13.97: return-leg stops are inactive while the request has no return.
  select count(*) into v_stop_count from public.request_stops s
  where s.request_id = p_request_id and s.leg = p_leg
    and (p_leg = 'out' or exists (select 1 from public.requests q where q.id = p_request_id and q.return_at is not null));

  for v_cur in select * from public.request_leg_route_points(p_request_id, p_leg) order by "position" loop
    if v_has_prev then
      v_total := v_total + greatest(coalesce(
        case when v_prev.place_id is not null and v_cur.place_id is not null
          then (select travel_minutes from public.place_travel(v_prev.place_id, v_cur.place_id))
        end, 30), 0);
    end if;
    v_prev := v_cur;
    v_has_prev := true;
  end loop;

  return v_total + v_stop_count * v_stop_minutes;
end;
$$;


ALTER FUNCTION "public"."request_leg_route_minutes"("p_request_id" "uuid", "p_leg" "public"."ride_leg") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_leg_route_points"("p_request_id" "uuid", "p_leg" "public"."ride_leg") RETURNS TABLE("position" smallint, "place_id" "uuid", "place_text" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.requests%rowtype;
  v_start_id uuid; v_start_text text; v_end_id uuid; v_end_text text;
  v_stop_count smallint;
begin
  select * into v_req from public.requests where id = p_request_id;
  if v_req.id is null then return; end if;
  if p_leg = 'out' then
    v_start_id := v_req.origin_id; v_start_text := v_req.origin_text;
    v_end_id := v_req.destination_id; v_end_text := v_req.destination_text;
  elsif p_leg = 'return' then
    v_start_id := v_req.destination_id; v_start_text := v_req.destination_text;
    v_end_id := v_req.origin_id; v_end_text := v_req.origin_text;
  else
    return; -- 'both' has no stored request_stops rows; callers always pass 'out'/'return'.
  end if;

  -- REQ §13.97: return-leg stops are stored but inactive while the request has no return.
  select count(*) into v_stop_count from public.request_stops s
  where s.request_id = p_request_id and s.leg = p_leg and (p_leg = 'out' or v_req.return_at is not null);

  return query
    select 0::smallint, v_start_id, v_start_text
    union all
    select s."position", s.place_id, s.place_text
    from public.request_stops s where s.request_id = p_request_id and s.leg = p_leg
      and (p_leg = 'out' or v_req.return_at is not null)
    union all
    select (v_stop_count + 1)::smallint, v_end_id, v_end_text
    order by 1;
end;
$$;


ALTER FUNCTION "public"."request_leg_route_points"("p_request_id" "uuid", "p_leg" "public"."ride_leg") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_named_passenger_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name='requests' then
    if tg_op='UPDATE' and new.adults=old.adults and new.child_seats=old.child_seats and new.boosters=old.boosters and new.guest_passenger_names=old.guest_passenger_names then return null;end if;
    perform public.assert_named_passenger_counts(new.id);
  else perform public.assert_named_passenger_counts(coalesce(new.request_id,old.request_id));end if;
  return null;
end $$;


ALTER FUNCTION "public"."request_named_passenger_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_ride_change"("p_ride_id" "uuid", "p_car_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_expected_version" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.rides%rowtype; other public.rides%rowtype; ch uuid; buffer interval; cnt int:=0;
begin
  select * into r from public.rides where id=p_ride_id for update;
  if not found then raise exception 'ride_not_found'; end if;
  if not public.is_approved() or r.driver_id is distinct from (select auth.uid()) or not public.is_week_public(r.department_id,r.week_start) then raise exception 'not_authorized'; end if;
  if r.status='cancelled' or r.version<>p_expected_version then perform public.raise_stale_version(); end if;
  if p_starts_at<=now() or p_ends_at<=p_starts_at or (p_starts_at at time zone 'Asia/Jerusalem')::date<>(r.starts_at at time zone 'Asia/Jerusalem')::date then raise exception 'ride_request_day_mismatch'; end if;
  if not (public.week_range(r.week_start) @> tstzrange(p_starts_at,p_ends_at,'[)')) then raise exception 'ride_outside_week'; end if;
  if exists(select 1 from public.ride_requests rr join public.requests q on q.id=rr.request_id where rr.ride_id=r.id and (q.requester_id<>r.driver_id or rr.car_mode='relay')) then raise exception 'shared_ride_requires_sadran'; end if;
  perform 1 from public.cars where id=p_car_id and department_id=r.department_id and status='active' and type='shared' for update;
  if not found then raise exception 'car_unavailable'; end if;
  select make_interval(mins=>coalesce((w.settings_overrides->>'turnaround_minutes')::int,s.turnaround_minutes)) into buffer
  from public.department_settings s join public.weeks w on w.department_id=s.department_id where w.department_id=r.department_id and w.week_start=r.week_start;
  if exists(select 1 from public.car_maintenance_blocks where car_id=p_car_id and tstzrange(starts_at,ends_at,'[)') && tstzrange(p_starts_at,p_ends_at+buffer,'[)')) then raise exception 'ride_conflicts_with_maintenance'; end if;
  update public.ride_change_requests set status='cancelled' where ride_id=r.id and status='pending';
  insert into public.ride_change_requests(department_id,week_start,requester_id,ride_id,car_id,starts_at,ends_at,expected_version)
  values(r.department_id,r.week_start,(select auth.uid()),r.id,p_car_id,p_starts_at,p_ends_at,r.version) returning id into ch;
  for other in select * from public.rides where car_id=p_car_id and id<>r.id and status<>'cancelled'
    and tstzrange(starts_at,blocked_until,'[)') && tstzrange(p_starts_at,p_ends_at+buffer,'[)') order by id for update loop
    if other.driver_id is null or other.driver_id=r.driver_id or other.origin_id<>other.destination_id
      or exists(select 1 from public.ride_requests rr join public.requests q on q.id=rr.request_id where rr.ride_id=other.id and q.requester_id<>other.driver_id)
    then raise exception 'shared_ride_requires_sadran'; end if;
    insert into public.ride_change_parties(change_id,ride_id,profile_id,expected_version) values(ch,other.id,other.driver_id,other.version);
    perform public.enqueue_notification(other.driver_id,'proposal_received',r.department_id,r.week_start,
      jsonb_build_object('requesterName',(select full_name from public.profiles where id=r.driver_id),
        'date',to_char(p_starts_at at time zone 'Asia/Jerusalem','DD/MM/YY'),
        'depart',to_char(p_starts_at at time zone 'Asia/Jerusalem','HH24:MI'),'return',to_char(p_ends_at at time zone 'Asia/Jerusalem','HH24:MI')),
      jsonb_build_object('ride_change_id',ch,'ride_id',other.id,'url','/inbox?change='||ch),format('ride_change:%s:%s',ch,other.driver_id));
    cnt:=cnt+1;
  end loop;
  if cnt=0 then raise exception 'no_conflicting_ride'; end if;
  return ch;
end $$;


ALTER FUNCTION "public"."request_ride_change"("p_ride_id" "uuid", "p_car_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_route_label"("p_request_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.route_label(q.department_id, q.origin_id, q.origin_text, q.destination_id, q.destination_text, stops.names)
  from public.requests q
  left join lateral (
    select string_agg(coalesce(d.name, s.place_text), ', ' order by s."position") as names
    from public.request_stops s
    left join public.destinations d on d.id = s.place_id
    where s.request_id = q.id and s.leg = 'out'
  ) stops on true
  where q.id = p_request_id;
$$;


ALTER FUNCTION "public"."request_route_label"("p_request_id" "uuid") OWNER TO "postgres";


