    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id
    where rr.request_id=_request_id and r.status not in ('draft','cancelled')
      and public.is_day_public(r.department_id,r.week_start,(r.starts_at at time zone 'Asia/Jerusalem')::date));
$$;


ALTER FUNCTION "public"."request_served_by_public_ride"("_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_span"("_depart" timestamp with time zone, "_return" timestamp with time zone) RETURNS "tstzrange"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select tstzrange(coalesce(_depart, _return), coalesce(_return, _depart), '[]');
$$;


ALTER FUNCTION "public"."request_span"("_depart" timestamp with time zone, "_return" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_stop_etas"("p_request_id" "uuid") RETURNS TABLE("leg" "public"."ride_leg", "position" smallint, "place_id" "uuid", "place_text" "text", "eta" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.requests%rowtype;
  v_stop record;
  v_t timestamptz;
  v_anchor_id uuid; v_anchor_text text;
  v_stop_minutes int;
begin
  select * into v_req from public.requests where id = p_request_id;
  if v_req.id is null then return; end if;
  select stop_minutes into v_stop_minutes from public.department_settings where department_id = v_req.department_id;
  v_stop_minutes := coalesce(v_stop_minutes, 5);

  if v_req.depart_at is not null then
    v_t := v_req.depart_at;
    v_anchor_id := v_req.origin_id; v_anchor_text := v_req.origin_text;
    for v_stop in
      select * from public.request_stops s where s.request_id = p_request_id and s.leg = 'out' order by s."position"
    loop
      v_t := v_t + make_interval(mins => greatest(coalesce(
        case when v_anchor_id is not null and v_stop.place_id is not null
          then (select travel_minutes from public.place_travel(v_anchor_id, v_stop.place_id)) end, 30), 0));
      leg := 'out'; "position" := v_stop."position"; place_id := v_stop.place_id; place_text := v_stop.place_text; eta := v_t;
      return next;
      v_t := v_t + make_interval(mins => v_stop_minutes);
      v_anchor_id := v_stop.place_id; v_anchor_text := v_stop.place_text;
    end loop;
  end if;

  if v_req.return_at is not null then
    v_t := v_req.return_at;
    v_anchor_id := v_req.origin_id; v_anchor_text := v_req.origin_text;  -- final arrival point
    for v_stop in
      select * from public.request_stops s where s.request_id = p_request_id and s.leg = 'return' order by s."position" desc
    loop
      v_t := v_t - make_interval(mins => greatest(coalesce(
        case when v_stop.place_id is not null and v_anchor_id is not null
          then (select travel_minutes from public.place_travel(v_stop.place_id, v_anchor_id)) end, 30), 0));
      leg := 'return'; "position" := v_stop."position"; place_id := v_stop.place_id; place_text := v_stop.place_text; eta := v_t;
      return next;
      v_t := v_t - make_interval(mins => v_stop_minutes);
      v_anchor_id := v_stop.place_id; v_anchor_text := v_stop.place_text;
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "public"."request_stop_etas"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_stops_with_eta"("p_request_id" "uuid") RETURNS TABLE("leg" "public"."ride_leg", "position" smallint, "place_id" "uuid", "place_text" "text", "eta" timestamp with time zone, "active" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- REQ §13.97: every stored stop; return-leg stops are inactive (and have no ETA) while the request has no return.
  select s.leg, s."position", s.place_id, s.place_text, e.eta,
         (s.leg = 'out' or q.return_at is not null)
  from public.request_stops s
  join public.requests q on q.id = s.request_id
  left join public.request_stop_etas(p_request_id) e on e.leg = s.leg and e."position" = s."position"
  where s.request_id = p_request_id;
$$;


ALTER FUNCTION "public"."request_stops_with_eta"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requests_default_origin"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare v_origin uuid;
begin
  if new.origin_id is null and new.origin_text is null then
    select dm.default_origin_id into v_origin from public.department_members dm
      where dm.department_id = new.department_id and dm.profile_id = new.requester_id and dm.removed_at is null;
    if v_origin is null then
      select home_destination_id into v_origin from public.departments where id = new.department_id;
    end if;
    new.origin_id := v_origin;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."requests_default_origin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requests_preserve_original_times"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if tg_op='INSERT' or coalesce(current_setting('app.reset_request_baseline',true),'off')='on' then
    new.original_depart_at:=new.depart_at;new.original_return_at:=new.return_at;
  else
    new.original_depart_at:=old.original_depart_at;new.original_return_at:=old.original_return_at;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."requests_preserve_original_times"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requests_status_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if tg_op = 'INSERT' then
    return new;
  end if;
  if new.status = old.status and new.status_reason is not distinct from old.status_reason then
    return new;
  end if;
  if coalesce(current_setting('app.system_status_transition', true), 'off') = 'on' then
    return new;
  end if;
  -- No JWT at all (service role / cron / a plain `postgres` session): trusted, same as the
  -- system-transition flag above.
  if (select auth.uid()) is null then
    return new;
  end if;
  if old.status in ('withdrawn', 'cancelled') then
    raise exception 'invalid_request_status_transition' using errcode = 'P0001',
      detail = format('request %s status %s is terminal', old.id, old.status);
  end if;
  if (select auth.uid()) = old.requester_id then
    -- Unchanged from 20260907092800: a requester may move their own request only to
    -- withdrawn/cancelled, unless they can also manage the week (Sadran/admin acting on
    -- their own request).
    if not public.can_manage_week(old.department_id, old.week_start) and new.status not in ('withdrawn', 'cancelled') then
      raise exception 'invalid_request_status_transition' using errcode = 'P0001',
        detail = format('member cannot move request %s from %s to %s', old.id, old.status, new.status);
    end if;
    return new;
  end if;
  -- New (R12): anyone else touching this row must manage ITS OWN department/week — closes
  -- the gap a Sadran of a different department, or an under-scoped RPC, would otherwise fall
  -- through.
  if public.can_manage_week(new.department_id, new.week_start) then
    return new;
  end if;
  raise exception 'not_authorized' using errcode = 'P0001';
end;
$$;


ALTER FUNCTION "public"."requests_status_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requests_within_week"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='UPDATE' and new.depart_at is not distinct from old.depart_at and new.return_at is not distinct from old.return_at
    and new.week_start=old.week_start and new.trip_shape=old.trip_shape then return new; end if;
  if new.depart_at is not null and new.return_at is not null then perform public.assert_same_day_window(new.depart_at,new.return_at); end if;
  if not (public.week_range(new.week_start) @> public.request_span(new.depart_at,new.return_at)) then raise exception 'request_outside_week'; end if;
  return new;
end $$;


ALTER FUNCTION "public"."requests_within_week"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."required_turnaround_minutes"("p_department_id" "uuid", "p_week_start" "date") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce((w.settings_overrides->>'turnaround_minutes')::int,s.turnaround_minutes,30)
  from public.department_settings s left join public.weeks w on w.department_id=s.department_id and w.week_start=p_week_start
  where s.department_id=p_department_id;
$$;


ALTER FUNCTION "public"."required_turnaround_minutes"("p_department_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_live_one_way_slot"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare q public.requests%rowtype; c record; dwell int; duration_minutes int; travel int;
  start_time timestamptz; end_time timestamptz; buffer_minutes int; ride_id uuid;
  pickup_start timestamptz; pickup_end timestamptz;
  v_start timestamptz; v_end timestamptz; v_loc uuid;
  week_from timestamptz; week_until timestamptz; request_day date;
begin
  select * into q from public.requests where id=p_request_id for update;
  if not found or q.requester_id is distinct from (select auth.uid()) or not public.member_of(q.department_id)
    or q.trip_shape='round_trip' or q.trip_type is distinct from 'drop_off' or not exists(select 1 from public.weeks where department_id=q.department_id and week_start=q.week_start and phase='live')
    or exists(select 1 from public.ride_requests where request_id=q.id) then raise exception 'invalid_quick_reservation';end if;
  select coalesce((w.settings_overrides->>'chauffeur_dwell_minutes')::int,s.chauffeur_dwell_minutes,10)
    into dwell from public.department_settings s
    join public.weeks w on w.department_id=s.department_id and w.week_start=q.week_start where s.department_id=q.department_id;
  travel := greatest(coalesce(public.request_leg_route_minutes(
    q.id, case when q.trip_shape='one_way_to' then 'out'::public.ride_leg else 'return'::public.ride_leg end), 30), 0);
  duration_minutes:=greatest(15,ceil((2*travel+greatest(dwell,0))/15.0)::int*15);
  if q.trip_shape='one_way_to' then
    start_time:=q.depart_at;end_time:=q.depart_at+make_interval(mins=>duration_minutes);
    -- Pickup candidate: back at the car's place `t` after collecting the member at D,
    -- rounded up to the 15-minute grid; the window keeps the same total duration.
    pickup_end:=q.depart_at+make_interval(mins=>ceil(travel/15.0)::int*15);
    pickup_start:=pickup_end-make_interval(mins=>duration_minutes);
  else end_time:=q.return_at;start_time:=q.return_at-make_interval(mins=>duration_minutes);end if;
  if start_time<now() then raise exception 'ride_in_past';end if;
  week_from:=q.week_start::timestamp at time zone 'Asia/Jerusalem';
  week_until:=(q.week_start+7)::timestamp at time zone 'Asia/Jerusalem';
  if start_time<week_from or end_time>week_until then raise exception 'ride_outside_week';end if;
  request_day:=(coalesce(q.depart_at,q.return_at) at time zone 'Asia/Jerusalem')::date;
  if (start_time at time zone 'Asia/Jerusalem')::date<>request_day then raise exception 'ride_request_day_mismatch';end if;
  buffer_minutes:=coalesce(public.required_turnaround_minutes(q.department_id,q.week_start),30);
  perform set_config('app.audit_reason','reserve_live_one_way_slot',true);
  perform set_config('app.system_status_transition','on',true);
  if q.origin_id is not null then
    for c in select car.id from public.cars car where car.department_id=q.department_id and car.status='active' and car.type='shared'
      and exists(select 1 from public.car_seat_configs seats where seats.car_id=car.id and seats.adults>=q.adults+1 and seats.child_seats>=q.child_seats and seats.boosters>=q.boosters)
      order by (car.id=q.preferred_car_id) desc nulls last,car.id loop
      -- A car being reserved by another transaction is temporarily unavailable; try the next one.
      if not pg_try_advisory_xact_lock(hashtextextended(c.id::text,0)) then continue;end if;
      perform 1 from public.cars where id=c.id and status='active' and type='shared' for share;
      if not found then continue;end if;
      v_loc:=null;
      if public.car_location_at(c.id,start_time) is not distinct from q.origin_id then
        v_start:=start_time;v_end:=end_time;v_loc:=q.origin_id;
      elsif q.trip_shape='one_way_to' and q.destination_id is not null
        and pickup_start>=now() and pickup_start>=week_from
        and (pickup_start at time zone 'Asia/Jerusalem')::date=request_day
        and public.car_location_at(c.id,pickup_start) is not distinct from q.destination_id then
        v_start:=pickup_start;v_end:=pickup_end;v_loc:=q.destination_id;
      end if;
      if v_loc is null
        or exists(select 1 from public.rides r where r.car_id=c.id and r.status<>'cancelled'
          and tstzrange(r.starts_at,r.blocked_until,'[)') && tstzrange(v_start,v_end+make_interval(mins=>buffer_minutes),'[)'))
        or exists(select 1 from public.car_maintenance_blocks b where b.car_id=c.id
          and tstzrange(b.starts_at,b.ends_at,'[)') && tstzrange(v_start,v_end+make_interval(mins=>buffer_minutes),'[)')) then continue;end if;
      begin
        insert into public.rides(department_id,week_start,car_id,starts_at,ends_at,origin_id,destination_id,driver_id,needs_driver,status,is_pinned,pin_reason,created_by)
          values(q.department_id,q.week_start,c.id,v_start,v_end,v_loc,v_loc,null,true,'confirmed',true,'MISSING_DRIVER',q.requester_id) returning id into ride_id;
        insert into public.ride_requests(ride_id,request_id,role,leg,car_mode)
          values(ride_id,q.id,'passenger',case when q.trip_shape='one_way_to' then 'out'::public.ride_leg else 'return'::public.ride_leg end,'chauffeur');
        perform public.assert_ride_driver(ride_id);perform public.assert_ride_request_day(ride_id);
        perform public.assert_ride_seats_fit(ride_id);perform public.assert_car_chain(c.id,q.week_start);
        -- REQ §13.88 (owner 2026-09-24): the chain check may have paired this leg with a matching
        -- leg at X (any non-overlapping gap now pairs) — then it is an ordinary driven relay leg,
        -- already `assigned`/RELAY_PAIRED by pair_one_way_legs(); report that instead.
        if exists(select 1 from public.ride_requests rr where rr.request_id=q.id and rr.car_mode='relay') then
          perform set_config('app.system_status_transition','off',true);
          return (select jsonb_build_object('status','assigned','reason','RELAY_PAIRED','needs_driver',false,'ride_id',r.id,'car_id',r.car_id,'starts_at',r.starts_at,'ends_at',r.ends_at)
                  from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=q.id limit 1);
        end if;
        update public.requests set status='waitlisted',status_reason='UNMET_NEEDS_DRIVER' where id=q.id;
        perform set_config('app.system_status_transition','off',true);
        return jsonb_build_object('status','waitlisted','reason','UNMET_NEEDS_DRIVER','needs_driver',true,'ride_id',ride_id,'car_id',c.id,'starts_at',v_start,'ends_at',v_end);
      exception when exclusion_violation or sqlstate 'P0410' or sqlstate 'P0411' then null;
      end;
    end loop;
  end if;
  update public.requests set status='waitlisted',status_reason='WAITLISTED_NO_CAR' where id=q.id;
  perform set_config('app.system_status_transition','off',true);
  return jsonb_build_object('status','waitlisted','reason','WAITLISTED_NO_CAR','needs_driver',false);
end $$;


ALTER FUNCTION "public"."reserve_live_one_way_slot"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_freed_offer"("p_offer_id" "uuid", "p_ranked_candidates" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_offer record;
  v_count int;
  v_first jsonb;
  v_ride_id uuid;
  v_cand jsonb;
begin
  select * into v_offer from public.freed_slot_offers where id = p_offer_id;
  if v_offer is null then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  if v_offer.status <> 'open' then raise exception 'offer_not_open' using errcode = 'P0001'; end if;

  v_count := jsonb_array_length(coalesce(p_ranked_candidates, '[]'));
  perform set_config('app.audit_reason', 'resolve_freed_offer', true);

  if v_count = 0 then
    update public.freed_slot_offers set status = 'closed', resolved_at = now() where id = p_offer_id;
  elsif v_count = 1 then
    v_first := p_ranked_candidates -> 0;
    insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
      driver_id, status, is_pinned, pin_reason, created_by)
    select r.department_id, r.week_start, v_offer.car_id, q.depart_at, q.return_at, r.origin_id, r.destination_id,
      q.requester_id, 'confirmed', true, 'FREED_SLOT_AUTO', q.requester_id
    from public.rides r, public.requests q
    where r.id = v_offer.cancelled_ride_id and q.id = (v_first ->> 'request_id')::uuid
    returning id into v_ride_id;

    insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
    values (v_ride_id, (v_first ->> 'request_id')::uuid, 'driver', 'both', 'keep');

    perform public.assert_car_chain(v_offer.car_id, v_offer.week_start);

    update public.requests set status = 'assigned', status_reason = 'FREED_SLOT_AUTO' where id = (v_first ->> 'request_id')::uuid;
    update public.freed_slot_offers set status = 'auto_assigned', resolved_at = now(),
      winning_request_id = (v_first ->> 'request_id')::uuid
    where id = p_offer_id;

    perform public.enqueue_notification((v_first ->> 'requester_id')::uuid, 'freed_slot_auto', v_offer.department_id, v_offer.week_start,
      '{}'::jsonb, jsonb_build_object('ride_id', v_ride_id), format('freed_slot_auto:%s', p_offer_id));
  else
    for v_cand in select * from jsonb_array_elements(p_ranked_candidates) loop
      insert into public.freed_slot_claims (offer_id, request_id, profile_id, status, offered_at)
      values (p_offer_id, (v_cand ->> 'request_id')::uuid, (v_cand ->> 'requester_id')::uuid, 'offered', now())
      on conflict (offer_id, request_id) do nothing;
      perform public.enqueue_notification((v_cand ->> 'requester_id')::uuid, 'freed_slot', v_offer.department_id, v_offer.week_start,
        '{}'::jsonb, jsonb_build_object('offer_id', p_offer_id),
        format('freed_slot:%s:%s', p_offer_id, v_cand ->> 'request_id'));
    end loop;
    update public.freed_slot_offers set status = 'pending_approval' where id = p_offer_id;
    perform public.enqueue_notification(s.profile_id, 'claim_contested', v_offer.department_id, v_offer.week_start,
      jsonb_build_object('count', v_count::text), jsonb_build_object('offer_id', p_offer_id), format('claim_contested:%s', p_offer_id))
    from public.sadranim_of(v_offer.department_id, v_offer.week_start) as s(profile_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."resolve_freed_offer"("p_offer_id" "uuid", "p_ranked_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_waitlist_group"("p_group_id" "uuid", "p_request_ids" "uuid"[], "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  g record;
  v_actor uuid := (select auth.uid());
  v_can_manage boolean;
begin
  select * into g from public.waitlist_groups where id = p_group_id for update;
  if g.id is null then raise exception 'waitlist_group_not_found' using errcode = 'P0001'; end if;

  v_can_manage := public.can_manage_week(g.department_id, g.week_start);
  if not v_can_manage and not exists (
    select 1 from public.waitlist_group_members wm
    where wm.group_id = g.id and wm.profile_id = v_actor and wm.chosen is null
  ) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  if g.status <> 'open' then raise exception 'waitlist_group_closed' using errcode = 'P0001'; end if;
  if p_expected_version is null or g.version is distinct from p_expected_version then
    perform public.raise_stale_version();
  end if;

  return public.settle_waitlist_group(p_group_id, p_request_ids, v_actor);
end;
$$;


ALTER FUNCTION "public"."resolve_waitlist_group"("p_group_id" "uuid", "p_request_ids" "uuid"[], "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_ride_change"("p_change_id" "uuid", "p_accept" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if exists(select 1 from public.ride_change_requests where id=p_change_id and is_planning) then raise exception 'not_authorized'; end if;
  perform public.respond_ride_change_before_planning(p_change_id,p_accept);
end $$;


ALTER FUNCTION "public"."respond_ride_change"("p_change_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_ride_change_before_planning"("p_change_id" "uuid", "p_accept" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare ch public.ride_change_requests%rowtype; r public.rides%rowtype; party record;
begin
  select * into ch from public.ride_change_requests where id=p_change_id for update;
  if not found then raise exception 'ride_change_not_found'; end if;
  if not public.is_approved() or not exists(select 1 from public.ride_change_parties where change_id=ch.id and profile_id=(select auth.uid())) then raise exception 'not_authorized'; end if;
  if ch.status<>'pending' then raise exception 'ride_change_not_pending'; end if;
  if ch.starts_at<=now() then update public.ride_change_requests set status='cancelled' where id=ch.id; return; end if;
  update public.ride_change_parties set accepted=p_accept,responded_at=now() where change_id=ch.id and profile_id=(select auth.uid());
  if not p_accept then update public.ride_change_requests set status='declined' where id=ch.id; return; end if;
  if exists(select 1 from public.ride_change_parties where change_id=ch.id and accepted is distinct from true) then return; end if;
  perform 1 from public.rides where id=ch.ride_id or id in(select ride_id from public.ride_change_parties where change_id=ch.id) order by id for update;
  select * into r from public.rides where id=ch.ride_id;
  if r.version<>ch.expected_version or r.status='cancelled' or exists(
    select 1 from public.ride_change_parties p join public.rides rd on rd.id=p.ride_id where p.change_id=ch.id and (rd.version<>p.expected_version or rd.status='cancelled')
  ) then update public.ride_change_requests set status='cancelled' where id=ch.id; return; end if;
  perform set_config('app.audit_reason','accepted_ride_change',true);
  perform set_config('app.system_status_transition','on',true);
  for party in select * from public.ride_change_parties where change_id=ch.id loop
    update public.rides set status='cancelled',cancelled_at=now(),cancelled_by=party.profile_id,cancel_reason='ACCEPTED_RIDE_CHANGE' where id=party.ride_id;
    update public.requests set status='cancelled',status_reason='RIDE_CANCELLED' where id in(select request_id from public.ride_requests where ride_id=party.ride_id);
    delete from public.ride_requests where ride_id=party.ride_id;
  end loop;
  update public.rides set car_id=ch.car_id,starts_at=ch.starts_at,ends_at=ch.ends_at,is_pinned=true,pin_reason='MEMBER_EDIT' where id=ch.ride_id;
  perform public.assert_ride_request_day(ch.ride_id);
  perform public.assert_ride_seats_fit(ch.ride_id);
  perform public.assert_car_chain(ch.car_id,ch.week_start);
  if r.car_id<>ch.car_id then perform public.assert_car_chain(r.car_id,ch.week_start); end if;
  update public.ride_change_requests set status='accepted' where id=ch.id;
  perform set_config('app.system_status_transition','off',true);
end $$;


ALTER FUNCTION "public"."respond_ride_change_before_planning"("p_change_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


