CREATE OR REPLACE FUNCTION "public"."rides_temp_car_never_relays"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_type public.car_type;
begin
  select c.type into v_type from public.cars c where c.id = new.car_id;
  if v_type = 'temporary' and new.origin_id <> new.destination_id then
    raise exception 'temporary_car_never_relays' using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."rides_temp_car_never_relays"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_temp_car_owner_only"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_type public.car_type; v_owner uuid;
begin
  select type, owner_id into v_type, v_owner from public.cars where id = new.car_id;
  if v_type = 'temporary' and new.driver_id is distinct from v_owner then
    raise exception 'temporary_car_owner_only' using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."rides_temp_car_owner_only"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rides_within_week"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='UPDATE' and new.starts_at=old.starts_at and new.ends_at=old.ends_at and new.week_start=old.week_start
    and new.car_id=old.car_id and (new.status=old.status or (new.status='draft' and old.status in ('confirmed','flagged'))) then return new;end if;
  if new.status='cancelled' then return new;end if;
  perform public.assert_same_day_window(new.starts_at,new.ends_at);
  if not (public.week_range(new.week_start) @> tstzrange(new.starts_at,new.ends_at,'[)')) then raise exception 'ride_outside_week';end if;
  return new;
end $$;


ALTER FUNCTION "public"."rides_within_week"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."route_label"("p_department_id" "uuid", "p_origin_id" "uuid", "p_origin_text" "text", "p_destination_id" "uuid", "p_destination_text" "text", "p_stops_text" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_home uuid;
  v_origin_name text;
  v_dest_name text;
  v_key text;
  v_has_origin boolean;
begin
  select home_destination_id into v_home from public.departments where id = p_department_id;

  select name into v_origin_name from public.destinations where id = p_origin_id;
  v_origin_name := coalesce(v_origin_name, p_origin_text);

  select name into v_dest_name from public.destinations where id = p_destination_id;
  v_dest_name := coalesce(v_dest_name, p_destination_text);

  v_has_origin := not (p_origin_id is null or p_origin_id = v_home);
  v_key := case
    when v_has_origin and p_stops_text is not null then 'route.via'
    when v_has_origin then 'route.from_to'
    when p_stops_text is not null then 'route.to_via'
    else 'route.to'
  end;

  return public.render_notification_text(
    (select body from public.text_fragments where key = v_key),
    jsonb_build_object('origin', coalesce(v_origin_name, ''), 'destination', coalesce(v_dest_name, ''),
      'stops', coalesce(p_stops_text, '')));
end;
$$;


ALTER FUNCTION "public"."route_label"("p_department_id" "uuid", "p_origin_id" "uuid", "p_origin_text" "text", "p_destination_id" "uuid", "p_destination_text" "text", "p_stops_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sadran_assignments_require_roster_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists(select 1 from public.department_members dm join public.profiles p on p.id=dm.profile_id
    where dm.department_id=new.department_id and dm.profile_id=new.profile_id
      and dm.removed_at is null and p.approval_status='approved'
      and (new.week_start is not null or dm.role='sadran')) then
    raise exception 'sadran_assignment_requires_roster_role' using errcode='P0001';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."sadran_assignments_require_roster_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sadran_contact_of"("_department_id" "uuid", "_week_start" "date") RETURNS TABLE("person_id" "uuid", "full_name" "text", "phone" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not (public.is_approved() and public.member_of(_department_id)) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  return query
    select p.id, p.full_name, p.phone
    from public.sadranim_of(_department_id, _week_start) s(profile_id)
    join public.profiles p on p.id = s.profile_id;
end;
$$;


ALTER FUNCTION "public"."sadran_contact_of"("_department_id" "uuid", "_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sadranim_of"("_dept" "uuid", "_week" "date") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with explicit as (
    select sa.profile_id from public.sadran_assignments sa
    join public.department_members dm on dm.department_id=sa.department_id and dm.profile_id=sa.profile_id
    join public.profiles p on p.id=sa.profile_id
    where sa.department_id=_dept and sa.week_start=_week
      and dm.removed_at is null and p.approval_status='approved'
  ), pool as (
    select dm.profile_id,row_number() over(order by dm.profile_id)-1 position,count(*) over() size
    from public.department_members dm join public.profiles p on p.id=dm.profile_id
    where dm.department_id=_dept and dm.role='sadran' and dm.removed_at is null and p.approval_status='approved'
  )
  select profile_id from explicit
  union all
  select profile_id from pool where not exists(select 1 from explicit)
    and position=mod(mod((_week-date '1970-01-04')/7,size)+size,size);
$$;


ALTER FUNCTION "public"."sadranim_of"("_dept" "uuid", "_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_request_template"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  q public.requests%rowtype;
  v_template_id uuid;
  v_depart_dow smallint;
  v_depart_time time;
  v_return_dow smallint;
  v_return_time time;
  v_child_ids uuid[];
  v_companion_ids uuid[];
  v_stops jsonb;
begin
  if not public.is_approved() then raise exception 'not_authorized' using errcode = 'P0001'; end if;

  select * into q from public.requests where id = p_request_id for update;
  if q is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  if q.requester_id <> (select auth.uid()) then raise exception 'not_authorized' using errcode = 'P0001'; end if;

  if q.depart_at is not null then
    v_depart_dow := extract(dow from (q.depart_at at time zone 'Asia/Jerusalem'));
    v_depart_time := (q.depart_at at time zone 'Asia/Jerusalem')::time;
  end if;
  if q.return_at is not null then
    v_return_dow := extract(dow from (q.return_at at time zone 'Asia/Jerusalem'));
    v_return_time := (q.return_at at time zone 'Asia/Jerusalem')::time;
  end if;

  select coalesce(array_agg(child_id), '{}') into v_child_ids
    from public.request_children where request_id = q.id;
  select coalesce(array_agg(profile_id), '{}') into v_companion_ids
    from public.request_companions where request_id = q.id;
  select coalesce(jsonb_agg(jsonb_build_object(
      'leg', s.leg, 'position', s."position", 'place_id', s.place_id, 'place_text', s.place_text
    ) order by s.leg, s."position"), '[]'::jsonb) into v_stops
    from public.request_stops s where s.request_id = q.id;

  v_template_id := q.template_id;
  if v_template_id is null then
    select id into v_template_id from public.request_templates where source_request_id = q.id;
  end if;

  if v_template_id is not null then
    update public.request_templates set
      destination_id = q.destination_id, destination_text = q.destination_text,
      origin_id = q.origin_id, origin_text = q.origin_text, trip_type = q.trip_type,
      ride_type_id = q.ride_type_id, trip_shape = q.trip_shape,
      depart_dow = v_depart_dow, depart_time = v_depart_time,
      return_dow = v_return_dow, return_time = v_return_time,
      one_way_car_mode = q.one_way_car_mode, needs_car_at_destination = q.needs_car_at_destination,
      adults = q.adults, child_seats = q.child_seats, boosters = q.boosters, has_luggage = q.has_luggage,
      flex_depart_early = q.flex_depart_early, flex_depart_late = q.flex_depart_late,
      flex_return_early = q.flex_return_early, flex_return_late = q.flex_return_late,
      notes = q.notes, preferred_car_id = q.preferred_car_id,
      ride_description = q.ride_description, guest_passenger_names = q.guest_passenger_names,
      companion_ids = v_companion_ids, child_ids = v_child_ids, stops = v_stops,
      source_request_id = q.id, is_active = true, stopped_at = null
    where id = v_template_id;
  else
    insert into public.request_templates (
      requester_id, department_id, destination_id, destination_text, origin_id, origin_text, trip_type,
      ride_type_id, trip_shape,
      depart_dow, depart_time, return_dow, return_time, one_way_car_mode, needs_car_at_destination,
      adults, child_seats, boosters, has_luggage,
      flex_depart_early, flex_depart_late, flex_return_early, flex_return_late,
      notes, preferred_car_id, ride_description, guest_passenger_names, companion_ids, child_ids, stops,
      source_request_id
    ) values (
      q.requester_id, q.department_id, q.destination_id, q.destination_text, q.origin_id, q.origin_text, q.trip_type,
      q.ride_type_id, q.trip_shape,
      v_depart_dow, v_depart_time, v_return_dow, v_return_time, q.one_way_car_mode, q.needs_car_at_destination,
      q.adults, q.child_seats, q.boosters, q.has_luggage,
      q.flex_depart_early, q.flex_depart_late, q.flex_return_early, q.flex_return_late,
      q.notes, q.preferred_car_id, q.ride_description, q.guest_passenger_names, v_companion_ids, v_child_ids, v_stops,
      q.id
    ) returning id into v_template_id;
  end if;

  update public.requests set template_id = v_template_id where id = q.id;
  return v_template_id;
end;
$$;


ALTER FUNCTION "public"."save_request_template"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_due_reminders"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_count int := 0; v_week record; v_settings record; v_hours int;
begin
  perform public.assert_not_direct_rpc('send_due_reminders');
  for v_week in select * from public.weeks where phase = 'open' loop
    select * into v_settings from public.department_settings where department_id = v_week.department_id;
    foreach v_hours in array v_settings.closing_reminder_hours loop
      if p_now >= v_week.close_at - make_interval(hours => v_hours)
         and p_now < v_week.close_at - make_interval(hours => v_hours) + interval '15 min' then
        perform public.enqueue_notification(dm.profile_id, 'window_closing', v_week.department_id, v_week.week_start,
          jsonb_build_object('count', v_hours::text), '{}'::jsonb,
          format('window_closing:%s:%s:%s', v_week.department_id, v_week.week_start, v_hours))
        from public.department_members dm
        where dm.department_id = v_week.department_id and dm.removed_at is null
          and not exists (
            select 1 from public.requests q where q.department_id = v_week.department_id and q.week_start = v_week.week_start
              and q.requester_id = dm.profile_id and q.status <> 'withdrawn'
          );
        v_count := v_count + 1;
      end if;
    end loop;
  end loop;

  for v_week in select * from public.weeks where phase = 'solving' and publish_reminder_sent_at is null loop
    select * into v_settings from public.department_settings where department_id = v_week.department_id;
    if p_now >= ((v_week.week_start - 7 + v_settings.publish_dow)::timestamp + v_settings.publish_time) at time zone 'Asia/Jerusalem' then
      perform public.enqueue_notification(s.profile_id, 'publish_reminder', v_week.department_id, v_week.week_start,
        '{}'::jsonb, '{}'::jsonb, format('publish_reminder:%s:%s', v_week.department_id, v_week.week_start))
      from public.sadranim_of(v_week.department_id, v_week.week_start) as s(profile_id);
      update public.weeks set publish_reminder_sent_at = p_now
      where department_id = v_week.department_id and week_start = v_week.week_start;
      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."send_due_reminders"("p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_proposal"("p_proposal_id" "uuid", "p_sent_via" "public"."notification_channel"[] DEFAULT '{}'::"public"."notification_channel"[], "p_replace_proposal_id" "uuid" DEFAULT NULL::"uuid", "p_replace_expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_prop public.proposals%rowtype;
  v_previous public.proposals%rowtype;
  v_request public.requests%rowtype;
  v_request_id uuid;
  v_token text;
  v_proposal_token text;
  v_party_tokens jsonb:='{}';
  v_party record;
begin
  select request_id into v_request_id from public.proposals where id=p_proposal_id;
  if v_request_id is null then raise exception 'proposal_not_found'; end if;
  -- This order is also used by answer_proposal: request, proposals, then parties.
  select * into v_request from public.requests where id=v_request_id for update;
  perform 1 from public.proposals where request_id=v_request_id order by id for update;
  select * into v_prop from public.proposals where id=p_proposal_id;
  if not public.can_manage_week(v_prop.department_id,v_prop.week_start) and (
    v_prop.created_via<>'ask_to_join' or not public.member_of(v_prop.department_id) or v_request.requester_id<>(select auth.uid())) then
    raise exception 'not_authorized';
  end if;
  if v_prop.status<>'draft' then raise exception 'proposal_not_draft'; end if;
  -- Owner decision (20260910098000): the day may have gone public between draft and send
  -- (create_proposal() guards at creation time, but a draft sitting unsent is never touched
  -- by expire_proposals(), which only expires status='sent' rows) — re-check at send time.
  -- Same "ask to join" exemption as create_proposal().
  if v_prop.created_via <> 'ask_to_join'
     and public.is_day_public(v_prop.department_id, v_prop.week_start,
       (coalesce(v_request.depart_at, v_request.return_at) at time zone 'Asia/Jerusalem')::date)
  then
    raise exception 'proposal_day_public' using errcode = 'P0001';
  end if;
  select * into v_previous from public.proposals where request_id=v_request_id and status='sent';
  if p_replace_proposal_id is null then
    if v_previous.id is not null then raise exception 'proposal_already_sent'; end if;
    if p_replace_expected_version is not null then perform public.raise_stale_version(); end if;
  else
    -- Replacing another person's offer is a coordinator action, even for ask-to-join drafts.
    if not public.can_manage_week(v_prop.department_id,v_prop.week_start) then raise exception 'not_authorized'; end if;
    if v_previous.id is distinct from p_replace_proposal_id or v_previous.version is distinct from p_replace_expected_version
      or v_request.status<>'proposed' then
      perform public.raise_stale_version();
    end if;
    if v_previous.answered_at is not null or exists(select 1 from public.proposal_parties where proposal_id=v_previous.id and response<>'pending') then
      raise exception 'proposal_replacement_answered';
    end if;
  end if;
  perform set_config('app.audit_reason','send_proposal',true);
  perform set_config('app.system_status_transition','on',true);
  if v_previous.id is not null then
    -- Expiring restores the pre-offer request state. Carry it into the replacement,
    -- whose draft may have been created while the request was already proposed.
    update public.proposals set status='expired' where id=v_previous.id;
    v_request.status:=v_previous.previous_status;
  end if;
  v_proposal_token:=public.generate_token();
  update public.proposals set previous_status=v_request.status,
    token_hash=encode(digest(v_proposal_token,'sha256'),'hex'),status='sent',sent_at=now(),sent_via=p_sent_via
    where id=p_proposal_id;
  perform set_config('app.system_status_transition','off',true);
  for v_party in select id,profile_id from public.proposal_parties where proposal_id=p_proposal_id order by id for update loop
    v_token:=public.generate_token();
    update public.proposal_parties set token_hash=encode(digest(v_token,'sha256'),'hex') where id=v_party.id;
    v_party_tokens:=v_party_tokens||jsonb_build_object(v_party.profile_id::text,v_token);
  end loop;
  for v_party in select profile_id from public.proposal_parties where proposal_id=p_proposal_id loop
    perform public.enqueue_notification(v_party.profile_id,'proposal_received',v_prop.department_id,v_prop.week_start,
      jsonb_build_object('newDepart',to_char((v_prop.payload->>'starts_at')::timestamptz at time zone 'Asia/Jerusalem','HH24:MI'),
        'newReturn',to_char((v_prop.payload->>'ends_at')::timestamptz at time zone 'Asia/Jerusalem','HH24:MI')),
      jsonb_build_object('proposal_id',p_proposal_id,'url','/p/'||(v_party_tokens->>v_party.profile_id::text)),
      format('proposal_received:%s:%s',p_proposal_id,v_party.profile_id));
  end loop;
  return jsonb_build_object('proposal_token',v_proposal_token,'party_tokens',v_party_tokens);
end $$;


ALTER FUNCTION "public"."send_proposal"("p_proposal_id" "uuid", "p_sent_via" "public"."notification_channel"[], "p_replace_proposal_id" "uuid", "p_replace_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_freed_slot_opt_out"("p_request_id" "uuid", "p_opt_out" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_req record;
begin
  select * into v_req from public.requests where id = p_request_id;
  if v_req is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  if v_req.requester_id <> (select auth.uid()) and not public.can_manage_week(v_req.department_id, v_req.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'set_freed_slot_opt_out', true);
  update public.requests set freed_slot_opt_out = p_opt_out where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."set_freed_slot_opt_out"("p_request_id" "uuid", "p_opt_out" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_manual_boost"("p_request_id" "uuid", "p_value" numeric, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_req record;
begin
  select * into v_req from public.requests where id = p_request_id;
  if v_req is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_req.department_id, v_req.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if p_value <> 0 and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'manual_boost_requires_reason' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'set_manual_boost', true);
  update public.requests set manual_boost = p_value, manual_boost_reason = p_reason where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."set_manual_boost"("p_request_id" "uuid", "p_value" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_default_origin"("p_department_id" "uuid", "p_origin_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.member_of(p_department_id) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if p_origin_id is not null and not exists (
    select 1 from public.destinations d where d.id = p_origin_id and d.department_id = p_department_id and d.is_approved
  ) then
    raise exception 'invalid_origin' using errcode = 'P0001';
  end if;
  update public.department_members
    set default_origin_id = p_origin_id
    where department_id = p_department_id and profile_id = (select auth.uid()) and removed_at is null;
  if not found then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "public"."set_my_default_origin"("p_department_id" "uuid", "p_origin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_policy_active"("p_policy_id" "uuid", "p_is_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.policies p where p.id = p_policy_id and public.can_manage_operations(p.department_id)) then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  perform set_config('app.audit_reason', 'set_policy_active', true);
  update public.policies set is_active = p_is_active where id = p_policy_id;
end;
$$;


