CREATE OR REPLACE FUNCTION "public"."set_request_children"("p_request_id" "uuid", "p_child_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  q public.requests%rowtype;
  v_year int;
  v_old_adult_children int := 0;
  v_old_child_seat_children int := 0;
  v_new_adult_children int := 0;
  v_new_child_seat_children int := 0;
  v_legacy_adults int := 1;
  v_legacy_child_seats int := 0;
begin
  select * into q from public.requests where id = p_request_id for update;
  if not found then raise exception 'request_not_found'; end if;
  if q.requester_id <> auth.uid() and not public.can_manage_week(q.department_id, q.week_start) then
    raise exception 'not_authorized';
  end if;
  if coalesce(cardinality(p_child_ids), 0) is distinct from (
    select count(distinct child_id) from unnest(coalesce(p_child_ids, '{}'::uuid[])) as u(child_id)
  ) then
    raise exception 'duplicate_child';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_child_ids, '{}'::uuid[])) as u(child_id)
    left join public.children c on c.id = u.child_id and c.department_id = q.department_id
    where c.id is null
  ) then raise exception 'invalid_child'; end if;

  v_year := extract(year from coalesce(q.depart_at, now()) at time zone 'Asia/Jerusalem')::int;
  select
    count(*) filter (where c.birth_year is not null and v_year - c.birth_year >= 8),
    count(*) filter (where c.birth_year is null or v_year - c.birth_year < 8)
  into v_old_adult_children, v_old_child_seat_children
  from public.request_children rc join public.children c on c.id = rc.child_id
  where rc.request_id = q.id;

  select
    count(*) filter (where c.birth_year is not null and v_year - c.birth_year >= 8),
    count(*) filter (where c.birth_year is null or v_year - c.birth_year < 8)
  into v_new_adult_children, v_new_child_seat_children
  from public.children c where c.id = any(coalesce(p_child_ids, '{}'::uuid[]));

  v_legacy_adults := greatest(1, q.adults - v_old_adult_children);
  v_legacy_child_seats := greatest(0, q.child_seats - v_old_child_seat_children);

  delete from public.request_children where request_id = q.id;
  insert into public.request_children(request_id, child_id)
    select q.id, child_id from unnest(coalesce(p_child_ids, '{}'::uuid[])) as u(child_id);

  update public.requests
  set adults = v_legacy_adults + v_new_adult_children,
      child_seats = v_legacy_child_seats + v_new_child_seat_children,
      updated_at = now()
  where id = q.id;
end;
$$;


ALTER FUNCTION "public"."set_request_children"("p_request_id" "uuid", "p_child_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_request_companions"("p_request_id" "uuid", "p_profile_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare q public.requests%rowtype;
begin
  select * into q from public.requests where id = p_request_id for update;
  if not found then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  if q.requester_id <> (select auth.uid()) and not public.can_manage_week(q.department_id, q.week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if q.status in ('withdrawn', 'cancelled') then
    raise exception 'request_not_editable' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'set_request_companions', true);
  delete from public.request_companions
  where request_id = p_request_id and not (profile_id = any(coalesce(p_profile_ids, '{}'::uuid[])));
  insert into public.request_companions (request_id, profile_id)
  select p_request_id, u.profile_id
  from unnest(coalesce(p_profile_ids, '{}'::uuid[])) as u(profile_id)
  on conflict (request_id, profile_id) do nothing;
end $$;


ALTER FUNCTION "public"."set_request_companions"("p_request_id" "uuid", "p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_request_trip_type"("p_request_id" "uuid", "p_trip_type" "public"."trip_type", "p_expected_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  q public.requests%rowtype; v_actor uuid := (select auth.uid());
  v_shape public.trip_shape; v_needs boolean; v_mode public.leg_car_mode; v_dep timestamptz; v_ret timestamptz;
  v_car uuid; v_ride uuid; v_old record; v_old_cars uuid[] := '{}'; v_old_car uuid; v_prev_sys text;
  v_status public.request_status; v_placed boolean := false; v_driver_mode public.leg_car_mode;
  v_kept timestamptz; v_defaulted timestamptz; v_flex_any boolean := false;
begin
  select * into q from public.requests where id = p_request_id for update;
  if q.id is null then raise exception 'request_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(q.department_id, q.week_start) then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  if exists (select 1 from public.weeks w where w.department_id = q.department_id and w.week_start = q.week_start and w.phase = 'archived') then
    raise exception 'week_archived' using errcode = 'P0001';
  end if;
  if p_expected_version is null or q.version <> p_expected_version then perform public.raise_stale_version(); end if;
  if q.series_id is not null then raise exception 'series_edit_not_supported' using errcode = 'MDR02'; end if;
  if q.status in ('draft', 'cancelled', 'withdrawn', 'denied', 'external') then
    raise exception 'request_not_editable' using errcode = 'P0001';
  end if;
  if q.trip_type = p_trip_type then
    return jsonb_build_object('status', q.status, 'changed', false);
  end if;

  select case when p.does_not_drive then 'passenger'::public.leg_car_mode else 'relay'::public.leg_car_mode end into v_driver_mode
  from public.profiles p where p.id = q.requester_id;

  v_dep := q.depart_at; v_ret := q.return_at; v_kept := q.kept_return_at;
  if p_trip_type = 'round_trip' then
    v_ret := coalesce(v_ret, q.kept_return_at); v_kept := null;
    if v_dep is null then raise exception 'trip_type_needs_return' using errcode = 'P0001'; end if;
    -- REQ §13.98: no known return time -> about two hours after arrival (departure + the out
    -- route + 2h, nearest quarter hour, never past the day's end) with return flexibility "any
    -- time that day", so the Sadran can move it without asking anyone.
    if v_ret is null then
      v_ret := to_timestamp(round(extract(epoch from
        v_dep + make_interval(mins => coalesce(public.request_leg_route_minutes(q.id, 'out'), 30)) + interval '2 hours') / 900) * 900);
      if (v_ret at time zone 'Asia/Jerusalem')::date <> (v_dep at time zone 'Asia/Jerusalem')::date then
        v_ret := (((v_dep at time zone 'Asia/Jerusalem')::date + time '23:59') at time zone 'Asia/Jerusalem');
      end if;
      if v_ret <= v_dep then raise exception 'trip_type_needs_return' using errcode = 'P0001'; end if;
      v_defaulted := v_ret; v_flex_any := true;
    end if;
    v_shape := 'round_trip'; v_needs := true; v_mode := null;
  elsif p_trip_type = 'one_way' then
    v_kept := coalesce(v_ret, q.kept_return_at); v_dep := coalesce(v_dep, v_ret); v_ret := null;
    v_shape := 'one_way_to'; v_needs := true; v_mode := 'relay';
  else
    v_needs := false;
    if v_ret is not null then v_kept := null; end if;
    if v_ret is not null and v_dep is not null then v_shape := 'round_trip'; v_mode := null;
    elsif v_ret is not null then v_shape := 'one_way_from'; v_mode := coalesce(q.one_way_car_mode, v_driver_mode);
    else v_shape := 'one_way_to'; v_mode := coalesce(q.one_way_car_mode, v_driver_mode);
    end if;
  end if;
  if p_trip_type <> 'drop_off' and public.eligible_leg_driver(q.id) is null then
    raise exception 'non_driver_needs_drop_off' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'set_request_trip_type', true);
  v_prev_sys := coalesce(nullif(current_setting('app.system_status_transition', true), ''), 'off');
  perform set_config('app.system_status_transition', 'on', true);

  update public.requests set trip_type = p_trip_type, trip_shape = v_shape, needs_car_at_destination = v_needs,
    one_way_car_mode = v_mode, depart_at = v_dep, return_at = v_ret, kept_return_at = v_kept,
    flex_return_early = case when v_flex_any then interval '1 day' else flex_return_early end,
    flex_return_late = case when v_flex_any then interval '1 day' else flex_return_late end
  where id = q.id;
  -- REQ §13.97: return-leg stops are kept (inactive while there is no return), never deleted.

  -- Re-place on the car the request was on (earliest live ride).
  select r.car_id into v_car from public.rides r join public.ride_requests rr on rr.ride_id = r.id
  where rr.request_id = q.id and r.status <> 'cancelled' order by r.starts_at, r.id limit 1;
  if v_car is not null then
    begin
      v_ride := public.place_request_on_car(q.id, v_car, true, v_actor, null, v_dep, v_ret, 'TRIP_TYPE_CHANGED');
      v_placed := true;
    exception when sqlstate 'P0001' or sqlstate '23P01' or sqlstate '23514' then
      v_placed := false; v_ride := null;
    end;
    if not v_placed then
      for v_old in select rd.* from public.rides rd join public.ride_requests rr on rr.ride_id = rd.id
        where rr.request_id = q.id and rd.status <> 'cancelled' order by rd.id for update of rd loop
        if not exists (select 1 from public.ride_requests where ride_id = v_old.id and request_id <> q.id) then
          update public.rides set status = 'cancelled', cancelled_at = now(), cancelled_by = coalesce(v_actor, q.requester_id),
            cancel_reason = 'UNMET_TRIP_TYPE_CHANGED' where id = v_old.id;
        end if;
        delete from public.ride_requests where ride_id = v_old.id and request_id = q.id;
        v_old_cars := v_old_cars || v_old.car_id;
      end loop;
      update public.requests set status = 'submitted', status_reason = 'UNMET_TRIP_TYPE_CHANGED' where id = q.id;
      foreach v_old_car in array v_old_cars loop
        perform public.assert_car_chain(v_old_car, q.week_start);
      end loop;
    end if;
  end if;
  perform set_config('app.system_status_transition', v_prev_sys, true);

  if q.requester_id is distinct from v_actor then
    perform public.enqueue_notification(q.requester_id, 'outcome_changed', q.department_id, q.week_start,
      '{}'::jsonb, jsonb_build_object('variant', 'trip_type_changed', 'request_id', q.id),
      format('trip_type_changed:%s:%s', q.id, q.version));
  end if;

  select status into v_status from public.requests where id = q.id;
  -- REQ §13.97: tell the caller when a kept return time came back (the board's toast says so).
  return jsonb_strip_nulls(jsonb_build_object('status', v_status, 'ride_id', v_ride, 'changed', true,
    'restored_return_at', case when q.return_at is null and v_ret is not null and v_defaulted is null then v_ret end,
    'defaulted_return_at', v_defaulted));
end;
$$;


ALTER FUNCTION "public"."set_request_trip_type"("p_request_id" "uuid", "p_trip_type" "public"."trip_type", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_ride_passengers"("p_ride_id" "uuid", "p_expected_version" integer, "p_passengers" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_actor uuid := (select auth.uid());
  v_actor_name text;
  v_item jsonb;
  v_person_id uuid;
  v_child_id uuid;
  v_display_name text;
  v_seat_kind text;
  v_old_person_ids uuid[];
  v_new_person_ids uuid[] := '{}';
  v_added_person_ids uuid[];
  v_existing_a int; v_existing_c int; v_existing_b int;
  v_new_a int := 0; v_new_c int := 0; v_new_b int := 0;
  v_chauffeur_bonus int;
  v_new_version int;
begin
  select * into v_ride from public.rides where id = p_ride_id for update;
  if not found or v_ride.status = 'cancelled' then raise exception 'ride_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_ride.department_id, v_ride.week_start) and v_ride.driver_id is distinct from v_actor then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  if p_expected_version is null or v_ride.version <> p_expected_version then
    perform public.raise_stale_version();
  end if;
  if exists (select 1 from public.weeks where department_id = v_ride.department_id and week_start = v_ride.week_start and phase = 'archived') then
    raise exception 'week_archived' using errcode = 'P0001';
  end if;

  select array_agg(person_id) filter (where person_id is not null) into v_old_person_ids
  from public.ride_passengers where ride_id = p_ride_id;

  -- Validate every row and total the new seat load before writing anything.
  for v_item in select * from jsonb_array_elements(coalesce(p_passengers, '[]'::jsonb))
  loop
    v_person_id := nullif(v_item ->> 'person_id', '')::uuid;
    v_child_id := nullif(v_item ->> 'child_id', '')::uuid;
    v_display_name := nullif(trim(coalesce(v_item ->> 'display_name', '')), '');
    v_seat_kind := v_item ->> 'seat_kind';
    if v_person_id is not null and v_child_id is not null then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_display_name is null then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_person_id is not null and not exists (
      select 1 from public.profiles p join public.department_members dm on dm.profile_id = p.id
      where p.id = v_person_id and p.approval_status = 'approved'
        and dm.department_id = v_ride.department_id and dm.removed_at is null
    ) then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_child_id is not null and not exists (
      select 1 from public.children c where c.id = v_child_id and c.department_id = v_ride.department_id
    ) then
      raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end if;
    if v_person_id is not null then
      v_new_person_ids := v_new_person_ids || v_person_id;
    end if;
    case v_seat_kind
      when 'adult' then v_new_a := v_new_a + 1;
      when 'child_seat' then v_new_c := v_new_c + 1;
      when 'booster' then v_new_b := v_new_b + 1;
      else raise exception 'invalid_ride_passenger' using errcode = 'P0001';
    end case;
  end loop;

  if cardinality(v_new_person_ids) <> (select count(distinct x) from unnest(v_new_person_ids) x) then
    raise exception 'invalid_ride_passenger' using errcode = 'P0001';
  end if;

  -- Seat capacity: car seats minus the ride's served `ride_requests` load (with the same
  -- driver-has-no-request-of-their-own bonus `assert_ride_seats_fit` applies) minus these rows.
  select coalesce(sum(q.adults), 0), coalesce(sum(q.child_seats), 0), coalesce(sum(q.boosters), 0)
    into v_existing_a, v_existing_c, v_existing_b
  from public.ride_requests rr join public.requests q on q.id = rr.request_id
  where rr.ride_id = p_ride_id;

  v_chauffeur_bonus := case when v_ride.driver_id is not null
    and not exists (select 1 from public.ride_requests rr where rr.ride_id = p_ride_id and rr.role = 'driver')
    then 1 else 0 end;

  if not public.car_fits(v_ride.car_id, v_existing_a + v_chauffeur_bonus + v_new_a, v_existing_c + v_new_c, v_existing_b + v_new_b) then
    raise exception 'ride_seats_exceeded' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'set_ride_passengers', true);

  delete from public.ride_passengers where ride_id = p_ride_id;
  for v_item in select * from jsonb_array_elements(coalesce(p_passengers, '[]'::jsonb))
  loop
    insert into public.ride_passengers (ride_id, department_id, week_start, person_id, child_id, display_name, seat_kind, added_by)
    values (p_ride_id, v_ride.department_id, v_ride.week_start,
      nullif(v_item ->> 'person_id', '')::uuid, nullif(v_item ->> 'child_id', '')::uuid,
      trim(v_item ->> 'display_name'), v_item ->> 'seat_kind', v_actor);
  end loop;

  -- Optimistic concurrency: any update fires `bump_version()` (20260907090800_rides.sql).
  update public.rides set updated_at = now() where id = p_ride_id
  returning version into v_new_version;

  select array_agg(x) into v_added_person_ids
  from unnest(v_new_person_ids) x
  where x <> all (coalesce(v_old_person_ids, '{}'::uuid[])) and x is distinct from v_actor;

  if v_added_person_ids is not null then
    select full_name into v_actor_name from public.profiles where id = v_actor;
    for v_person_id in select unnest(v_added_person_ids) loop
      perform public.enqueue_notification(v_person_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
        jsonb_build_object('byName', coalesce(v_actor_name, '')),
        jsonb_build_object('variant', 'reservation_added', 'ride_id', p_ride_id),
        format('reservation_added:%s:%s:%s', p_ride_id, v_new_version, v_person_id));
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_ride_passengers"("p_ride_id" "uuid", "p_expected_version" integer, "p_passengers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_week_close_at"("p_department_id" "uuid", "p_week_start" "date", "p_close_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  w public.weeks%rowtype;
  v_new_phase public.week_phase;
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized';
  end if;

  select * into w from public.weeks where department_id = p_department_id and week_start = p_week_start for update;
  if not found or w.phase not in ('open', 'solving') then
    raise exception 'week_close_not_editable';
  end if;

  if p_close_at is null or p_close_at <= w.open_at or p_close_at > w.publish_at or not public.is_quarter_hour(p_close_at) then
    raise exception 'week_close_out_of_range';
  end if;

  v_new_phase := w.phase;
  if w.phase = 'solving' and p_close_at > now() then
    v_new_phase := 'open';
  elsif w.phase = 'open' and p_close_at <= now() then
    v_new_phase := 'solving';
  end if;

  perform set_config('app.audit_reason', 'set_week_close_at', true);
  update public.weeks set close_at = p_close_at, phase = v_new_phase
    where department_id = p_department_id and week_start = p_week_start;

  -- Same transition, same event and recipients as advance_week_phases()'s own open->solving
  -- branch — a fresh dedupe key (folding in the new close_at) so a later *natural* close
  -- (after the Sadran reopens and it elapses again via app.tick()) is never silently
  -- deduped against this manual one.
  if w.phase = 'open' and v_new_phase = 'solving' then
    perform public.enqueue_notification(s.profile_id, 'window_closed_solve_now', p_department_id, p_week_start,
      '{}'::jsonb, '{}'::jsonb, format('window_closed_solve_now:%s:%s:%s', p_department_id, p_week_start, p_close_at))
    from public.sadranim_of(p_department_id, p_week_start) as s(profile_id);
  end if;

  -- notification_context() reads weeks.close_at fresh, so the auto-computed {{weekLabel}}
  -- already reflects the row we just updated; closeDay/closeTime are explicit here because
  -- the auto {{closeTime}} is "DD/MM HH24:MI" (other window events), not the bare "HH:MM"
  -- this copy wants.
  perform public.enqueue_notification(dm.profile_id, 'window_changed', p_department_id, p_week_start,
    jsonb_build_object(
      'closeDay', public.weekday_short_label((p_close_at at time zone 'Asia/Jerusalem')::date),
      'closeTime', to_char(p_close_at at time zone 'Asia/Jerusalem', 'HH24:MI')
    ),
    '{}'::jsonb,
    format('window_changed:%s:%s:%s', p_department_id, p_week_start, p_close_at))
  from public.department_members dm
  join public.profiles p on p.id = dm.profile_id
  where dm.department_id = p_department_id and dm.removed_at is null and p.approval_status = 'approved';
end;
$$;


ALTER FUNCTION "public"."set_week_close_at"("p_department_id" "uuid", "p_week_start" "date", "p_close_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_week_phase"("p_department_id" "uuid", "p_week_start" "date", "p_phase" "public"."week_phase") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.can_manage_week(p_department_id, p_week_start) then
    raise exception 'not_authorized' using errcode = 'P0001';
  end if;
  perform set_config('app.audit_reason', 'set_week_phase', true);
  update public.weeks set phase = p_phase where department_id = p_department_id and week_start = p_week_start;

  if p_phase = 'solving' then
    perform public.enqueue_notification(s.profile_id, 'window_closed_solve_now', p_department_id, p_week_start,
      '{}'::jsonb, '{}'::jsonb, format('window_closed_solve_now:%s:%s', p_department_id, p_week_start))
    from public.sadranim_of(p_department_id, p_week_start) as s(profile_id);
  end if;
end;
$$;


ALTER FUNCTION "public"."set_week_phase"("p_department_id" "uuid", "p_week_start" "date", "p_phase" "public"."week_phase") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_waitlist_cluster"("_department_id" "uuid", "_week_start" "date", "_day" "date", "_request_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_result jsonb; v_all_assigned boolean := true; v_group uuid;
begin
  if coalesce(cardinality(_request_ids), 0) = 0 then return 0; end if;

  if cardinality(_request_ids) = 1 then
    -- A lone request keeps today's behavior. try_auto_approve() can still raise
    -- (assert_car_chain, seat/maintenance guards); one bad request must not abort a whole
    -- publication, so it falls back to the ordinary "no car" waitlist outcome.
    begin
      v_result := public.try_auto_approve(_request_ids[1]);
    exception when others then
      perform set_config('app.system_status_transition', 'on', true);
      perform set_config('app.audit_reason', 'form_waitlist_groups:no_car', true);
      update public.requests set status = 'waitlisted', status_reason = 'WAITLISTED_NO_CAR'
      where id = _request_ids[1] and status = 'submitted';
      perform set_config('app.system_status_transition', 'off', true);
    end;
    return 0;
  end if;

  begin
    foreach v_id in array _request_ids loop
      v_result := public.try_auto_approve(v_id);
      if coalesce(v_result ->> 'status', '') <> 'assigned' then
        -- Deliberate: unwinds every placement made inside this subtransaction.
        raise exception 'waitlist_cluster_rollback' using errcode = 'P0001';
      end if;
    end loop;
  exception when others then
    v_all_assigned := false;
  end;

  if v_all_assigned then return 0; end if;

  v_group := public.create_waitlist_group(_department_id, _week_start, _day, _request_ids);
  if v_group is null then return 0; end if;
  perform public.notify_waitlist_contested(v_group);
  return 1;
end;
$$;


ALTER FUNCTION "public"."settle_waitlist_cluster"("_department_id" "uuid", "_week_start" "date", "_day" "date", "_request_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_waitlist_group"("p_group_id" "uuid", "p_request_ids" "uuid"[], "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  g record;
  v_driver_request uuid;
  v_driver_profile uuid;
  v_driver_name text;
  v_preferred uuid;
  v_home uuid;
  v_turnaround interval;
  v_car public.cars%rowtype;
  v_starts timestamptz;
  v_ends timestamptz;
  v_adults int; v_child_seats int; v_boosters int;
  v_ride uuid;
  v_id uuid;
  v_chosen_names text;
  v_day text; v_depart text; v_return text;
  m record; v_sadran uuid; v_variant text;
begin
  select * into g from public.waitlist_groups where id = p_group_id for update;
  if g.id is null then raise exception 'waitlist_group_not_found' using errcode = 'P0001'; end if;
  if g.status <> 'open' then raise exception 'waitlist_group_closed' using errcode = 'P0001'; end if;

  if coalesce(cardinality(p_request_ids), 0) = 0
     or cardinality(p_request_ids) <> (select count(distinct x) from unnest(p_request_ids) x)
     or exists (select 1 from unnest(p_request_ids) rid where not exists (
          select 1 from public.waitlist_group_members wm
          where wm.group_id = g.id and wm.request_id = rid and wm.chosen is null))
  then
    raise exception 'waitlist_selection_invalid' using errcode = 'P0001';
  end if;

  v_driver_request := p_request_ids[1];
  select q.requester_id, q.preferred_car_id into v_driver_profile, v_preferred
  from public.requests q where q.id = v_driver_request;

  select d.home_destination_id into v_home from public.departments d where d.id = g.department_id;
  if v_home is null then raise exception 'no_home_location' using errcode = 'P0412'; end if;

  select make_interval(mins => s.turnaround_minutes) into v_turnaround
  from public.department_settings s where s.department_id = g.department_id;
  v_turnaround := coalesce(v_turnaround, interval '30 minutes');

  select min(q.depart_at), max(q.return_at),
         sum(q.adults)::int, sum(q.child_seats)::int, sum(q.boosters)::int
    into v_starts, v_ends, v_adults, v_child_seats, v_boosters
  from public.requests q where q.id = any(p_request_ids);

  if v_preferred is not null then
    select c.* into v_car from public.cars c
    where c.id = v_preferred and c.department_id = g.department_id
      and c.status = 'active' and c.type = 'shared'
      and public.car_fits(c.id, v_adults, v_child_seats, v_boosters)
      and public.car_location_at(c.id, v_starts) = v_home
      and not exists (select 1 from public.rides r where r.car_id = c.id and r.status <> 'cancelled'
        and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_starts, v_ends + v_turnaround, '[)'));
  end if;
  if v_car.id is null then
    select c.* into v_car from public.cars c
    where c.department_id = g.department_id and c.status = 'active' and c.type = 'shared'
      and public.car_fits(c.id, v_adults, v_child_seats, v_boosters)
      and public.car_location_at(c.id, v_starts) = v_home
      and not exists (select 1 from public.rides r where r.car_id = c.id and r.status <> 'cancelled'
        and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_starts, v_ends + v_turnaround, '[)'))
    order by c.id limit 1;
  end if;
  if v_car.id is null then
    raise exception 'no_car_free' using errcode = 'WLG01';
  end if;

  perform set_config('app.audit_reason', 'resolve_waitlist_group', true);

  insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
    driver_id, status, is_pinned, pin_reason, created_by)
  values (g.department_id, g.week_start, v_car.id, v_starts, v_ends, v_home, v_home,
    v_driver_profile, 'confirmed', true, 'WAITLIST_RESOLVED', p_actor)
  returning id into v_ride;

  insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
  values (v_ride, v_driver_request, 'driver', 'both', 'keep');

  foreach v_id in array p_request_ids loop
    if v_id <> v_driver_request then
      insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
      values (v_ride, v_id, 'passenger', 'both', 'passenger');
    end if;
  end loop;

  perform public.assert_car_chain(v_car.id, g.week_start);

  update public.waitlist_group_members set chosen = (request_id = any(p_request_ids))
  where group_id = g.id and chosen is null;

  perform set_config('app.system_status_transition', 'on', true);
  update public.requests set status = 'assigned', status_reason = 'WAITLIST_RESOLVED_DRIVER'
  where id = v_driver_request;
  update public.requests set status = 'merged', status_reason = 'WAITLIST_RESOLVED_PASSENGER'
  where id = any(p_request_ids) and id <> v_driver_request;
  -- Was bare before this migration: an unchosen participant's request is a DIFFERENT row
  -- than the actor's own when the actor is a mere participant, not a Sadran.
  update public.requests set status_reason = 'WAITLISTED_NOT_CHOSEN'
  where id in (select wm.request_id from public.waitlist_group_members wm
               where wm.group_id = g.id and wm.chosen = false)
    and status = 'waitlisted';
  perform set_config('app.system_status_transition', 'off', true);

  update public.waitlist_groups
  set status = 'resolved', ride_id = v_ride, resolved_by = p_actor, resolved_at = now()
  where id = g.id;

  select full_name into v_driver_name from public.profiles where id = v_driver_profile;
  select string_agg(coalesce(p.full_name, ''), ', ' order by m2.created_at, m2.id) into v_chosen_names
  from public.waitlist_group_members m2 join public.profiles p on p.id = m2.profile_id
  where m2.group_id = g.id and m2.chosen;
  v_day := to_char(g.day, 'DD/MM');
  v_depart := to_char(v_starts at time zone 'Asia/Jerusalem', 'HH24:MI');
  v_return := to_char(v_ends at time zone 'Asia/Jerusalem', 'HH24:MI');

  for m in select m3.request_id, m3.profile_id, m3.chosen
    from public.waitlist_group_members m3 where m3.group_id = g.id
    order by m3.created_at, m3.id
  loop
    v_variant := case when not m.chosen then 'not_chosen'
                      when m.request_id = v_driver_request then 'driver'
                      else 'passenger' end;
    perform public.enqueue_notification(m.profile_id, 'waitlist_resolved', g.department_id, g.week_start,
      jsonb_build_object('names', coalesce(v_chosen_names, ''), 'driverName', coalesce(v_driver_name, ''),
        'car', coalesce(v_car.name, ''), 'day', v_day, 'depart', v_depart, 'return', v_return),
      jsonb_build_object('group_id', g.id, 'request_id', m.request_id, 'day', g.day::text,
        'ride_id', case when m.chosen then v_ride end, 'variant', v_variant),
      format('waitlist_resolved:%s:%s', g.id, m.profile_id));
  end loop;

  for v_sadran in select * from public.sadranim_of(g.department_id, g.week_start) loop
    perform public.enqueue_notification(v_sadran, 'waitlist_resolved', g.department_id, g.week_start,
      jsonb_build_object('names', coalesce(v_chosen_names, ''), 'driverName', coalesce(v_driver_name, ''),
        'car', coalesce(v_car.name, ''), 'day', v_day, 'depart', v_depart, 'return', v_return),
      jsonb_build_object('group_id', g.id, 'day', g.day::text, 'ride_id', v_ride, 'variant', 'sadran'),
      format('waitlist_resolved:%s:sadran:%s', g.id, v_sadran));
  end loop;

  return jsonb_build_object('group_id', g.id, 'ride_id', v_ride, 'car_id', v_car.id,
    'driver_request_id', v_driver_request, 'chosen', to_jsonb(p_request_ids),
    'not_chosen', (select coalesce(jsonb_agg(m4.request_id), '[]')
                   from public.waitlist_group_members m4 where m4.group_id = g.id and m4.chosen = false));
end;
$$;


ALTER FUNCTION "public"."settle_waitlist_group"("p_group_id" "uuid", "p_request_ids" "uuid"[], "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shares_ride_with"("_profile" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.ride_requests rr1
    join public.requests q1 on q1.id = rr1.request_id and q1.requester_id = (select auth.uid())
    join public.ride_requests rr2 on rr2.ride_id = rr1.ride_id
    join public.requests q2 on q2.id = rr2.request_id and q2.requester_id = _profile
    join public.rides r on r.id = rr1.ride_id and r.status <> 'cancelled');
$$;


ALTER FUNCTION "public"."shares_ride_with"("_profile" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."siddur_versions_assign_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  select coalesce(max(version_no), 0) + 1 into new.version_no
  from public.siddur_versions where department_id = new.department_id and week_start = new.week_start;
  return new;
end;
$$;


ALTER FUNCTION "public"."siddur_versions_assign_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snooze_request_template"("p_template_id" "uuid", "p_week_start" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_approved() then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  update public.request_templates
    set snoozed_until_week = p_week_start + 7
  where id = p_template_id and requester_id = (select auth.uid());
  if not found then raise exception 'not_authorized' using errcode = 'P0001'; end if;
end;
$$;


ALTER FUNCTION "public"."snooze_request_template"("p_template_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."solver_policy_same_department"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists(select 1 from public.policy_versions v join public.policies p on p.id=v.policy_id where v.id=new.policy_version_id and p.department_id=new.department_id) then
    raise exception 'policy_department_mismatch' using errcode='P0001';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."solver_policy_same_department"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_request_template"("p_template_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.is_approved() then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  update public.request_templates
    set is_active = false, stopped_at = now()
  where id = p_template_id and requester_id = (select auth.uid());
  if not found then raise exception 'not_authorized' using errcode = 'P0001'; end if;
end;
$$;


ALTER FUNCTION "public"."stop_request_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_request"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_request_id uuid := nullif(payload ->> 'request_id', '')::uuid;
  v_requester_id uuid := coalesce(nullif(payload ->> 'requester_id', '')::uuid, v_actor);
  v_department_id uuid := (payload ->> 'department_id')::uuid;
  v_week_start date := (payload ->> 'week_start')::date;
  v_trip_shape public.trip_shape := coalesce((payload ->> 'trip_shape')::public.trip_shape, 'round_trip');
  v_depart_at timestamptz := nullif(payload ->> 'depart_at', '')::timestamptz;
  v_return_at timestamptz := nullif(payload ->> 'return_at', '')::timestamptz;
  v_one_way_mode public.leg_car_mode := nullif(payload ->> 'one_way_car_mode', '')::public.leg_car_mode;
  v_needs_car boolean := coalesce((payload ->> 'needs_car_at_destination')::boolean, true);
  v_preferred_car_id uuid := nullif(payload ->> 'preferred_car_id', '')::uuid;
  v_origin_id uuid := nullif(payload ->> 'origin_id', '')::uuid;
  v_origin_text text := nullif(payload ->> 'origin_text', '');
  v_trip_type_in text := nullif(payload ->> 'trip_type', '');
  v_trip_type public.trip_type;
  v_week record;
  v_existing record;
  v_can_manage boolean;
  v_is_late boolean;
  v_status public.request_status;
  v_warnings jsonb := '[]'::jsonb;
  v_join_ride_id uuid := nullif(payload ->> 'join_ride_id', '')::uuid;
  v_join_car_type public.car_type;
  v_join_owner uuid;
  v_auto_result jsonb;
  v_companion_ids uuid[];
  v_series_id uuid := nullif(payload ->> 'series_id', '')::uuid;
  v_series_index smallint := nullif(payload ->> 'series_index', '')::smallint;
  v_series_count smallint := nullif(payload ->> 'series_count', '')::smallint;
  v_eligible_driver uuid;
  v_kept timestamptz; v_prev_return timestamptz; v_prev_kept timestamptz;
begin
  if v_requester_id <> v_actor then
    if not public.can_manage_week(v_department_id, v_week_start) then
      raise exception 'not_authorized' using errcode = 'P0001';
    end if;
    v_can_manage := true;
  else
    v_can_manage := public.can_manage_week(v_department_id, v_week_start);
  end if;

  select * into v_week from public.weeks where department_id = v_department_id and week_start = v_week_start;
  if v_week is null then
    raise exception 'week_not_open' using errcode = 'P0001';
  end if;
  -- REQ §13.77: a week that only exists as `upcoming` (materialized early for a series leg)
  -- is not open for an ordinary new request; series legs (series_id set) are exactly what
  -- put it there and are accepted.
  if v_week.phase = 'upcoming' and v_series_id is null then
    raise exception 'week_not_open' using errcode = 'P0001';
  end if;

  if not public.is_approved() or not public.member_of(v_department_id) and not v_can_manage then raise exception 'not_authorized'; end if;
  if v_week.phase = 'archived' then raise exception 'week_archived'; end if;
  if not exists (select 1 from public.department_members where department_id=v_department_id and profile_id=v_requester_id and removed_at is null) then raise exception 'not_authorized'; end if;

  if v_trip_shape <> 'round_trip' then
    v_needs_car := true;
    -- REQ §13.88: the member no longer chooses a car mode; when omitted, default to
    -- the requester's driving ability — a non-driver's leg is `passenger`, everyone
    -- else's is `relay`. An explicit value (Sadran/board, older clients) is kept as-is.
    if v_one_way_mode is null then
      select case when p.does_not_drive then 'passenger'::public.leg_car_mode else 'relay'::public.leg_car_mode end
        into v_one_way_mode
      from public.profiles p where p.id = v_requester_id;
    end if;
  end if;

  -- REQ §13.93: origin defaults to the requester's default_origin_id for this department,
  -- else the department home; an explicit origin_id/origin_text always wins.
  if v_origin_id is null and v_origin_text is null then
    select dm.default_origin_id into v_origin_id from public.department_members dm
      where dm.department_id = v_department_id and dm.profile_id = v_requester_id and dm.removed_at is null;
    if v_origin_id is null then
      select home_destination_id into v_origin_id from public.departments where id = v_department_id;
    end if;
  end if;

  -- REQ §13.93: trip_type is the source of truth when sent; otherwise derive it from the
  -- legacy fields above (same mapping as the 20261004100200 backfill).
  if v_trip_type_in is not null then
    v_trip_type := v_trip_type_in::public.trip_type;
    case v_trip_type
      when 'round_trip' then
        v_trip_shape := 'round_trip'; v_needs_car := true; v_one_way_mode := null;
      when 'one_way' then
        v_trip_shape := 'one_way_to'; v_needs_car := true; v_one_way_mode := 'relay';
      when 'drop_off' then
        if v_return_at is not null then
          v_trip_shape := 'round_trip'; v_needs_car := false; v_one_way_mode := null;
        else
          v_trip_shape := 'one_way_to'; v_needs_car := false;
          if v_one_way_mode is null then
            select case when p.does_not_drive then 'passenger'::public.leg_car_mode else 'relay'::public.leg_car_mode end
              into v_one_way_mode
            from public.profiles p where p.id = v_requester_id;
          end if;
        end if;
    end case;
  else
    v_trip_type := case when v_trip_shape = 'round_trip' and v_needs_car then 'round_trip'::public.trip_type else 'drop_off'::public.trip_type end;
  end if;

  if v_request_id is not null then
    select * into v_existing from public.requests where id = v_request_id for update;
    if v_existing is null then
      raise exception 'request_not_found' using errcode = 'P0001';
    end if;
    if v_existing.requester_id <> v_actor and not public.can_manage_week(v_existing.department_id, v_existing.week_start) then
      raise exception 'not_authorized' using errcode = 'P0001';
    end if;
    if v_existing.department_id is distinct from v_department_id or v_existing.week_start is distinct from v_week_start or v_existing.requester_id is distinct from v_requester_id then raise exception 'not_authorized'; end if;
    -- REQ §13.77 v1: a multi-day series is cancelled and resubmitted, never edited leg by leg.
    if v_existing.series_id is not null or v_series_id is not null then
      raise exception 'series_edit_not_supported' using errcode = 'MDR02';
    end if;
    if not v_can_manage and (v_week.phase not in ('open','solving') or now() > v_week.close_at or now() < v_week.open_at) then raise exception 'request_window_closed'; end if;
    if v_existing.status in ('cancelled','withdrawn') or exists(select 1 from public.ride_requests rr join public.rides r on r.id=rr.ride_id where rr.request_id=v_request_id and r.status not in ('draft','cancelled')) then raise exception 'request_not_editable'; end if;
    if not (payload ? 'expected_version') then perform public.raise_stale_version(); end if;
    if v_existing.version is distinct from (payload ->> 'expected_version')::int then
      perform public.raise_stale_version();
    end if;
  end if;

  -- A one-way shape stores no return_at: remember the last real one (payload, else the stored one) in
  -- kept_return_at; a shape that needs a return and got none gets the kept one back.
  if v_request_id is not null then
    v_prev_return := v_existing.return_at; v_prev_kept := v_existing.kept_return_at;
  end if;
  if v_trip_shape = 'one_way_to' then
    v_kept := coalesce(v_return_at, v_prev_return, v_prev_kept);
    v_return_at := null;
  else
    v_return_at := coalesce(v_return_at, v_prev_kept);
  end if;

  if coalesce((payload->>'reserve_missing_driver')::boolean,false) and (
    v_request_id is not null or v_requester_id is distinct from v_actor or v_week.phase<>'live' or v_trip_shape='round_trip' or v_trip_type<>'drop_off' or v_join_ride_id is not null
  ) then raise exception 'invalid_quick_reservation';end if;
  if v_request_id is not null then perform public.release_request_draft_rides(v_request_id); end if;

  v_is_late := now() > v_week.close_at;

  perform set_config('app.audit_reason', 'submit_request', true);

  perform set_config('app.reset_request_baseline',case when v_requester_id=v_actor then 'on' else 'off' end,true);
  if v_request_id is null then
    v_status := 'submitted';
    insert into public.requests (
      department_id, week_start, requester_id, filed_by, destination_id, destination_text, ride_type_id,
      origin_id, origin_text, trip_type,
      trip_shape, depart_at, return_at, one_way_car_mode, needs_car_at_destination,
      adults, child_seats, boosters, has_luggage,
      flex_depart_early, flex_depart_late, flex_return_early, flex_return_late,
      notes, is_late, submitted_at, status, freed_slot_opt_out, join_ride_id, template_id, preferred_car_id,
      series_id, series_index, series_count, kept_return_at
    ) values (
      v_department_id, v_week_start, v_requester_id, v_actor,
      nullif(payload ->> 'destination_id', '')::uuid, nullif(payload ->> 'destination_text', ''),
      (payload ->> 'ride_type_id')::uuid,
      v_origin_id, v_origin_text, v_trip_type,
      v_trip_shape, v_depart_at, v_return_at, v_one_way_mode, v_needs_car,
      coalesce((payload ->> 'adults')::smallint, 1), coalesce((payload ->> 'child_seats')::smallint, 0),
      coalesce((payload ->> 'boosters')::smallint, 0), coalesce((payload ->> 'has_luggage')::boolean, false),
      coalesce(nullif(payload ->> 'flex_depart_early', '')::interval, '0'),
      coalesce(nullif(payload ->> 'flex_depart_late', '')::interval, '0'),
      coalesce(nullif(payload ->> 'flex_return_early', '')::interval, '0'),
      coalesce(nullif(payload ->> 'flex_return_late', '')::interval, '0'),
      nullif(payload ->> 'notes', ''), v_is_late, now(), v_status,
      coalesce((payload ->> 'freed_slot_opt_out')::boolean, false),
      v_join_ride_id, nullif(payload ->> 'template_id', '')::uuid, v_preferred_car_id,
      v_series_id, v_series_index, v_series_count, v_kept
    ) returning id into v_request_id;
  else
    update public.requests set
      destination_id = nullif(payload ->> 'destination_id', '')::uuid,
      destination_text = nullif(payload ->> 'destination_text', ''),
      ride_type_id = (payload ->> 'ride_type_id')::uuid,
      origin_id = v_origin_id, origin_text = v_origin_text, trip_type = v_trip_type,
      trip_shape = v_trip_shape, depart_at = v_depart_at, return_at = v_return_at, kept_return_at = v_kept,
      one_way_car_mode = v_one_way_mode, needs_car_at_destination = v_needs_car,
      adults = coalesce((payload ->> 'adults')::smallint, adults),
      child_seats = coalesce((payload ->> 'child_seats')::smallint, child_seats),
      boosters = coalesce((payload ->> 'boosters')::smallint, boosters),
      has_luggage = coalesce((payload ->> 'has_luggage')::boolean, has_luggage),
      flex_depart_early = coalesce(nullif(payload ->> 'flex_depart_early', '')::interval, flex_depart_early),
      flex_depart_late = coalesce(nullif(payload ->> 'flex_depart_late', '')::interval, flex_depart_late),
      flex_return_early = coalesce(nullif(payload ->> 'flex_return_early', '')::interval, flex_return_early),
      flex_return_late = coalesce(nullif(payload ->> 'flex_return_late', '')::interval, flex_return_late),
      notes = case when payload ? 'notes' then nullif(payload ->> 'notes','') else notes end,
      is_late = v_is_late,
      freed_slot_opt_out = coalesce((payload ->> 'freed_slot_opt_out')::boolean, freed_slot_opt_out),
      join_ride_id = coalesce(v_join_ride_id, join_ride_id),
      preferred_car_id = case when payload ? 'preferred_car_id' then v_preferred_car_id else preferred_car_id end,
      changed_since_solve = (v_week.phase not in ('open','solving'))
    where id = v_request_id
    returning status into v_status;

    if v_week.phase in ('solving','published') then
      perform public.enqueue_notification(s.profile_id, 'request_changed', v_department_id, v_week_start,
        jsonb_build_object('requestId', v_request_id::text), jsonb_build_object('request_id', v_request_id),
        format('request_changed:%s:%s', v_request_id, now()))
      from public.sadranim_of(v_department_id, v_week_start) as s(profile_id);
    end if;
  end if;

  perform set_config('app.reset_request_baseline','off',true);
  if payload ? 'ride_description' or payload ? 'guest_passenger_names' then
    if payload ? 'ride_description' and jsonb_typeof(payload->'ride_description') not in ('string','null') then raise exception 'invalid_ride_description';end if;
    if payload ? 'guest_passenger_names' and jsonb_typeof(payload->'guest_passenger_names') not in ('array','null') then raise exception 'invalid_passenger_names';end if;
    if payload ? 'guest_passenger_names' and jsonb_typeof(payload->'guest_passenger_names')='array' and exists(
      select 1 from jsonb_array_elements(payload->'guest_passenger_names') value where jsonb_typeof(value)<>'string') then raise exception 'invalid_passenger_names';end if;
    update public.requests set ride_description=case when payload ? 'ride_description' then payload->>'ride_description' else ride_description end,
      guest_passenger_names=case when payload ? 'guest_passenger_names' then array(select jsonb_array_elements_text(case when payload->'guest_passenger_names'='null'::jsonb then '[]'::jsonb else payload->'guest_passenger_names' end)) else guest_passenger_names end
      where id=v_request_id;
  end if;
  if payload ? 'companion_ids' then
    if jsonb_typeof(payload->'companion_ids') not in ('array','null') then raise exception 'invalid_companions';end if;
    select array_agg(value::uuid) into v_companion_ids from jsonb_array_elements_text(case when payload->'companion_ids'='null'::jsonb then '[]'::jsonb else payload->'companion_ids' end);
    if cardinality(v_companion_ids)>20 or cardinality(v_companion_ids)<>(select count(distinct id) from unnest(v_companion_ids) id)
      or exists(select 1 from unnest(v_companion_ids) candidate(profile_id) where candidate.profile_id=v_requester_id or not exists(
        select 1 from public.profiles p join public.department_members dm on dm.profile_id=p.id where p.id=candidate.profile_id
        and p.approval_status='approved' and dm.department_id=v_department_id and dm.removed_at is null)) then raise exception 'invalid_companions';end if;
    delete from public.request_companions where request_id=v_request_id;
    insert into public.request_companions(request_id,profile_id) select v_request_id,id from unnest(v_companion_ids) id;
  end if;
  if payload ? 'guest_passenger_names' or payload ? 'companion_ids' then perform public.assert_named_passenger_counts(v_request_id);end if;

  -- REQ §13.93 "Multi-stop rides": payload `stops` replaces the request's whole set, in route
  -- order per leg; absent key = leave existing stops untouched (same convention as `notes`).
  if payload ? 'stops' then
    perform public.replace_request_stops(v_request_id, v_department_id, v_return_at is not null, payload -> 'stops');
  end if;

  -- REQ §13.93: a requester who does not drive, and has no driving companion on board,
  -- may only file a הקפצה (drop_off) -- checked after companions are written above.
  if v_trip_type <> 'drop_off' then
    v_eligible_driver := public.eligible_leg_driver(v_request_id);
    if v_eligible_driver is null then
      raise exception 'non_driver_needs_drop_off' using errcode = 'P0001';
    end if;
  end if;

  -- Duplicate detection (warn, never block, REQ §5.3).
  if exists (
    select 1 from public.requests q
    where q.requester_id = v_requester_id and q.id <> v_request_id and q.status not in ('withdrawn','cancelled','denied','external')
      and q.department_id = v_department_id
      -- REQ §13.77: the legs of one multi-day series overlap each other by construction.
      and (v_series_id is null or q.series_id is distinct from v_series_id)
      and public.request_span(q.depart_at, q.return_at) && public.request_span(v_depart_at, v_return_at)
  ) then
    v_warnings := v_warnings || '"DUPLICATE_OVERLAP"'::jsonb;
  end if;

  -- Seat-fit warning (warn, never block).
  if not exists (
    select 1 from public.cars c join public.car_seat_configs csc on csc.car_id = c.id
    where c.department_id = v_department_id and c.status = 'active'
      and csc.adults >= coalesce((payload ->> 'adults')::smallint, 1)
      and csc.child_seats >= coalesce((payload ->> 'child_seats')::smallint, 0)
      and csc.boosters >= coalesce((payload ->> 'boosters')::smallint, 0)
  ) then
    v_warnings := v_warnings || '"NO_CAR_FITS_SEATS"'::jsonb;
  end if;

  -- "Ask to join" a temporary car: create + send the merge proposal straight to the owner (REQ §13.43).
  if v_join_ride_id is not null then
    select c.type, c.owner_id into v_join_car_type, v_join_owner
    from public.rides r join public.cars c on c.id = r.car_id where r.id = v_join_ride_id;
    if v_join_car_type = 'temporary' then
      perform public.create_proposal(v_request_id, v_join_ride_id, 'merge',
        jsonb_build_object('ride_id', v_join_ride_id, 'legs', jsonb_build_array(
          jsonb_build_object('leg', 'both', 'ride_id', v_join_ride_id, 'car_mode', 'passenger'))),
        'ASK_TO_JOIN_TEMP_CAR', array[v_join_owner], 'ask_to_join');
    end if;
  end if;

  -- Placement on submit (REQ §13.93/§13.94): only round_trip and an explicit one_way ("I take the
  -- car") go through try_auto_approve() once a week is published/live. Every drop_off, with or
  -- without a pickup, is two separate trips for the Sadran/solver: waitlisted in a live week.
  if coalesce((payload->>'reserve_missing_driver')::boolean,false) then
    v_auto_result:=public.reserve_live_one_way_slot(v_request_id);
    perform public.enqueue_notification(s.profile_id,'waitlisted_request',v_department_id,v_week_start,
      jsonb_build_object('requestId',v_request_id::text),jsonb_build_object('request_id',v_request_id,'ride_id',v_auto_result->>'ride_id'),
      format('waitlisted_request:%s',v_request_id)) from public.sadranim_of(v_department_id,v_week_start) as s(profile_id);
  elsif v_series_id is not null then
    -- REQ §13.77: placement is all-or-nothing across every leg — try_auto_approve_series()
    -- is called once by submit_series_request() after the last leg exists.
    v_auto_result := null;
  elsif v_week.phase in ('published','live')
    and v_trip_type in ('round_trip', 'one_way') then
    v_auto_result := public.try_auto_approve(v_request_id);
  elsif v_week.phase = 'live' then
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'waitlisted', status_reason = 'WAITLISTED_ONE_WAY' where id = v_request_id;
    perform set_config('app.system_status_transition', 'off', true);
    perform public.enqueue_notification(s.profile_id, 'waitlisted_request', v_department_id, v_week_start,
      jsonb_build_object('requestId', v_request_id::text), jsonb_build_object('request_id', v_request_id),
      format('waitlisted_request:%s', v_request_id))
    from public.sadranim_of(v_department_id, v_week_start) as s(profile_id);
    v_auto_result := jsonb_build_object('status', 'waitlisted', 'reason', 'WAITLISTED_ONE_WAY');
  end if;

  if v_is_late and coalesce(v_auto_result->>'status','') <> 'assigned' and coalesce(v_series_index, 1) = 1 then
    perform public.enqueue_notification(s.profile_id, 'late_request', v_department_id, v_week_start,
      jsonb_build_object('requestId', v_request_id::text), jsonb_build_object('request_id', v_request_id),
      format('late_request:%s', v_request_id))
    from public.sadranim_of(v_department_id, v_week_start) as s(profile_id);
  end if;

  return jsonb_build_object('request_id', v_request_id, 'is_late', v_is_late, 'warnings', v_warnings)
    || coalesce(v_auto_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."submit_request"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_series_request"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_dept uuid := (payload ->> 'department_id')::uuid;
  v_depart timestamptz := nullif(payload ->> 'depart_at', '')::timestamptz;
  v_return timestamptz := nullif(payload ->> 'return_at', '')::timestamptz;
  v_shape public.trip_shape := coalesce((payload ->> 'trip_shape')::public.trip_shape, 'round_trip');
  v_first_date date; v_last_date date; v_count int; v_series uuid := gen_random_uuid();
  v_d date; v_week date; v_first_week date; v_phase public.week_phase;
  v_ids uuid[] := '{}'; v_warnings jsonb := '[]'::jsonb; v_leg jsonb; v_auto jsonb;
begin
  if payload ? 'request_id' or payload ? 'series_id' then
    raise exception 'series_edit_not_supported' using errcode = 'MDR02';
  end if;
  if v_dept is null or v_depart is null or v_return is null or v_shape <> 'round_trip' then
    raise exception 'invalid_series_request' using errcode = 'P0001';
  end if;
  v_first_date := (v_depart at time zone 'Asia/Jerusalem')::date;
  v_last_date  := (v_return at time zone 'Asia/Jerusalem')::date;
  if v_last_date <= v_first_date then
    raise exception 'invalid_series_request' using errcode = 'P0001';
  end if;
  v_count := (v_last_date - v_first_date) + 1;
  v_first_week := v_first_date - extract(dow from v_first_date)::int;

  -- Pre-flight every day, so a span that runs past the sane ceiling fails before any leg is
  -- filed (the raise would unwind them anyway; this just keeps the error unambiguous). A
  -- week that has no row yet is materialized `upcoming` right here, not left for
  -- submit_request() to reject.
  for i in 0 .. v_count - 1 loop
    v_d := v_first_date + i;
    v_week := v_d - extract(dow from v_d)::int;
    if v_week < public.current_week_start() or v_week > v_first_week + 42 then
      raise exception 'series_week_not_open' using errcode = 'MDR01';
    end if;
    if not exists (select 1 from public.weeks w where w.department_id = v_dept and w.week_start = v_week) then
      perform public.ensure_upcoming_week(v_dept, v_week);
    end if;
  end loop;

  for i in 0 .. v_count - 1 loop
    v_d := v_first_date + i;
    v_week := v_d - extract(dow from v_d)::int;
    v_leg := public.submit_request(
      (payload - 'request_id' - 'expected_version' - 'trip_type') || jsonb_build_object(
        'week_start', v_week,
        'trip_shape', 'round_trip',
        'depart_at', case when i = 0 then v_depart else (v_d::timestamp) at time zone 'Asia/Jerusalem' end,
        'return_at', case when i = v_count - 1 then v_return
                          else ((v_d + time '23:59')) at time zone 'Asia/Jerusalem' end,
        'series_id', v_series, 'series_index', i + 1, 'series_count', v_count));
    v_ids := array_append(v_ids, (v_leg ->> 'request_id')::uuid);
    if i = 0 then v_warnings := coalesce(v_leg -> 'warnings', '[]'::jsonb); end if;
  end loop;

  select w.phase into v_phase from public.weeks w where w.department_id = v_dept and w.week_start = v_first_week;
  if v_phase in ('published', 'live') then
    v_auto := public.try_auto_approve_series(v_series);
  end if;

  return jsonb_build_object('series_id', v_series, 'request_ids', to_jsonb(v_ids), 'warnings', v_warnings)
    || coalesce(v_auto, '{}'::jsonb);
end $$;


ALTER FUNCTION "public"."submit_series_request"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_destination"("p_department_id" "uuid", "p_name" "text", "p_zone" "text" DEFAULT 'unknown'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not (public.is_admin() or public.member_of(p_department_id)) then raise exception 'not_authorized' using errcode='P0001'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'invalid_destination_name' using errcode='P0001'; end if;
  insert into public.destinations(department_id,name,zone,is_approved,created_by) values(p_department_id,p_name,p_zone,false,(select auth.uid())) returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."suggest_destination"("p_department_id" "uuid", "p_name" "text", "p_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_day_cars"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid", "p_expected_fingerprint" "text", "p_series_mode" "text" DEFAULT 'whole'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := (select auth.uid());
  v_day_ids uuid[];
  v_series_ids uuid[];
  v_moving uuid[];
  v_auth_blockers jsonb;
  v_phys_blockers jsonb;
  v_notices jsonb;
  v_old_car_names jsonb;
  v_fp text;
  v_sid uuid;
  v_weeks date[];
  w date;
  v_notified int := 0;
  v_moved int := 0;
  v_person record;
begin
  if p_series_mode not in ('whole', 'day') then
    raise exception 'invalid_series_mode' using errcode = 'P0001';
  end if;

  v_auth_blockers := public._day_car_swap_authorize(p_department_id, p_week_start, p_day, p_car_a, p_car_b, v_actor);
  if jsonb_array_length(v_auth_blockers) > 0 then
    raise exception 'not_authorized' using errcode = 'P0001', detail = v_auth_blockers::text;
  end if;

  v_day_ids := public._day_car_swap_day_ride_ids(p_department_id, p_week_start, p_day, p_car_a, p_car_b);
  v_fp := public._day_car_swap_fingerprint(v_day_ids);
  if p_expected_fingerprint is null or v_fp <> p_expected_fingerprint then
    perform public.raise_stale_version();
  end if;

  v_series_ids := public._day_car_swap_series_ids(v_day_ids);

  if p_series_mode = 'whole' then
    v_moving := public._day_car_swap_expand_whole(v_day_ids);
  else
    v_moving := v_day_ids;   -- 'day': only the swapped day's own legs change car
  end if;

  v_phys_blockers := public._day_car_swap_private_car_blockers(p_car_a, p_car_b, v_actor)
    || public._day_car_swap_physical_blockers(v_moving, p_car_a, p_car_b);
  if jsonb_array_length(v_phys_blockers) > 0 then
    raise exception 'day_car_swap_blocked' using errcode = 'P0001', detail = (v_phys_blockers -> 0)::text;
  end if;

  v_notices := case when coalesce(array_length(v_day_ids, 1), 0) > 0
    then public._day_car_swap_notices(v_day_ids, p_car_a, p_car_b, p_day)
    else '[]'::jsonb end;

  -- capture each moving ride's pre-swap car name for the `fromCar` notification var.
  select jsonb_object_agg(r.id::text, c.name) into v_old_car_names
  from public.rides r join public.cars c on c.id = r.car_id
  where r.id = any(v_moving);

  perform set_config('app.audit_reason', 'swap_day_cars', true);

  if p_series_mode = 'day' then
    foreach v_sid in array v_series_ids loop
      perform public._day_car_swap_split_series(v_sid, p_day);
    end loop;
  end if;

  -- One UPDATE exchanges the two cars. Two per-row checks would false-positive mid-statement
  -- whenever both cars have rides at the same time (the ordinary case): the overlap
  -- exclusion constraint and rides_before_write's neighbour/turnaround check both compare a
  -- moved row with the other car's not-yet-moved row. So, scoped to this statement only:
  -- the exclusion constraint is deferred (DEFERRABLE INITIALLY IMMEDIATE, top of this file)
  -- and `app.day_car_swap` makes rides_before_write skip its neighbour checks; the same
  -- checks then run on the final state right after — no table lock, no trigger disabling.
  set constraints public.rides_no_overlap_per_car deferred;
  perform set_config('app.day_car_swap', 'on', true);
  update public.rides
  set car_id = case when car_id = p_car_a then p_car_b else p_car_a end
  where id = any(v_moving) and car_id in (p_car_a, p_car_b);
  perform set_config('app.day_car_swap', 'off', true);
  if exists (
    select 1
    from public.rides r1
    join public.rides r2 on r2.car_id = r1.car_id and r2.id <> r1.id
    where r1.id = any(v_moving)
      and r1.status <> 'cancelled' and r2.status <> 'cancelled'
      and not r1.planning_conflict and not r2.planning_conflict
      and not (r1.series_id is not null and r1.series_id = r2.series_id)
      and tstzrange(r1.starts_at, r1.blocked_until, '[)') && tstzrange(r2.starts_at, r2.blocked_until, '[)')
  ) then
    raise exception 'ride_turnaround_conflict' using errcode = '23P01';
  end if;
  set constraints public.rides_no_overlap_per_car immediate;

  v_moved := coalesce(array_length(v_moving, 1), 0);

  select coalesce(array_agg(distinct week_start), array[p_week_start]) into v_weeks
  from public.rides where id = any(v_moving);

  foreach w in array v_weeks loop
    perform public.assert_car_chain(p_car_a, w);
    perform public.assert_car_chain(p_car_b, w);
  end loop;

  if public.is_day_public(p_department_id, p_week_start, p_day) and coalesce(array_length(v_day_ids, 1), 1) > 0 then
    for v_person in
      select distinct (pe ->> 'person_id')::uuid as person_id, vbr.id as ride_id
      from public.v_board_rides vbr
      cross join lateral jsonb_array_elements(vbr.people) pe
      where vbr.id = any(v_day_ids) and pe ->> 'person_id' is not null
    loop
      if v_person.person_id is distinct from v_actor then
        perform public.enqueue_notification(v_person.person_id, 'car_swapped', p_department_id, p_week_start,
          jsonb_build_object('fromCar', coalesce(v_old_car_names ->> v_person.ride_id::text, '')),
          jsonb_build_object('ride_id', v_person.ride_id),
          format('car_swapped:%s:%s', v_person.ride_id, v_person.person_id));
        v_notified := v_notified + 1;
      end if;
    end loop;
  end if;

  return jsonb_build_object('moved_rides', v_moved, 'notified', v_notified, 'notices', v_notices);
end $$;


ALTER FUNCTION "public"."swap_day_cars"("p_department_id" "uuid", "p_week_start" "date", "p_day" "date", "p_car_a" "uuid", "p_car_b" "uuid", "p_expected_fingerprint" "text", "p_series_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_google_profile_name"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.profiles set google_name=coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),
    nullif(trim(new.raw_user_meta_data->>'name'),''),google_name) where id=new.id;
  return new;
end $$;


ALTER FUNCTION "public"."sync_google_profile_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_auto_approve"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req record;
  v_car record;
  v_turnaround interval;
  v_ride_id uuid;
  v_preferred_ok boolean := false;
  v_is_one_way boolean;
  v_end timestamptz;
  v_travel int;
  v_driver uuid;
begin
  select * into v_req from public.requests where id = p_request_id for update;
  if v_req.id is null or v_req.status not in ('submitted', 'waitlisted') then
    return null;
  end if;

  -- REQ §13.94: a drop_off (with or without a pickup) is never auto-placed; it is two
  -- separate trips for the Sadran/solver, not one block that holds the car.
  if v_req.trip_type = 'drop_off' then
    return null;
  end if;

  v_is_one_way := v_req.trip_shape = 'one_way_to' and v_req.trip_type = 'one_way';
  if v_req.trip_shape <> 'round_trip' and not v_is_one_way then
    return null;
  end if;
  -- A free-text origin is never auto-placed (REQ §13.93: "the Sadran handles it").
  if v_req.origin_id is null then
    return null;
  end if;

  perform set_config('app.system_status_transition', 'on', true);

  select make_interval(mins => s.turnaround_minutes) into v_turnaround
  from public.department_settings s where s.department_id = v_req.department_id;

  if v_is_one_way then
    -- A free-text destination can never relay (REQ §13.58); no window to compute either.
    if v_req.destination_id is null then
      perform set_config('app.system_status_transition', 'off', true);
      return null;
    end if;
    v_driver := public.eligible_leg_driver(p_request_id);
    if v_driver is null then
      -- No eligible driver on board: not this function's job (submit_request's
      -- non_driver_needs_drop_off guard should have prevented this at submission time).
      perform set_config('app.system_status_transition', 'off', true);
      return null;
    end if;
    v_travel := greatest(coalesce(public.request_leg_route_minutes(p_request_id, 'out'), 30), 0);
    v_end := v_req.depart_at + make_interval(mins => v_travel);
    if not public.is_quarter_hour(v_end) then
      v_end := to_timestamp(ceil(extract(epoch from v_end) / 900) * 900);
    end if;
  else
    v_end := v_req.return_at;
  end if;

  -- Preferred car first: same eligibility rules as the fallback query below (shared,
  -- active, seats fit, at the request's origin at departure, no overlap incl. the
  -- turnaround buffer, and -- for a one-way leg -- no later ride on that car starting
  -- anywhere but the destination), scoped to that single car.
  if v_req.preferred_car_id is not null then
    select c.* into v_car
    from public.cars c
    join public.car_seat_configs csc on csc.car_id = c.id
    where c.id = v_req.preferred_car_id and c.department_id = v_req.department_id
      and c.status = 'active' and c.type = 'shared'
      and csc.adults >= v_req.adults and csc.child_seats >= v_req.child_seats and csc.boosters >= v_req.boosters
      and public.car_location_at(c.id, v_req.depart_at) = v_req.origin_id
      and not exists (
        select 1 from public.rides r
        where r.car_id = c.id and r.status <> 'cancelled'
          and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_req.depart_at, v_end + v_turnaround, '[)')
      )
      and (not v_is_one_way or coalesce(public.car_next_ride_origin(c.id, v_end), v_req.destination_id) = v_req.destination_id)
    order by c.id limit 1;
    v_preferred_ok := v_car.id is not null;
  end if;

  if not v_preferred_ok then
    select c.* into v_car
    from public.cars c
    join public.car_seat_configs csc on csc.car_id = c.id
    where c.department_id = v_req.department_id and c.status = 'active' and c.type = 'shared'
      and csc.adults >= v_req.adults and csc.child_seats >= v_req.child_seats and csc.boosters >= v_req.boosters
      and public.car_location_at(c.id, v_req.depart_at) = v_req.origin_id
      and not exists (
        select 1 from public.rides r
        where r.car_id = c.id and r.status <> 'cancelled'
          and tstzrange(r.starts_at, r.blocked_until, '[)') && tstzrange(v_req.depart_at, v_end + v_turnaround, '[)')
      )
      and (not v_is_one_way or coalesce(public.car_next_ride_origin(c.id, v_end), v_req.destination_id) = v_req.destination_id)
    order by c.id limit 1;
  end if;

  if v_car.id is null then
    perform set_config('app.audit_reason', 'try_auto_approve:no_car', true);
    update public.requests set status = 'waitlisted', status_reason = 'WAITLISTED_NO_CAR' where id = p_request_id;
    perform public.enqueue_notification(s.profile_id, 'waitlisted_request', v_req.department_id, v_req.week_start,
      jsonb_build_object('requestId', p_request_id::text), jsonb_build_object('request_id', p_request_id),
      format('waitlisted_request:%s', p_request_id))
    from public.sadranim_of(v_req.department_id, v_req.week_start) as s(profile_id);
    perform set_config('app.system_status_transition', 'off', true);
    -- 20260910091900 (contested waiting-list groups, REQ §7.3): join_waitlist_group() is a
    -- round-trip-only no-op for a one-way leg, so this stays safe to call unconditionally.
    if public.join_waitlist_group(p_request_id) is not null then
      return jsonb_build_object('status', 'waitlisted', 'reason', 'WAITLISTED_CONTESTED');
    end if;
    return jsonb_build_object('status', 'waitlisted', 'reason', 'WAITLISTED_NO_CAR');
  end if;

  perform set_config('app.audit_reason', 'try_auto_approve:assigned', true);
  if v_is_one_way then
    insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
      driver_id, status, is_pinned, pin_reason, created_by)
    values (v_req.department_id, v_req.week_start, v_car.id, v_req.depart_at, v_end, v_req.origin_id, v_req.destination_id,
      v_driver, 'confirmed', true, 'AUTO_APPROVED', v_req.requester_id)
    returning id into v_ride_id;

    insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
    values (v_ride_id, p_request_id, 'driver', 'out', 'relay');

    update public.requests set status = 'assigned', status_reason = 'AUTO_APPROVED_RELAY' where id = p_request_id;
  else
    insert into public.rides (department_id, week_start, car_id, starts_at, ends_at, origin_id, destination_id,
      driver_id, status, is_pinned, pin_reason, created_by)
    values (v_req.department_id, v_req.week_start, v_car.id, v_req.depart_at, v_req.return_at, v_req.origin_id, v_req.origin_id,
      v_req.requester_id, 'confirmed', true, 'AUTO_APPROVED', v_req.requester_id)
    returning id into v_ride_id;

    insert into public.ride_requests (ride_id, request_id, role, leg, car_mode)
    values (v_ride_id, p_request_id, 'driver', 'both', 'keep');

    update public.requests set status = 'assigned', status_reason = 'AUTO_APPROVED_FREE_CAR' where id = p_request_id;
  end if;

  perform public.assert_car_chain(v_car.id, v_req.week_start);
  perform set_config('app.system_status_transition', 'off', true);

  perform public.enqueue_notification(v_req.requester_id, 'auto_approved', v_req.department_id, v_req.week_start,
    jsonb_build_object('requestId', p_request_id::text), jsonb_build_object('request_id', p_request_id, 'ride_id', v_ride_id),
    format('auto_approved:%s', p_request_id));
  perform public.enqueue_notification(s.profile_id, 'auto_approved', v_req.department_id, v_req.week_start,
    jsonb_build_object('requestId', p_request_id::text), jsonb_build_object('request_id', p_request_id, 'ride_id', v_ride_id),
    format('auto_approved:%s:%s', p_request_id, s.profile_id))
  from public.sadranim_of(v_req.department_id, v_req.week_start) as s(profile_id);

  return jsonb_build_object('status', 'assigned', 'ride_id', v_ride_id, 'car_id', v_car.id);
end;
$$;


ALTER FUNCTION "public"."try_auto_approve"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_auto_approve_series"("p_series_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_head record; v_car record; v_result jsonb;
begin
  select q.id, q.department_id, q.week_start, q.requester_id, q.preferred_car_id
    into v_head from public.requests q where q.series_id = p_series_id order by q.series_index limit 1;
  if v_head.id is null then return null; end if;
  -- REQ §13.94: a drop_off series is never held on one car; the Sadran serves each leg.
  if exists (select 1 from public.requests q where q.series_id = p_series_id and q.trip_type = 'drop_off') then
    return null;
  end if;

  for v_car in
    select c.id from public.cars c
    where c.department_id = v_head.department_id and c.status = 'active' and c.type = 'shared'
    order by (c.id = v_head.preferred_car_id) desc, c.id
  loop
    begin
      v_result := public.place_series(p_series_id, v_car.id, true, 'SERIES_PLACED');
      return v_result || jsonb_build_object('status', 'assigned', 'reason', 'SERIES_PLACED');
    exception when others then
      null;                                        -- try the next car; the subtransaction unwinds
    end;
  end loop;

  perform set_config('app.system_status_transition', 'on', true);
  perform set_config('app.audit_reason', 'try_auto_approve_series:no_car', true);
  update public.requests set status = 'waitlisted', status_reason = 'WAITLISTED_SERIES_NO_CAR'
  where series_id = p_series_id;
  perform set_config('app.system_status_transition', 'off', true);

  perform public.enqueue_notification(s.profile_id, 'waitlisted_request', v_head.department_id, v_head.week_start,
    jsonb_build_object('requestId', v_head.id::text),
    jsonb_build_object('request_id', v_head.id, 'series_id', p_series_id),
    format('waitlisted_series:%s:%s', p_series_id, s.profile_id))
  from public.sadranim_of(v_head.department_id, v_head.week_start) as s(profile_id);

  return jsonb_build_object('status', 'waitlisted', 'reason', 'WAITLISTED_SERIES_NO_CAR', 'series_id', p_series_id);
end $$;


ALTER FUNCTION "public"."try_auto_approve_series"("p_series_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_widen_one_way_leg"("p_ride_id" "uuid", "p_car" "uuid", "p_dept" "uuid", "p_week" "date", "p_home" "uuid", "p_turnaround" interval, "p_direction" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_request_id uuid; v_trip_shape public.trip_shape; v_trip_type public.trip_type;
  v_origin uuid; v_dest uuid; v_requester uuid;
  v_travel int; v_dwell int;
  v_start_a timestamptz; v_end_a timestamptz;
  v_start_b timestamptz; v_end_b timestamptz;
  v_start timestamptz; v_end timestamptz; v_loc uuid;
  v_car_id uuid; v_candidate uuid;
  v_was_active boolean;
  v_adults smallint; v_child_seats smallint; v_boosters smallint;
  v_prev_flag text;
begin
  select * into v_ride from public.rides where id = p_ride_id;
  if v_ride is null or v_ride.status = 'cancelled' then return null; end if;
  if (select count(*) from public.ride_requests where ride_id = p_ride_id) <> 1 then return null; end if;

  select rr.request_id, q.trip_shape, q.trip_type, q.origin_id, q.destination_id, q.requester_id,
         q.adults, q.child_seats, q.boosters
    into v_request_id, v_trip_shape, v_trip_type, v_origin, v_dest, v_requester,
         v_adults, v_child_seats, v_boosters
  from public.ride_requests rr join public.requests q on q.id = rr.request_id
  where rr.ride_id = p_ride_id;
  -- An explicit one_way trip never widens (§1.3a); neither does a round trip or a free-text end.
  if v_trip_type is distinct from 'drop_off' then return null; end if;
  if v_origin is null or v_dest is null then return null; end if;
  if p_direction = 'out' and v_trip_shape <> 'one_way_to' then return null; end if;
  if p_direction = 'fetch' and v_trip_shape <> 'one_way_from' then return null; end if;

  v_was_active := not v_ride.needs_driver;

  select coalesce(
      (select (w.settings_overrides ->> 'chauffeur_dwell_minutes')::int from public.weeks w
       where w.department_id = p_dept and w.week_start = p_week),
      (select s.chauffeur_dwell_minutes from public.department_settings s where s.department_id = p_dept), 10)
    into v_dwell;

  if p_direction = 'out' then
    v_travel := greatest(coalesce(public.request_leg_route_minutes(v_request_id, 'out'), 30), 0);
    -- Candidate A: the car is at the leg's origin -- drop-off wrap, leaves when the leg
    -- already would and comes straight back instead of being left at the destination.
    v_start_a := v_ride.starts_at;
    v_end_a := v_start_a + make_interval(mins => 2 * v_travel + greatest(v_dwell, 0));
    if not (public.is_quarter_hour(v_end_a) or public.is_same_day_end(v_end_a)) then
      v_end_a := to_timestamp(ceil(extract(epoch from v_end_a) / 900) * 900);
    end if;
    -- Candidate B: the car is at the leg's destination -- pickup wrap ("pick me up from X"):
    -- the car fetches the requester at the origin just in time for the stated departure and
    -- returns to the destination.
    v_start_b := v_start_a - make_interval(mins => v_travel + greatest(v_dwell, 0));
    if not public.is_quarter_hour(v_start_b) then
      v_start_b := to_timestamp(floor(extract(epoch from v_start_b) / 900) * 900);
    end if;
    v_end_b := v_start_a + make_interval(mins => v_travel);
    if not public.is_quarter_hour(v_end_b) then
      v_end_b := to_timestamp(ceil(extract(epoch from v_end_b) / 900) * 900);
    end if;

    v_car_id := null;
    for v_candidate in
      select c.id from public.cars c
      where c.department_id = p_dept and c.status = 'active' and c.type = 'shared'
      order by (c.id = p_car) desc, c.id
    loop
      if public.car_location_at(v_candidate, v_start_a) = v_origin
        and public.car_fits(v_candidate, v_adults + 1, v_child_seats, v_boosters)
        and not exists (
          select 1 from public.rides x
          where x.car_id = v_candidate and x.id <> p_ride_id and x.status <> 'cancelled' and not x.planning_conflict
            and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_start_a, v_end_a + p_turnaround, '[)')
        )
      then
        v_car_id := v_candidate; v_start := v_start_a; v_end := v_end_a; v_loc := v_origin;
        exit;
      end if;
    end loop;

    if v_car_id is null then
      for v_candidate in
        select c.id from public.cars c
        where c.department_id = p_dept and c.status = 'active' and c.type = 'shared'
        order by (c.id = p_car) desc, c.id
      loop
        if public.car_location_at(v_candidate, v_start_b) = v_dest
          and public.car_fits(v_candidate, v_adults + 1, v_child_seats, v_boosters)
          and not exists (
            select 1 from public.rides x
            where x.car_id = v_candidate and x.id <> p_ride_id and x.status <> 'cancelled' and not x.planning_conflict
              and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_start_b, v_end_b + p_turnaround, '[)')
          )
        then
          v_car_id := v_candidate; v_start := v_start_b; v_end := v_end_b; v_loc := v_dest;
          exit;
        end if;
      end loop;
    end if;
  else
    -- Legacy return/fetch leg: single formula, now anchored at the request's own origin
    -- (previously always the department home) -- unchanged otherwise.
    v_travel := greatest(coalesce(public.request_leg_route_minutes(v_request_id, 'return'), 30), 0);
    v_end := v_ride.ends_at;
    v_start := v_end - make_interval(mins => 2 * v_travel + greatest(v_dwell, 0));
    if not public.is_quarter_hour(v_start) then
      v_start := to_timestamp(floor(extract(epoch from v_start) / 900) * 900);
    end if;
    v_loc := v_origin;

    v_car_id := p_car;
    if not (public.car_fits(v_car_id, v_adults + 1, v_child_seats, v_boosters)) or exists (
      select 1 from public.rides x
      where x.car_id = v_car_id and x.id <> p_ride_id and x.status <> 'cancelled' and not x.planning_conflict
        and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_start, v_end + p_turnaround, '[)')
    ) then
      v_car_id := null;
      for v_candidate in
        select c.id from public.cars c
        where c.department_id = p_dept and c.status = 'active' and c.type = 'shared' and c.id <> p_car
        order by c.id
      loop
        if public.car_fits(v_candidate, v_adults + 1, v_child_seats, v_boosters) and not exists (
          select 1 from public.rides x
          where x.car_id = v_candidate and x.status <> 'cancelled' and not x.planning_conflict
            and tstzrange(x.starts_at, x.blocked_until, '[)') && tstzrange(v_start, v_end + p_turnaround, '[)')
        ) then
          v_car_id := v_candidate;
          exit;
        end if;
      end loop;
    end if;
  end if;

  if v_start >= v_end then v_end := v_start + interval '15 minutes'; end if;

  if v_car_id is null then
    -- Neither end has an available, seat-fitting car: the request goes back to unmet
    -- (ORIGINS_PLAN §3) instead of staying a dangling chauffeur placeholder.
    delete from public.ride_requests where ride_id = p_ride_id and request_id = v_request_id;
    update public.rides set status = 'cancelled', cancelled_at = now(),
      cancelled_by = coalesce((select auth.uid()), v_ride.created_by), cancel_reason = 'UNMET_NO_CAR_AT_ORIGIN'
    where id = p_ride_id;

    v_prev_flag := coalesce(current_setting('app.system_status_transition', true), 'off');
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'submitted', status_reason = 'UNMET_NO_CAR_AT_ORIGIN' where id = v_request_id;
    perform set_config('app.system_status_transition', v_prev_flag, true);

    if v_was_active then
      perform public.enqueue_notification(v_requester, 'outcome_changed', p_dept, p_week,
        '{}'::jsonb, jsonb_build_object('request_id', v_request_id),
        format('outcome_changed:%s:%s', v_request_id, now()));
    end if;
    return 'unmet';
  end if;

  update public.rides set
    car_id = v_car_id, origin_id = v_loc, destination_id = v_loc,
    starts_at = v_start, ends_at = v_end, needs_driver = true, driver_id = null,
    -- A former relay leg may carry its short gap at X as an override (20260924120000);
    -- the reshaped chauffeur ride gets the ordinary turnaround again.
    turnaround_override_minutes = null
  where id = p_ride_id;

  update public.ride_requests set role = 'passenger', car_mode = 'chauffeur'
  where ride_id = p_ride_id and request_id = v_request_id;

  if v_was_active then
    perform public.enqueue_notification(v_requester, 'outcome_changed', p_dept, p_week,
      '{}'::jsonb, jsonb_build_object('request_id', v_request_id),
      format('outcome_changed:%s:%s', v_request_id, now()));
  end if;

  return case when v_car_id = p_car then 'here' else 'moved' end;
end $$;


ALTER FUNCTION "public"."try_widen_one_way_leg"("p_ride_id" "uuid", "p_car" "uuid", "p_dept" "uuid", "p_week" "date", "p_home" "uuid", "p_turnaround" interval, "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unassign_ride"("p_ride_id" "uuid", "p_expected_version" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.rides%rowtype; ids uuid[];
begin
  select * into r from public.rides where id=p_ride_id for update;
  if not found then raise exception 'ride_not_found'; end if;
  if not public.can_manage_week(r.department_id,r.week_start) then raise exception 'not_authorized'; end if;
  if p_expected_version is null or r.version<>p_expected_version then perform public.raise_stale_version(); end if;
  if exists(select 1 from public.weeks where department_id=r.department_id and week_start=r.week_start and phase='archived') then raise exception 'week_archived'; end if;
  perform set_config('app.audit_reason','unassign_ride',true);
  select array_agg(request_id) into ids from public.ride_requests where ride_id=r.id;
  update public.rides set status='cancelled',cancelled_at=now(),cancelled_by=(select auth.uid()),cancel_reason='SADRAN_UNASSIGNED' where id=r.id;
  delete from public.ride_requests where ride_id=r.id;
  update public.requests q set status='waitlisted',status_reason='SADRAN_UNASSIGNED' where id=any(ids)
    and not exists(select 1 from public.ride_requests rr join public.rides rd on rd.id=rr.ride_id where rr.request_id=q.id and rd.status<>'cancelled');
  perform set_config('app.chain_hint', jsonb_build_object('origin_id',r.origin_id,'destination_id',r.destination_id,
    'starts_at',r.starts_at,'ends_at',r.ends_at)::text, true);
  perform public.assert_car_chain(r.car_id,r.week_start);
end $$;


ALTER FUNCTION "public"."unassign_ride"("p_ride_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unmerge_request"("p_ride_id" "uuid", "p_request_id" "uuid", "p_expected_version" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ride public.rides%rowtype;
  v_actor uuid := (select auth.uid());
  v_guest public.requests%rowtype;
  v_base uuid; v_base_return timestamptz; v_base_depart timestamptz;
  v_before int; v_after int; v_delta int; v_b_out int; v_a_out int; v_b_ret int; v_a_ret int;
  v_start timestamptz; v_end timestamptz; v_prev_sys text; v_new_window boolean;
  v_actor_name text; v_dest_name text; v_route text;
begin
  select * into v_ride from public.rides where id = p_ride_id for update;
  if not found or v_ride.status = 'cancelled' then raise exception 'ride_not_found' using errcode = 'P0001'; end if;
  if not public.can_manage_week(v_ride.department_id, v_ride.week_start) then raise exception 'not_authorized' using errcode = 'P0001'; end if;
  if p_expected_version is null or v_ride.version <> p_expected_version then perform public.raise_stale_version(); end if;
  if exists (select 1 from public.weeks w where w.department_id = v_ride.department_id and w.week_start = v_ride.week_start and w.phase = 'archived') then
    raise exception 'week_archived' using errcode = 'P0001';
  end if;

  select * into v_guest from public.requests q where q.id = p_request_id;
  if v_guest.id is null or v_guest.department_id <> v_ride.department_id
     or not exists (select 1 from public.ride_requests rr where rr.ride_id = p_ride_id and rr.request_id = p_request_id) then
    raise exception 'request_not_on_ride' using errcode = 'P0001';
  end if;

  select rr.request_id into v_base from public.ride_requests rr where rr.ride_id = p_ride_id
  order by (rr.role = 'driver') desc, rr.created_at, rr.request_id limit 1;
  if v_base = p_request_id
     or exists (select 1 from public.ride_requests rr where rr.ride_id = p_ride_id and rr.request_id = p_request_id and rr.role = 'driver')
     or v_ride.driver_id is not distinct from v_guest.requester_id then
    raise exception 'unmerge_base_request' using errcode = 'P0001';
  end if;

  perform set_config('app.audit_reason', 'unmerge_request', true);
  v_b_out := public.ride_route_minutes(p_ride_id, 'out'); v_b_ret := public.ride_route_minutes(p_ride_id, 'return');
  v_before := public.ride_route_minutes(p_ride_id, 'both');
  delete from public.ride_requests where ride_id = p_ride_id and request_id = p_request_id;
  v_a_out := public.ride_route_minutes(p_ride_id, 'out'); v_a_ret := public.ride_route_minutes(p_ride_id, 'return');
  v_after := public.ride_route_minutes(p_ride_id, 'both');
  v_delta := greatest(coalesce(v_before, 0) - coalesce(v_after, 0), 0);

  select case when rr2.covers_return then q.return_at end, case when rr2.covers_out then q.depart_at end
    into v_base_return, v_base_depart
  from public.ride_requests rr2 join public.requests q on q.id = rr2.request_id
  where rr2.ride_id = p_ride_id and rr2.request_id = v_base limit 1;

  v_start := v_ride.starts_at; v_end := v_ride.ends_at;
  v_new_window := v_base_depart is not null and v_ride.starts_at < v_base_depart;
  if v_new_window then
    if greatest(coalesce(v_b_out, 0) - coalesce(v_a_out, 0), 0) > 0 then
      v_start := least(v_ride.starts_at + make_interval(mins => (ceil(greatest(v_b_out - v_a_out, 0) / 15.0) * 15)::int), v_base_depart);
    end if;
    v_delta := greatest(coalesce(v_b_ret, 0) - coalesce(v_a_ret, 0), 0);
  end if;
  if v_delta > 0 then
    -- 23:59 is the capped "end of day": treat it as 24:00 so the quarter-hour arithmetic inverts apply.
    if (v_end at time zone 'Asia/Jerusalem')::time = time '23:59' then v_end := v_end + interval '1 minute'; end if;
    v_end := v_end - make_interval(mins => (ceil(v_delta / 15.0) * 15)::int);
    v_end := greatest(v_end, coalesce(v_base_return, v_end), v_start + interval '15 minutes');
    v_end := least(public._round_up_ride_end(v_start, v_end), v_ride.ends_at);
  end if;

  update public.rides set starts_at = v_start, ends_at = v_end, updated_at = now() where id = p_ride_id;
  perform public.refresh_car_turnarounds(v_ride.car_id, v_ride.week_start);

  if not exists (select 1 from public.ride_requests rr join public.rides r on r.id = rr.ride_id
                 where rr.request_id = p_request_id and r.status <> 'cancelled') then
    v_prev_sys := coalesce(nullif(current_setting('app.system_status_transition', true), ''), 'off');
    perform set_config('app.system_status_transition', 'on', true);
    update public.requests set status = 'submitted', status_reason = 'UNMERGED_BY_SADRAN' where id = p_request_id;
    perform set_config('app.system_status_transition', v_prev_sys, true);
  end if;

  if v_guest.requester_id is distinct from v_actor then
    select full_name into v_actor_name from public.profiles where id = v_actor;
    select name into v_dest_name from public.destinations where id = coalesce(v_guest.destination_id, v_ride.destination_id);
    v_route := public.route_label(v_guest.department_id, v_guest.origin_id, v_guest.origin_text, v_guest.destination_id, v_guest.destination_text);
    perform public.enqueue_notification(v_guest.requester_id, 'outcome_changed', v_ride.department_id, v_ride.week_start,
      jsonb_build_object('byName', coalesce(v_actor_name, ''), 'destination', coalesce(v_dest_name, ''),
        'route', coalesce(v_route, ''), 'day', public.day_date_label(v_ride.starts_at)),
      jsonb_build_object('variant', 'passenger_removed_you', 'ride_id', p_ride_id, 'request_id', p_request_id),
      format('unmerge:%s:%s:%s', p_ride_id, p_request_id, v_ride.version));
  end if;
end;
$$;


ALTER FUNCTION "public"."unmerge_request"("p_ride_id" "uuid", "p_request_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ride_public_notes"("p_ride_id" "uuid", "p_expected_version" integer, "p_notes" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  ride_row public.rides%rowtype;
  week_phase public.week_phase;
  clean_notes text := nullif(btrim(p_notes), '');
begin
  if not public.is_approved() then raise exception 'not_authorized'; end if;
  select * into ride_row from public.rides where id = p_ride_id for update;
  if not found or ride_row.status = 'cancelled' then raise exception 'ride_not_found'; end if;

  if not public.can_manage_week(ride_row.department_id, ride_row.week_start) then
    if not public.member_of(ride_row.department_id)
      or not public.is_week_public(ride_row.department_id, ride_row.week_start)
      or not (
        ride_row.driver_id is not distinct from (select auth.uid())
        or exists (
          select 1 from public.ride_requests rr
          join public.requests q on q.id = rr.request_id
          where rr.ride_id = ride_row.id and q.requester_id = (select auth.uid())
        )
      )
    then raise exception 'not_authorized'; end if;
  end if;

  select phase into week_phase from public.weeks
  where department_id = ride_row.department_id and week_start = ride_row.week_start
  for share;
  if week_phase = 'archived' then raise exception 'week_archived'; end if;
  if ride_row.ends_at <= now() then raise exception 'ride_in_past'; end if;
  if p_expected_version is null or ride_row.version <> p_expected_version then
    perform public.raise_stale_version();
  end if;
  if char_length(clean_notes) > 1000
    or (clean_notes is null and ride_row.driver_id is null and not ride_row.needs_driver)
  then raise exception 'invalid_ride_description'; end if;

  -- Existing version, updated_at and audit triggers remain authoritative. No ride
  -- scheduling/status/driver fields, linked requests or consent rows are changed.
  if ride_row.notes is distinct from clean_notes then
    perform set_config('app.audit_reason', 'update_ride_public_notes', true);
    update public.rides set notes = clean_notes where id = ride_row.id;
  end if;
end;
$$;


ALTER FUNCTION "public"."update_ride_public_notes"("p_ride_id" "uuid", "p_expected_version" integer, "p_notes" "text") OWNER TO "postgres";


