  select not exists (
    select 1 from jsonb_array_elements(_rules) as r
    where (r ->> 'type') not in (
      'rideType', 'distance', 'publicTransport', 'peopleServed',
      'fairness', 'submissionTime', 'flexibilityOffered', 'manualBoost'
    )
  );
$$;


