CREATE OR REPLACE FUNCTION "public"."waitlist_group_membership_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_group uuid; v_open int; v_last uuid; v_last_profile uuid;
begin
  if new.status is not distinct from old.status then return null; end if;
  if new.status in ('submitted', 'waitlisted') then return null; end if;

  select m.group_id into v_group from public.waitlist_group_members m
  where m.request_id = new.id and m.chosen is null;
  if v_group is null then return null; end if;

  delete from public.waitlist_group_members where request_id = new.id and chosen is null;

  select count(*) into v_open from public.waitlist_group_members
  where group_id = v_group and chosen is null;

  if v_open = 1 then
    select request_id, profile_id into v_last, v_last_profile from public.waitlist_group_members
    where group_id = v_group and chosen is null limit 1;
    begin
      perform public.settle_waitlist_group(v_group, array[v_last], v_last_profile);
    exception when others then
      perform set_config('app.audit_reason', 'waitlist_group_dissolved', true);
      update public.waitlist_group_members set chosen = false where group_id = v_group and chosen is null;
      update public.waitlist_groups set status = 'cancelled', resolved_at = now()
      where id = v_group and status = 'open';
      perform set_config('app.system_status_transition', 'on', true);
      update public.requests set status_reason = 'WAITLISTED_NO_CAR'
      where id = v_last and status = 'waitlisted';
      perform set_config('app.system_status_transition', 'off', true);
    end;
  elsif v_open = 0 then
    update public.waitlist_group_members set chosen = false where group_id = v_group and chosen is null;
    perform set_config('app.audit_reason', 'waitlist_group_dissolved', true);
    update public.waitlist_groups set status = 'cancelled', resolved_at = now()
    where id = v_group and status = 'open';
  else
    perform set_config('app.audit_reason', 'waitlist_group_shrunk', true);
    update public.waitlist_groups g
    set starts_at = sub.min_start, ends_at = sub.max_end
    from (select min(depart_at) as min_start, max(return_at) as max_end
          from public.waitlist_group_members where group_id = v_group and chosen is null) sub
    where g.id = v_group and g.status = 'open';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."waitlist_group_membership_sync"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."department_settings" (
    "department_id" "uuid" NOT NULL,
    "turnaround_minutes" integer DEFAULT 30 NOT NULL,
    "day_end_time" time without time zone DEFAULT '23:59:00'::time without time zone NOT NULL,
    "chauffeur_dwell_minutes" integer DEFAULT 10 NOT NULL,
    "detour_limit_minutes" integer DEFAULT 20 NOT NULL,
    "detour_limit_km" numeric(6,1) DEFAULT 15 NOT NULL,
    "open_dow" smallint DEFAULT 0 NOT NULL,
    "open_time" time without time zone DEFAULT '00:00:00'::time without time zone NOT NULL,
    "close_dow" smallint DEFAULT 3 NOT NULL,
    "close_time" time without time zone DEFAULT '12:00:00'::time without time zone NOT NULL,
    "closing_reminder_hours" integer[] DEFAULT '{24,2}'::integer[] NOT NULL,
    "publish_dow" smallint DEFAULT 3 NOT NULL,
    "publish_time" time without time zone DEFAULT '20:00:00'::time without time zone NOT NULL,
    "proposal_expiry_mode" "text" DEFAULT 'at_publish'::"text" NOT NULL,
    "proposal_expiry_hours" integer DEFAULT 24 NOT NULL,
    "auto_apply_accepted_proposals" boolean DEFAULT true NOT NULL,
    "board_start_time" time without time zone DEFAULT '06:00:00'::time without time zone NOT NULL,
    "weeks_open_ahead" smallint DEFAULT 1 NOT NULL,
    "overrides" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone,
    "updated_by" "uuid",
    "join_radius_km" numeric(5,1) DEFAULT 10 NOT NULL,
    "stop_minutes" integer DEFAULT 5 NOT NULL,
    CONSTRAINT "department_settings_close_dow_ck" CHECK ((("close_dow" >= 0) AND ("close_dow" <= 6))),
    CONSTRAINT "department_settings_expiry_mode_ck" CHECK (("proposal_expiry_mode" = ANY (ARRAY['at_publish'::"text", 'fixed_hours'::"text"]))),
    CONSTRAINT "department_settings_join_radius_km_ck" CHECK ((("join_radius_km" >= (0)::numeric) AND ("join_radius_km" <= (100)::numeric))),
    CONSTRAINT "department_settings_open_dow_ck" CHECK ((("open_dow" >= 0) AND ("open_dow" <= 6))),
    CONSTRAINT "department_settings_publish_dow_ck" CHECK ((("publish_dow" >= 0) AND ("publish_dow" <= 6))),
    CONSTRAINT "department_settings_stop_minutes_ck" CHECK ((("stop_minutes" >= 0) AND ("stop_minutes" <= 60))),
    CONSTRAINT "department_settings_turnaround_ck" CHECK (((("turnaround_minutes" % 15) = 0) AND (("turnaround_minutes" >= 0) AND ("turnaround_minutes" <= 120))))
);

