    "trip_shape" "public"."trip_shape" DEFAULT 'round_trip'::"public"."trip_shape" NOT NULL,
    "depart_dow" smallint,
    "depart_time" time without time zone,
    "return_dow" smallint,
    "return_time" time without time zone,
    "one_way_car_mode" "public"."leg_car_mode",
    "needs_car_at_destination" boolean DEFAULT true NOT NULL,
    "adults" smallint DEFAULT 1 NOT NULL,
    "child_seats" smallint DEFAULT 0 NOT NULL,
    "boosters" smallint DEFAULT 0 NOT NULL,
    "has_luggage" boolean DEFAULT false NOT NULL,
    "flex_depart_early" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_depart_late" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_return_early" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_return_late" interval DEFAULT '00:00:00'::interval NOT NULL,
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "paused_until" "date",
    "last_materialized_week" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "preferred_car_id" "uuid",
    "ride_description" "text",
    "guest_passenger_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "companion_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "source_request_id" "uuid",
    "snoozed_until_week" "date",
    "stopped_at" timestamp with time zone,
    "child_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "origin_id" "uuid",
    "origin_text" "text",
    "trip_type" "public"."trip_type" DEFAULT 'round_trip'::"public"."trip_type" NOT NULL,
    "stops" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    CONSTRAINT "request_templates_adults_ck" CHECK (("adults" >= 1)),
    CONSTRAINT "request_templates_boosters_ck" CHECK (("boosters" >= 0)),
    CONSTRAINT "request_templates_child_seats_ck" CHECK (("child_seats" >= 0)),
    CONSTRAINT "request_templates_depart_ck" CHECK ((("depart_dow" IS NULL) = ("trip_shape" = 'one_way_from'::"public"."trip_shape"))),
    CONSTRAINT "request_templates_depart_dow_ck" CHECK ((("depart_dow" IS NULL) OR (("depart_dow" >= 0) AND ("depart_dow" <= 6)))),
    CONSTRAINT "request_templates_destination_ck" CHECK ((("destination_id" IS NOT NULL) OR ("destination_text" IS NOT NULL))),
    CONSTRAINT "request_templates_flex_depart_early_ck" CHECK (("flex_depart_early" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "request_templates_flex_depart_late_ck" CHECK (("flex_depart_late" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "request_templates_flex_return_early_ck" CHECK (("flex_return_early" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "request_templates_flex_return_late_ck" CHECK (("flex_return_late" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "request_templates_one_way_mode_ck" CHECK (((("one_way_car_mode" IS NULL) = ("trip_shape" = 'round_trip'::"public"."trip_shape")) AND (("one_way_car_mode" IS NULL) OR ("one_way_car_mode" = ANY (ARRAY['relay'::"public"."leg_car_mode", 'passenger'::"public"."leg_car_mode"]))))),
    CONSTRAINT "request_templates_origin_ck" CHECK ((("origin_id" IS NOT NULL) OR ("origin_text" IS NOT NULL))),
    CONSTRAINT "request_templates_return_ck" CHECK ((("return_dow" IS NULL) = ("trip_shape" = 'one_way_to'::"public"."trip_shape"))),
    CONSTRAINT "request_templates_return_dow_ck" CHECK ((("return_dow" IS NULL) OR (("return_dow" >= 0) AND ("return_dow" <= 6)))),
    CONSTRAINT "request_templates_snoozed_until_week_sunday_ck" CHECK ((("snoozed_until_week" IS NULL) OR (EXTRACT(dow FROM "snoozed_until_week") = (0)::numeric)))
);

ALTER TABLE ONLY "public"."request_templates" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."request_templates" OWNER TO "postgres";


COMMENT ON COLUMN "public"."request_templates"."paused_until" IS 'Deprecated (2026-09-10): unused by the suggestion model; superseded by snoozed_until_week/stopped_at. Kept, not dropped, to avoid an unnecessary types regen.';



COMMENT ON COLUMN "public"."request_templates"."last_materialized_week" IS 'Deprecated (2026-09-10): materialize_templates() is now a no-op; this column is never written any more.';



COMMENT ON COLUMN "public"."request_templates"."source_request_id" IS 'The request save_request_template() last captured this template from; requests.template_id is the primary link back (this is only a fallback lookup).';



COMMENT ON COLUMN "public"."request_templates"."snoozed_until_week" IS 'Suggestions for this template resume from this week_start onward (set to the snoozed week + 7 days by snooze_request_template()); null = never snoozed / snooze elapsed.';



COMMENT ON COLUMN "public"."request_templates"."stopped_at" IS 'Soft "stop repeating" timestamp, set together with is_active=false by stop_request_template(); resume_request_template() clears both.';



COMMENT ON COLUMN "public"."request_templates"."child_ids" IS 'Named children (public.children) selected on the request this template was captured from, mirroring request_children — not re-validated against seat counts here since adults/child_seats are copied verbatim from the request that already passed that check.';



CREATE TABLE IF NOT EXISTS "public"."requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "department_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "requester_id" "uuid" NOT NULL,
    "filed_by" "uuid" NOT NULL,
    "destination_id" "uuid",
    "destination_text" "text",
    "ride_type_id" "uuid" NOT NULL,
    "trip_shape" "public"."trip_shape" DEFAULT 'round_trip'::"public"."trip_shape" NOT NULL,
    "depart_at" timestamp with time zone,
    "return_at" timestamp with time zone,
    "one_way_car_mode" "public"."leg_car_mode",
    "needs_car_at_destination" boolean DEFAULT true NOT NULL,
    "adults" smallint DEFAULT 1 NOT NULL,
    "child_seats" smallint DEFAULT 0 NOT NULL,
    "boosters" smallint DEFAULT 0 NOT NULL,
    "has_luggage" boolean DEFAULT false NOT NULL,
    "flex_depart_early" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_depart_late" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_return_early" interval DEFAULT '00:00:00'::interval NOT NULL,
    "flex_return_late" interval DEFAULT '00:00:00'::interval NOT NULL,
    "notes" "text",
    "is_late" boolean DEFAULT false NOT NULL,
    "submitted_at" timestamp with time zone,
    "status" "public"."request_status" DEFAULT 'draft'::"public"."request_status" NOT NULL,
    "status_reason" "text",
    "changed_since_solve" boolean DEFAULT false NOT NULL,
    "freed_slot_opt_out" boolean DEFAULT false NOT NULL,
    "manual_boost" numeric(6,2) DEFAULT 0 NOT NULL,
    "manual_boost_reason" "text",
    "join_ride_id" "uuid",
    "template_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "preferred_car_id" "uuid",
    "original_depart_at" timestamp with time zone,
    "original_return_at" timestamp with time zone,
    "ride_description" "text",
    "guest_passenger_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "series_id" "uuid",
    "series_index" smallint,
    "series_count" smallint,
    "origin_id" "uuid",
    "origin_text" "text",
    "trip_type" "public"."trip_type" DEFAULT 'round_trip'::"public"."trip_type" NOT NULL,
    "kept_return_at" timestamp with time zone,
    CONSTRAINT "requests_adults_ck" CHECK (("adults" >= 1)),
    CONSTRAINT "requests_boosters_ck" CHECK (("boosters" >= 0)),
    CONSTRAINT "requests_child_seats_ck" CHECK (("child_seats" >= 0)),
    CONSTRAINT "requests_depart_presence_ck" CHECK ((("depart_at" IS NOT NULL) = ("trip_shape" <> 'one_way_from'::"public"."trip_shape"))),
    CONSTRAINT "requests_depart_qh_ck" CHECK ("public"."is_quarter_hour"("depart_at")),
    CONSTRAINT "requests_destination_ck" CHECK ((("destination_id" IS NOT NULL) OR ("destination_text" IS NOT NULL))),
    CONSTRAINT "requests_flex_depart_early_ck" CHECK (("flex_depart_early" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "requests_flex_depart_late_ck" CHECK (("flex_depart_late" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "requests_flex_return_early_ck" CHECK (("flex_return_early" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "requests_flex_return_late_ck" CHECK (("flex_return_late" = ANY (ARRAY['00:00:00'::interval, '00:15:00'::interval, '00:30:00'::interval, '01:00:00'::interval, '02:00:00'::interval, '1 day'::interval]))),
    CONSTRAINT "requests_manual_boost_ck" CHECK ((("manual_boost" = (0)::numeric) OR ("manual_boost_reason" IS NOT NULL))),
    CONSTRAINT "requests_one_way_mode_ck" CHECK (((("one_way_car_mode" IS NULL) = ("trip_shape" = 'round_trip'::"public"."trip_shape")) AND (("one_way_car_mode" IS NULL) OR ("one_way_car_mode" = ANY (ARRAY['relay'::"public"."leg_car_mode", 'passenger'::"public"."leg_car_mode"]))))),
    CONSTRAINT "requests_origin_ck" CHECK ((("origin_id" IS NOT NULL) OR ("origin_text" IS NOT NULL))),
    CONSTRAINT "requests_return_after_depart_ck" CHECK ((("depart_at" IS NULL) OR ("return_at" IS NULL) OR ("return_at" > "depart_at"))),
    CONSTRAINT "requests_return_presence_ck" CHECK ((("return_at" IS NOT NULL) = ("trip_shape" <> 'one_way_to'::"public"."trip_shape"))),
    CONSTRAINT "requests_return_qh_ck" CHECK (("public"."is_quarter_hour"("return_at") OR "public"."is_same_day_end"("return_at"))),
    CONSTRAINT "requests_series_ck" CHECK (((("series_id" IS NULL) AND ("series_index" IS NULL) AND ("series_count" IS NULL)) OR (("series_id" IS NOT NULL) AND ("series_index" IS NOT NULL) AND ("series_count" IS NOT NULL) AND ("series_count" >= 2) AND ("series_index" >= 1) AND ("series_index" <= "series_count"))))
);

