    CONSTRAINT "rides_pin_reason_ck" CHECK (((NOT "is_pinned") OR ("pin_reason" IS NOT NULL))),
    CONSTRAINT "rides_planning_draft_ck" CHECK (((NOT "planning_conflict") OR ("status" = 'draft'::"public"."ride_status"))),
