    CONSTRAINT "rides_starts_qh_ck" CHECK ("public"."is_quarter_hour"("starts_at")),
    CONSTRAINT "rides_turnaround_override_minutes_check" CHECK ((("turnaround_override_minutes" >= 0) AND ("turnaround_override_minutes" <= 1440)))
);

