                    "t_1"."notes"
                   FROM ((("public"."request_templates" "t_1"
                     JOIN "public"."weeks" "w" ON ((("w"."department_id" = "t_1"."department_id") AND ("w"."phase" = 'open'::"public"."week_phase"))))
                     LEFT JOIN "public"."destinations" "dst" ON (("dst"."id" = "t_1"."destination_id")))
                     JOIN "public"."ride_types" "rt" ON (("rt"."id" = "t_1"."ride_type_id")))
                  WHERE (("t_1"."requester_id" = ( SELECT "auth"."uid"() AS "uid")) AND "t_1"."is_active" AND (("t_1"."snoozed_until_week" IS NULL) OR ("t_1"."snoozed_until_week" <= "w"."week_start")) AND (NOT (EXISTS ( SELECT 1
                           FROM "public"."requests" "q"
                          WHERE (("q"."template_id" = "t_1"."id") AND ("q"."week_start" = "w"."week_start") AND ("q"."status" <> ALL (ARRAY['withdrawn'::"public"."request_status", 'cancelled'::"public"."request_status", 'draft'::"public"."request_status"])))))))) "existing_1"
             JOIN "public"."request_templates" "t" ON (("t"."id" = "existing_1"."template_id")))
             LEFT JOIN "public"."destinations" "od" ON (("od"."id" = "t"."origin_id")))) "existing"
     JOIN "public"."request_templates" "tpl" ON (("tpl"."id" = "existing"."template_id")));


ALTER VIEW "public"."v_request_template_suggestions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_waitlist_groups" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"uuid" AS "department_id",
    NULL::"date" AS "week_start",
    NULL::"date" AS "day",
    NULL::timestamp with time zone AS "starts_at",
    NULL::timestamp with time zone AS "ends_at",
    NULL::"public"."waitlist_group_status" AS "status",
    NULL::"uuid" AS "ride_id",
    NULL::"uuid" AS "resolved_by",
    NULL::timestamp with time zone AS "resolved_at",
    NULL::integer AS "version",
    NULL::timestamp with time zone AS "created_at",
    NULL::timestamp with time zone AS "updated_at",
    NULL::"jsonb" AS "members";


ALTER VIEW "public"."v_waitlist_groups" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_week_summary" WITH ("security_invoker"='true') AS
 SELECT "q"."department_id",
    "q"."week_start",
    "rt"."code" AS "ride_type",
    "q"."status",
    "count"(*) AS "request_count"
   FROM ("public"."requests" "q"
     JOIN "public"."ride_types" "rt" ON (("rt"."id" = "q"."ride_type_id")))
  GROUP BY "q"."department_id", "q"."week_start", "rt"."code", "q"."status";


ALTER VIEW "public"."v_week_summary" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."waitlist_group_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "group_id" "uuid" NOT NULL,
    "request_id" "uuid" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "department_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "depart_at" timestamp with time zone NOT NULL,
    "return_at" timestamp with time zone NOT NULL,
    "adults" smallint DEFAULT 1 NOT NULL,
    "child_seats" smallint DEFAULT 0 NOT NULL,
    "boosters" smallint DEFAULT 0 NOT NULL,
    "destination" "text",
    "chosen" boolean,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waitlist_group_members_order_ck" CHECK (("return_at" > "depart_at"))
);

