ALTER TABLE "public"."waitlist_group_members" OWNER TO "postgres";


COMMENT ON TABLE "public"."waitlist_group_members" IS 'Participants of a waitlist group, with the request snapshot denormalized so every participant can see who else is in the discussion. chosen is null while open, true/false after resolution or cancellation.';



CREATE TABLE IF NOT EXISTS "public"."waitlist_groups" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "department_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "day" "date" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "status" "public"."waitlist_group_status" DEFAULT 'open'::"public"."waitlist_group_status" NOT NULL,
    "ride_id" "uuid",
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waitlist_groups_open_ck" CHECK ((("status" <> 'open'::"public"."waitlist_group_status") OR (("ride_id" IS NULL) AND ("resolved_at" IS NULL) AND ("resolved_by" IS NULL)))),
    CONSTRAINT "waitlist_groups_order_ck" CHECK (("ends_at" > "starts_at"))
);

ALTER TABLE ONLY "public"."waitlist_groups" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."waitlist_groups" OWNER TO "postgres";


COMMENT ON TABLE "public"."waitlist_groups" IS 'A set of overlapping round-trip requests on one published day that cannot all be served (REQ §7.3). Any participant or the Sadran resolves it with resolve_waitlist_group(); the siddur renders it as one "בדיון" block from starts_at to ends_at.';



CREATE TABLE IF NOT EXISTS "public"."week_stats" (
    "department_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "total_requests" integer DEFAULT 0 NOT NULL,
    "granted" integer DEFAULT 0 NOT NULL,
    "unmet" integer DEFAULT 0 NOT NULL,
    "cancelled" integer DEFAULT 0 NOT NULL,
    "rides" integer DEFAULT 0 NOT NULL,
    "active_hours" numeric DEFAULT 0 NOT NULL,
    "distinct_people" integer DEFAULT 0 NOT NULL,
    "computed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "capacity_hours" numeric DEFAULT 0 NOT NULL,
    CONSTRAINT "week_stats_active_hours_ck" CHECK (("active_hours" >= (0)::numeric)),
    CONSTRAINT "week_stats_cancelled_ck" CHECK (("cancelled" >= 0)),
    CONSTRAINT "week_stats_capacity_hours_ck" CHECK (("capacity_hours" >= (0)::numeric)),
    CONSTRAINT "week_stats_distinct_people_ck" CHECK (("distinct_people" >= 0)),
    CONSTRAINT "week_stats_granted_ck" CHECK (("granted" >= 0)),
    CONSTRAINT "week_stats_rides_ck" CHECK (("rides" >= 0)),
    CONSTRAINT "week_stats_total_requests_ck" CHECK (("total_requests" >= 0)),
    CONSTRAINT "week_stats_unmet_ck" CHECK (("unmet" >= 0))
);

ALTER TABLE ONLY "public"."week_stats" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."week_stats" OWNER TO "postgres";


